    private fun p2(l: MutableList<BProb>) {
        l.add(BProb(id = "s1geo_17", topic = "geo", level = 3, text = "Halle el valor de x si O es centro, arco AM ≅ arco MB, BN=NC y m∢APC=60°.", opts = listOf("45°", "53°", "60°", "30°", "37°"), vals = listOf("45", "53", "60", "30", "37"), correct = 2, check = "acos(dot([-5,-sqrt(3)],[-1/2,-3*sqrt(3)/2])/(norm([-5,-sqrt(3)])*norm([-1/2,-3*sqrt(3)/2])))*180/pi", steps = listOf("PA y PC son tangentes y ∠APC = 60°: ∠AOC = 120° y PO lo divide en dos, así que ∠AOP = 60° y OP = 2R.", "Tomamos R = 2, O en el origen y P = (−4; 0). B = (2; 0). A está a 120° del eje: A = (−1; √3). C = (−1; −√3).", "M es el punto medio del arco AB: está a 60°, M = (1; √3). N es punto medio de BC: N = (1/2; −√3/2).", "Vectores desde M: MP = (−5; −√3) y MN = (−1/2; −3√3/2). Producto punto: 5/2 + 9/2 = 7. Longitudes: √28 = 2√7 y √7.", "cos x = 7/(2√7·√7) = 1/2, así que x = 60°."), fig = "f1g_17", theory = "Dos tangentes desde un punto P son simétricas respecto a PO, y el ángulo entre ellas más el ángulo central AOC suman 180°. El ángulo entre dos vectores cumple cos θ = (u·v)/(|u||v|).", idea = "Con el ángulo de 60° se ubican A, B, C y M en la circunferencia. Luego conviene usar coordenadas.", mistake = "Pensar que x es la mitad del ángulo en P, 30°, alternativa D, sin relacionar los puntos M y N.", verify = "|MP| = √(25 + 3) = √28 y |MN| = √(1/4 + 27/4) = √7. El producto de longitudes es 14 y 7/14 = 1/2.", src = "ficha", group = "Semana 1 · Geometría", num = 17))
        l.add(BProb(id = "s1geo_18", topic = "trig", level = 2, text = "Del gráfico, halle el valor de x si tanα = 1/3 y cotβ = 5/3.", opts = listOf("1", "2", "3", "4", "5"), vals = emptyList(), correct = -1, check = "", steps = listOf("Sea h la altura del lado vertical. En el triángulo pequeño: tan α = x/h = 1/3, así que x = h/3.", "En el triángulo grande: cot β = base/h = 5/3, así que la base completa mide 5h/3.", "El tramo de la izquierda mide 5h/3 − h/3 = 4h/3, es decir 4x.", "Sin una longitud dada, x puede ser cualquier número: solo se sabe que el tramo izquierdo es 4 veces x."), fig = "f1g_18", theory = "En un triángulo rectángulo, tan es cateto opuesto entre cateto adyacente y cot es adyacente entre opuesto.", idea = "Con la altura h del triángulo se escriben x y la base completa. Pero ninguna longitud está dada.", mistake = "Elegir 1 suponiendo que la altura es 3. Ese dato no está en el enunciado ni en la figura.", verify = "Por ejemplo, con h = 3: x = 1 y la base mide 5. Con h = 6: x = 2 y la base mide 10. Ambos cumplen los datos.", warn = "A la ficha le falta un dato de longitud: con los datos dados, x no queda determinado. Lee la solución.", src = "ficha", group = "Semana 1 · Geometría", answer = "No se puede determinar con los datos dados. Solo se sabe que el tramo izquierdo de la base mide 4x.", num = 18, review = true))
        l.add(BProb(id = "s1geo_19", topic = "trig", level = 1, text = "El perímetro de un triángulo rectángulo es 90 m y la tangente de uno de sus ángulos agudos es 2,4. Halle la longitud de su hipotenusa.", opts = listOf("13 m", "39 m", "24 m", "5 m", "36 m"), vals = listOf("13", "39", "24", "5", "36"), correct = 1, check = "13*90/(5+12+13)", steps = listOf("2,4 = 24/10 = 12/5. Catetos 12k y 5k.", "Hipotenusa: √(144k² + 25k²) = √169k² = 13k.", "Perímetro: 12k + 5k + 13k = 30k = 90, así que k = 3.", "Hipotenusa: 13·3 = 39 m."), theory = "tan = cateto opuesto / cateto adyacente. Si la tangente es 12/5, los catetos son 12k y 5k y la hipotenusa 13k, por el triángulo 5, 12, 13.", idea = "2,4 = 12/5. Con eso se conocen las proporciones del triángulo.", mistake = "Responder 13 m, alternativa A, olvidando multiplicar por k = 3.", verify = "Lados 15, 36 y 39: 15 + 36 + 39 = 90 y 15² + 36² = 225 + 1296 = 1521 = 39².", trap = "13", src = "ficha", group = "Semana 1 · Geometría", num = 19, trapOpt = 0))
        l.add(BProb(id = "s1geo_20", topic = "trig", level = 2, text = "En un triángulo rectángulo ABC, recto en C, se cumple que senA·cosB = 4/9. Calcule cosA.", opts = listOf("§sqrt(5)/3", "§sqrt(5)/5", "§sqrt(5)/4", "§3/4", "§2/3"), vals = listOf("sqrt(5)/3", "sqrt(5)/5", "sqrt(5)/4", "3/4", "2/3"), correct = 0, check = "sqrt(1-(2/3)^2)", steps = listOf("En el triángulo recto en C: sen A = a/c y cos B = a/c. Son iguales.", "sen A·cos B = sen²A = 4/9, así que sen A = 2/3.", "cos A = √(1 − 4/9) = √(5/9) = √5/3."), theory = "En un triángulo rectángulo, el seno de un ángulo agudo es igual al coseno del otro: sen A = cos B. Además sen²A + cos²A = 1.", idea = "Como sen A = cos B, el dato es sen²A = 4/9.", mistake = "Responder sen A = 2/3, alternativa E, en lugar de cos A.", verify = "Con a = 2, c = 3 y b = √5: sen A = 2/3, cos B = 2/3 y su producto es 4/9. cos A = √5/3.", trap = "sqrt(4/9)", src = "ficha", group = "Semana 1 · Geometría", num = 20, trapOpt = 4))
        l.add(BProb(id = "s1geo_21", topic = "trig", level = 1, text = "Reduzca la siguiente expresión:\nE = (4sen30° + √3 tan60° − cot45°) / (cos²30° · cot37°)", opts = listOf("§sqrt(2)", "§sqrt(3)", "2", "3", "4"), vals = listOf("sqrt(2)", "sqrt(3)", "2", "3", "4"), correct = 4, check = "(4*1/2+sqrt(3)*sqrt(3)-1)/((sqrt(3)/2)^2*4/3)", steps = listOf("Numerador: 4·(1/2) + √3·√3 − 1 = 2 + 3 − 1 = 4.", "Denominador: (√3/2)²·(4/3) = (3/4)·(4/3) = 1.", "E = 4/1 = 4."), theory = "Valores notables: sen 30° = 1/2, tan 60° = √3, cot 45° = 1, cos 30° = √3/2 y cot 37° = 4/3.", idea = "Se reemplaza cada razón por su valor y se simplifica.", mistake = "Usar cot 37° = 3/4 en lugar de 4/3. El denominador sería 9/16 y E no daría ninguna alternativa.", verify = "cos²30° = 0,75 y 0,75·4/3 = 1. El denominador vale exactamente 1.", src = "ficha", group = "Semana 1 · Geometría", num = 21))
        l.add(BProb(id = "s1geo_22", topic = "trig", level = 2, text = "Si ABCD es cuadrado, calcule csc²α.", opts = listOf("14", "15", "16", "17", "18"), vals = listOf("14", "15", "16", "17", "18"), correct = 3, check = "1+(1/(1-3/4))^2", steps = listOf("En el triángulo ABE, recto en E: ∠ABE = 37°, así que ∠BAE = 53°.", "∠FAD = 90° − 53° = 37°. En el triángulo ADF, recto en D: DF/AD = tan 37° = 3/4. Con lado 4: DF = 3 y CF = 1.", "En el triángulo BCF, recto en C: cot α = BC/CF = 4/1 = 4.", "csc²α = 1 + 4² = 17."), fig = "f1g_22", theory = "Identidad: csc²α = 1 + cot²α. Triángulo notable de 37° y 53°: catetos 3 y 4.", idea = "Con el ángulo de 37° se halla dónde está F sobre CD. Luego α sale del triángulo BCF.", mistake = "Calcular cot²α = 16 y olvidar sumar 1: alternativa C.", verify = "BF = √(4² + 1²) = √17 y csc α = BF/CF = √17. Su cuadrado es 17.", trap = "(1/(1-3/4))^2", src = "ficha", group = "Semana 1 · Geometría", num = 22, trapOpt = 2))
        l.add(BProb(id = "s1alg_01", topic = "alg", level = 2, text = "Reduce la siguiente expresión:\n§M=(30^2*81^3*15^2)/(18^2*27^4)", opts = emptyList(), vals = emptyList(), correct = -1, check = "(30^2*81^3*15^2)/(18^2*27^4)", steps = listOf("Descomponemos: 30 = 2·3·5, 81 = 3⁴, 15 = 3·5, 18 = 2·3² y 27 = 3³.", "Numerador: 30² = 2²·3²·5², 81³ = 3¹² y 15² = 3²·5². Su producto es 2²·3¹⁶·5⁴.", "Denominador: 18² = 2²·3⁴ y 27⁴ = 3¹². Su producto es 2²·3¹⁶.", "Se cancelan 2² y 3¹⁶. Queda M = 5⁴ = 625."), note = "El encabezado de la ficha dice Factorización, pero este ejercicio y los siguientes son de leyes de exponentes.", theory = "Leyes de exponentes: aᵐ·aⁿ = aᵐ⁺ⁿ, aᵐ/aⁿ = aᵐ⁻ⁿ, (aᵐ)ⁿ = aᵐⁿ, a⁻ⁿ = 1/aⁿ y la raíz de índice n de aᵐ es a^(m/n). Conviene escribir cada base como producto de números primos.", idea = "Si todo se escribe con primos, los factores iguales se cancelan.", mistake = "Multiplicar las bases antes de factorizar. Se obtienen números enormes que no se simplifican a la vista.", verify = "Calculando directo: el numerador vale 900·531441·225 y el denominador 324·531441. Al dividir, 900·225/324 = 625.", src = "ficha", group = "Semana 1 · Álgebra", answer = "625", answerVal = "625", num = 1))
        l.add(BProb(id = "s1alg_02", topic = "alg", level = 2, text = "Calcula el valor de:\n§E=(2^(x+1)+2^(x+2)+2^(x+3))/(2^(x-3)+2^(x-2)+2^(x-1))", opts = emptyList(), vals = emptyList(), correct = -1, check = "(2^(x+1)+2^(x+2)+2^(x+3))/(2^(x-3)+2^(x-2)+2^(x-1))", steps = listOf("Arriba: 2ˣ·2¹ + 2ˣ·2² + 2ˣ·2³ = 2ˣ·(2 + 4 + 8) = 2ˣ·14.", "Abajo: 2ˣ·2⁻³ + 2ˣ·2⁻² + 2ˣ·2⁻¹ = 2ˣ·(1/8 + 1/4 + 1/2) = 2ˣ·7/8.", "E = 14/(7/8) = 14·8/7 = 16."), theory = "Leyes de exponentes: aᵐ·aⁿ = aᵐ⁺ⁿ, aᵐ/aⁿ = aᵐ⁻ⁿ, (aᵐ)ⁿ = aᵐⁿ, a⁻ⁿ = 1/aⁿ y la raíz de índice n de aᵐ es a^(m/n).", idea = "Se saca 2ˣ como factor común arriba y abajo. Así x desaparece.", mistake = "Sumar los exponentes del numerador como si fueran factores. Son sumandos: se saca factor común, no se multiplican.", verify = "Con x = 3: arriba 16 + 32 + 64 = 112 y abajo 1 + 2 + 4 = 7. Y 112/7 = 16.", src = "ficha", group = "Semana 1 · Álgebra", answer = "16", answerVal = "16", num = 2))
    }
    private fun p3(l: MutableList<BProb>) {
        l.add(BProb(id = "s1alg_03", topic = "alg", level = 2, text = "Si\n§a/c=surd(5,8)\ndetermina el valor de la expresión:\n§(((a^3*b)^3*c)^3)/(((c^3*b)^3*a)^3)", opts = emptyList(), vals = emptyList(), correct = -1, check = "simplify(subs((((a^3*b)^3*c)^3)/(((c^3*b)^3*a)^3),[a,b,c],[3*surd(5,8),7,3]))", steps = listOf("Numerador: (a³·b)³ = a⁹·b³. Luego a⁹·b³·c, y al cubo: a²⁷·b⁹·c³.", "Denominador: (c³·b)³ = c⁹·b³. Luego c⁹·b³·a, y al cubo: c²⁷·b⁹·a³.", "Cociente: a²⁷·b⁹·c³/(c²⁷·b⁹·a³) = a²⁴/c²⁴ = (a/c)²⁴.", "a/c es la raíz octava de 5, es decir 5^(1/8). Entonces (5^(1/8))²⁴ = 5³ = 125."), note = "En la ficha la condición y la pregunta van en una sola línea: Si a/c = raíz octava de 5, determina el valor de la expresión.", theory = "Leyes de exponentes: aᵐ·aⁿ = aᵐ⁺ⁿ, aᵐ/aⁿ = aᵐ⁻ⁿ, (aᵐ)ⁿ = aᵐⁿ, a⁻ⁿ = 1/aⁿ y la raíz de índice n de aᵐ es a^(m/n). Un producto elevado a una potencia reparte la potencia entre sus factores.", idea = "Primero se simplifica la expresión hasta que quede solo la razón a/c.", mistake = "Restar mal los exponentes y dejar b en el resultado. La b se cancela porque aparece igual arriba y abajo.", verify = "Con c = 3, b = 7 y a = 3·5^(1/8), la expresión completa da 125.", src = "ficha", group = "Semana 1 · Álgebra", answer = "125", answerVal = "125", num = 3))
        l.add(BProb(id = "s1alg_04", topic = "alg", level = 3, text = "Si\n§x^x=3\nhalla el valor de:\n§K=sqrt(x^(x^(x+1))-x^(2*x))", opts = emptyList(), vals = emptyList(), correct = -1, check = "round(1000*subs(sqrt(x^(x^(x+1))-x^(2*x)),x=fsolve(x^x=3,x=1..2)[0]))", steps = listOf("x^(x+1) = x·xˣ = 3x.", "Entonces x^(x^(x+1)) = x^(3x) = (xˣ)³ = 27.", "También x^(2x) = (xˣ)² = 9.", "K = √(27 − 9) = √18 = 3√2."), theory = "Leyes de exponentes: aᵐ·aⁿ = aᵐ⁺ⁿ, aᵐ/aⁿ = aᵐ⁻ⁿ, (aᵐ)ⁿ = aᵐⁿ, a⁻ⁿ = 1/aⁿ y la raíz de índice n de aᵐ es a^(m/n). Cuando aparece xˣ, conviene reemplazarlo por su valor.", idea = "El exponente x^(x+1) se puede escribir como x·xˣ, y xˣ vale 3.", mistake = "Pensar que x^(x^(x+1)) vale 3^(x+1). El exponente de la base x es x^(x+1), no xˣ.", verify = "Con el valor numérico x ≈ 1,8256, que cumple xˣ = 3, la expresión da 4,2426, que es 3√2.", src = "ficha", group = "Semana 1 · Álgebra", answer = "3√2, aproximadamente 4,243", answerVal = "round(1000*3*sqrt(2))", num = 4))
        l.add(BProb(id = "s1alg_05", topic = "alg", level = 3, text = "Si\n§x^x=6\ncalcula:\n§E=x^(x+x^(1+x))", opts = emptyList(), vals = emptyList(), correct = -1, check = "round(subs(x^(x+x^(1+x)),x=fsolve(x^x=6,x=1..3)[0]))", steps = listOf("x^(1+x) = x·xˣ = 6x.", "El exponente de E es x + 6x = 7x.", "E = x^(7x) = (xˣ)⁷ = 6⁷ = 279 936."), theory = "Leyes de exponentes: aᵐ·aⁿ = aᵐ⁺ⁿ, aᵐ/aⁿ = aᵐ⁻ⁿ, (aᵐ)ⁿ = aᵐⁿ, a⁻ⁿ = 1/aⁿ y la raíz de índice n de aᵐ es a^(m/n).", idea = "x^(1+x) = x·xˣ = 6x. Con eso el exponente total queda como un múltiplo de x.", mistake = "Calcular 6^(x+1) en lugar de xˣ elevado a 7. Quedaría una expresión que depende de x.", verify = "6⁷ = 6·6·6·6·6·6·6: 36, 216, 1296, 7776, 46 656 y 279 936.", src = "ficha", group = "Semana 1 · Álgebra", answer = "279936", answerVal = "279936", num = 5))
        l.add(BProb(id = "s1alg_06", topic = "alg", level = 2, text = "Luego de efectuar\n§surd(x^5*surd(x^2*sqrt(x^(-1)),3),6)\nIndicar el exponente final de \"x\".", opts = emptyList(), vals = emptyList(), correct = -1, check = "round(12*evalf(ln(subs(surd(x^5*surd(x^2*sqrt(x^(-1)),3),6),x=2))/ln(2)))", steps = listOf("Raíz más interna: √(x⁻¹) = x^(−1/2).", "Dentro de la raíz cúbica: x²·x^(−1/2) = x^(3/2). Su raíz cúbica es x^(1/2).", "Dentro de la raíz sexta: x⁵·x^(1/2) = x^(11/2).", "Raíz sexta: x^(11/12). El exponente final es 11/12."), note = "La comprobación con Giac compara 12 veces el exponente, que es 11.", theory = "Una raíz de índice n equivale a la potencia 1/n. Las raíces se resuelven de adentro hacia afuera.", idea = "Se escribe todo con exponentes fraccionarios y se va simplificando desde la raíz más interna.", mistake = "Olvidar que √(x⁻¹) tiene exponente negativo y sumar +1/2 en lugar de −1/2.", verify = "Con x = 2 el valor es 2^(11/12) ≈ 1,89, y el logaritmo en base 2 da 11/12.", src = "ficha", group = "Semana 1 · Álgebra", answer = "11/12", answerVal = "11", num = 6))
        l.add(BProb(id = "s1alg_07", topic = "alg", level = 3, text = "Al resolver y encontrar el valor de \"x\" en:\n§27^(3^(x+1))=3^(27^(x+1))\nCalcular el valor de:\n§M=6*x+10", opts = emptyList(), vals = emptyList(), correct = -1, check = "6*solve(3^(x+2)=3^(3*x+3),x)[0]+10", steps = listOf("27 = 3³. Lado izquierdo: 27^(3^(x+1)) = 3^(3·3^(x+1)) = 3^(3^(x+2)).", "Lado derecho: 27^(x+1) = 3^(3x+3), así que 3^(27^(x+1)) = 3^(3^(3x+3)).", "Igualamos los exponentes de base 3: 3^(x+2) = 3^(3x+3).", "Igualamos los exponentes de nuevo: x + 2 = 3x + 3, así que x = −1/2.", "M = 6·(−1/2) + 10 = −3 + 10 = 7."), theory = "Leyes de exponentes: aᵐ·aⁿ = aᵐ⁺ⁿ, aᵐ/aⁿ = aᵐ⁻ⁿ, (aᵐ)ⁿ = aᵐⁿ, a⁻ⁿ = 1/aⁿ y la raíz de índice n de aᵐ es a^(m/n). Si dos potencias de la misma base son iguales, sus exponentes son iguales.", idea = "Todo se lleva a base 3, dos veces: primero la base y luego los exponentes.", mistake = "Igualar solo el primer nivel de exponentes. Hay dos niveles y se igualan uno tras otro.", verify = "Con x = −1/2: 3^(x+2) = 3^(3/2) y 3^(3x+3) = 3^(3/2). Se cumple la igualdad.", src = "ficha", group = "Semana 1 · Álgebra", answer = "7", answerVal = "7", num = 7))
        l.add(BProb(id = "s1alg_08", topic = "alg", level = 3, text = "Si:\n§(2*x-1)^(2*x)=1024/(2^7*x-8^3)\ncon x ≠ 1/2, halle\n§surd(2*x+5,3)", opts = emptyList(), vals = emptyList(), correct = -1, check = "round(1000*surd(2*fsolve((2*x-1)^(2*x)=1024/(2^7*x-8^3),x=4.0000001..4.5)[0]+5,3))", steps = listOf("1024 = 2¹⁰ y 2⁷·x − 8³ = 128x − 512 = 128·(x − 4).", "La ecuación queda (2x − 1)^(2x) = 8/(x − 4).", "Si x < 4, el lado derecho es negativo y el izquierdo no puede serlo, salvo bases negativas con exponente no entero, que no existen en los reales.", "Si x > 4, el lado derecho baja desde infinito y el izquierdo sube muy rápido. Se cruzan en x ≈ 4,0000014.", "Entonces 2x + 5 ≈ 13,000003 y su raíz cúbica es aproximadamente 2,351."), note = "Si el denominador fuera 2⁷ = 128, la ecuación sería (2x − 1)^(2x) = 8, con x = 3/2 y raíz cúbica de 2x + 5 igual a 2. Es solo una hipótesis y la academia debe confirmar el enunciado.", theory = "Leyes de exponentes: aᵐ·aⁿ = aᵐ⁺ⁿ, aᵐ/aⁿ = aᵐ⁻ⁿ, (aᵐ)ⁿ = aᵐⁿ, a⁻ⁿ = 1/aⁿ y la raíz de índice n de aᵐ es a^(m/n).", idea = "Se simplifica el denominador y se busca si la ecuación tiene una solución sencilla.", mistake = "Forzar un resultado entero sin comprobar. El 2 que sale en la hipótesis de la nota no se obtiene con el enunciado tal cual.", verify = "Con x = 4,0000014: el lado izquierdo es 7,0000028^8,0000028 ≈ 5 764 8xx y el derecho 8/0,0000014 ≈ 5 714 286, valores del mismo orden que se cruzan en ese punto.", warn = "Con el enunciado tal cual, la ecuación no tiene una solución limpia. Es probable que la ficha tenga una errata en el denominador.", src = "ficha", group = "Semana 1 · Álgebra", answer = "Aproximadamente 2,351, sin valor exacto sencillo", answerVal = "2351", num = 8, review = true))
        l.add(BProb(id = "s1alg_09", topic = "alg", level = 2, text = "Resolver:\nSi\n§(3*x-1)^(3*x)=3^4\ncon x ≠ 1/3, halle x − 1", opts = emptyList(), vals = emptyList(), correct = -1, check = "when(((3*(4/3)-1)^(3*(4/3)))==81,4/3-1,-1)", steps = listOf("Buscamos 3x − 1 = 3, es decir 3x = 4.", "Entonces el exponente 3x vale 4 y el lado izquierdo es 3⁴, que es justo el lado derecho.", "Así x = 4/3.", "x − 1 = 4/3 − 1 = 1/3."), note = "La condición x ≠ 1/3 evita la base 0, que daría 0¹ = 0.", theory = "Si dos potencias son iguales, se buscan valores donde la base y el exponente coincidan con los de la otra potencia.", idea = "81 = 3⁴: el lado izquierdo se parece a 3⁴ cuando la base es 3 y el exponente es 4.", mistake = "Tomar 3x − 1 = 81 y 3x = 1 a la vez. Las dos condiciones se contradicen.", verify = "Con x = 4/3: la base es 3·(4/3) − 1 = 3, el exponente es 4 y 3⁴ = 81.", src = "ficha", group = "Semana 1 · Álgebra", answer = "1/3", answerVal = "1/3", num = 9))
        l.add(BProb(id = "s1alg_10", topic = "alg", level = 2, text = "Si\n§a^a=264\nCalcula el valor de \"3a\".", opts = emptyList(), vals = emptyList(), correct = -1, check = "round(1000*3*fsolve(a^a=264,a=3.9..4.2)[0])", steps = listOf("4⁴ = 256 y 5⁵ = 3125. Como 256 < 264 < 3125, a está entre 4 y 5, muy cerca de 4.", "Con cálculo numérico a ≈ 4,0129.", "3a ≈ 12,039."), note = "Si el dato fuera aᵃ = 256, entonces a = 4 y 3a = 12. Es solo una hipótesis y la academia debe confirmarlo.", theory = "Una ecuación como aᵃ = N rara vez se resuelve con álgebra: se compara con potencias conocidas.", idea = "264 está muy cerca de 4⁴ = 256, así que a es un poco mayor que 4.", mistake = "Responder 12 sin comprobar. Con 264, aᵃ no es una potencia exacta.", verify = "4,0129^4,0129 ≈ 264,0 con la calculadora.", warn = "Con el enunciado tal cual, a no es un número entero. Es probable que la ficha tenga una errata.", src = "ficha", group = "Semana 1 · Álgebra", answer = "3a ≈ 12,039, sin valor exacto", answerVal = "12039", num = 10, review = true))
    }
    private fun p4(l: MutableList<BProb>) {
        l.add(BProb(id = "s1alg_11", topic = "alg", level = 3, text = "Calcula el valor de \"n\" en la siguiente expresión:\n§(surd(a^(-4)*surd(b^2,1/5),1/3))^(1/6)/sqrt(surd(a^4,1/3)*b^(-6))=(b/a)^n\ncon a ≠ b", opts = emptyList(), vals = emptyList(), correct = -1, check = "round(evalf(ln(subs(((a^(-4)*(b^2)^5)^3)^(1/6)/sqrt((a^4)^3*b^(-6)),[a,b],[2,3]))/ln(3/2)))", steps = listOf("Raíz de índice 1/5 de b²: (b²)⁵ = b¹⁰.", "Numerador: dentro queda a⁻⁴·b¹⁰. La raíz de índice 1/3 da (a⁻⁴·b¹⁰)³ = a⁻¹²·b³⁰, y elevado a 1/6 queda a⁻²·b⁵.", "Denominador: raíz de índice 1/3 de a⁴ es (a⁴)³ = a¹². Multiplicado por b⁻⁶ da a¹²·b⁻⁶, y su raíz cuadrada es a⁶·b⁻³.", "Cociente: a⁻²·b⁵/(a⁶·b⁻³) = a⁻⁸·b⁸ = (b/a)⁸.", "n = 8."), note = "La raíz de índice 1/3 es una notación poco usual: se interpreta como la potencia 3.", theory = "Leyes de exponentes: aᵐ·aⁿ = aᵐ⁺ⁿ, aᵐ/aⁿ = aᵐ⁻ⁿ, (aᵐ)ⁿ = aᵐⁿ, a⁻ⁿ = 1/aⁿ y la raíz de índice n de aᵐ es a^(m/n). Una raíz de índice 1/n equivale a elevar a n.", idea = "Se resuelve de adentro hacia afuera, llevando todo a potencias de a y de b.", mistake = "Interpretar la raíz de índice 1/3 como raíz cúbica. Cambia por completo el resultado.", verify = "Con a = 2 y b = 3 ambos lados valen (3/2)⁸ = 6561/256.", src = "ficha", group = "Semana 1 · Álgebra", answer = "8", answerVal = "8", num = 11))
        l.add(BProb(id = "s1alg_12", topic = "alg", level = 2, text = "Calcula el valor de \"x\" en la expresión:\n§5^(x^2)*2^(x^2)*100^(-x)=1/10", opts = emptyList(), vals = emptyList(), correct = -1, check = "when(5^(1^2)*2^(1^2)*100^(-1)==1/10,1,-1)", steps = listOf("5^(x²)·2^(x²) = 10^(x²) y 100^(−x) = 10^(−2x).", "El lado izquierdo es 10^(x² − 2x) y el derecho 1/10 = 10⁻¹.", "x² − 2x = −1, es decir x² − 2x + 1 = 0.", "(x − 1)² = 0, así que x = 1."), theory = "Leyes de exponentes: aᵐ·aⁿ = aᵐ⁺ⁿ, aᵐ/aⁿ = aᵐ⁻ⁿ, (aᵐ)ⁿ = aᵐⁿ, a⁻ⁿ = 1/aⁿ y la raíz de índice n de aᵐ es a^(m/n). Además aᵐ·bᵐ = (a·b)ᵐ.", idea = "5 y 2 tienen el mismo exponente: se juntan en 10. Y 100 = 10².", mistake = "Pasar 100 a base 5 o 2 sin necesidad. Conviene juntar 5 y 2 en 10.", verify = "Con x = 1: 5·2·100⁻¹ = 10/100 = 1/10.", src = "ficha", group = "Semana 1 · Álgebra", answer = "1", answerVal = "1", num = 12))
        l.add(BProb(id = "s1alg_13", topic = "alg", level = 2, text = "Si\n§4^x-4^(x-1)=24\nCalcula el valor de el valor de\n§(2*x)^(x/5)", opts = emptyList(), vals = emptyList(), correct = -1, check = "simplify(subs((2*x)^(x/5),x=solve(4^x-4^(x-1)=24,x)[0]))", steps = listOf("4ˣ = 4^(x−1)·4. Entonces 4ˣ − 4^(x−1) = 4^(x−1)·(4 − 1) = 3·4^(x−1).", "3·4^(x−1) = 24, así que 4^(x−1) = 8.", "4 = 2² y 8 = 2³: 2^(2x−2) = 2³, así que 2x − 2 = 3 y x = 5/2.", "(2x)^(x/5) = 5^((5/2)/5) = 5^(1/2) = √5."), note = "El enunciado dice Calcula el valor de el valor de, tal como está en la ficha.", theory = "Leyes de exponentes: aᵐ·aⁿ = aᵐ⁺ⁿ, aᵐ/aⁿ = aᵐ⁻ⁿ, (aᵐ)ⁿ = aᵐⁿ, a⁻ⁿ = 1/aⁿ y la raíz de índice n de aᵐ es a^(m/n).", idea = "4ˣ − 4^(x−1) se factoriza sacando 4^(x−1).", mistake = "Tomar 2x = 5 y exponente x/5 = 1, y responder 5. El exponente es 1/2.", verify = "Con x = 5/2: 4^(5/2) = 32 y 4^(3/2) = 8. La diferencia es 24.", src = "ficha", group = "Semana 1 · Álgebra", answer = "√5", answerVal = "sqrt(5)", num = 13))
        l.add(BProb(id = "s1alg_14", topic = "alg", level = 2, text = "El dueño de la academia YOMI , en un local tiene como cantidad de alumnos el valor de x de:\n§Q=(5^(x+1)+5^(x+2)+5^(x+3)+5^(x+4))/(5^(x-1)+5^(x-2)+5^(x-3)+5^(x-4))\n¿Cuántos alumnos tiene?", opts = emptyList(), vals = emptyList(), correct = -1, check = "(5^(x+1)+5^(x+2)+5^(x+3)+5^(x+4))/(5^(x-1)+5^(x-2)+5^(x-3)+5^(x-4))", steps = listOf("Arriba: 5ˣ·(5 + 25 + 125 + 625) = 5ˣ·780.", "Abajo: 5ˣ·(1/5 + 1/25 + 1/125 + 1/625) = 5ˣ·156/625.", "Q = 780·625/156 = 5·625 = 3125.", "Q no depende de x. La cantidad de alumnos es 3125."), note = "El enunciado habla del valor de x, pero Q no depende de x. El único número que sale es Q = 3125.", theory = "Leyes de exponentes: aᵐ·aⁿ = aᵐ⁺ⁿ, aᵐ/aⁿ = aᵐ⁻ⁿ, (aᵐ)ⁿ = aᵐⁿ, a⁻ⁿ = 1/aⁿ y la raíz de índice n de aᵐ es a^(m/n).", idea = "Se saca 5ˣ como factor común arriba y abajo, y x desaparece.", mistake = "Intentar despejar x. La expresión da el mismo valor para cualquier x.", verify = "780/156 = 5 exacto, y 5·625 = 3125.", src = "ficha", group = "Semana 1 · Álgebra", answer = "3125 alumnos", answerVal = "3125", num = 14, review = true))
        l.add(BProb(id = "s1alg_15", topic = "alg", level = 1, text = "Efectúe.\n§M=sqrt((1/4)^(-((1/5)^(-1)))+(1/5)^(-((1/4)^(-1)))+(1/2)^(-5))", opts = emptyList(), vals = emptyList(), correct = -1, check = "sqrt((1/4)^(-((1/5)^(-1)))+(1/5)^(-((1/4)^(-1)))+(1/2)^(-5))", steps = listOf("(1/5)⁻¹ = 5, así que el primer exponente es −5. (1/4)^(−5) = 4⁵ = 1024.", "(1/4)⁻¹ = 4, así que el segundo exponente es −4. (1/5)^(−4) = 5⁴ = 625.", "(1/2)⁻⁵ = 2⁵ = 32.", "M = √(1024 + 625 + 32) = √1681 = 41."), theory = "Leyes de exponentes: aᵐ·aⁿ = aᵐ⁺ⁿ, aᵐ/aⁿ = aᵐ⁻ⁿ, (aᵐ)ⁿ = aᵐⁿ, a⁻ⁿ = 1/aⁿ y la raíz de índice n de aᵐ es a^(m/n). Elevar una fracción a −1 la invierte.", idea = "Los exponentes también tienen potencias: se resuelven primero.", mistake = "Olvidar el signo menos del exponente externo y dejar (1/4)⁵ en lugar de 4⁵.", verify = "41² = 1681.", src = "ficha", group = "Semana 1 · Álgebra", answer = "41", answerVal = "41", num = 15))
        l.add(BProb(id = "s1alg_16", topic = "alg", level = 2, text = "Reduzca.\nM = ³⁰√( ⁵√x² · ⁵√x² · ⁵√x² · …(50 factores) / √x⁵ · √x⁵ · √x⁵ · …(20 factores) )", opts = emptyList(), vals = emptyList(), correct = -1, check = "simplify(ln(subs(((x^(2/5))^50/((x^(5/2))^20))^(1/30),x=2))/ln(2))", steps = listOf("Cada factor de arriba es ⁵√x² = x^(2/5). Con 50 factores: x^(2/5·50) = x²⁰.", "Cada factor de abajo es √x⁵ = x^(5/2). Con 20 factores: x^(5/2·20) = x⁵⁰.", "Cociente: x²⁰/x⁵⁰ = x⁻³⁰.", "Raíz de índice 30: (x⁻³⁰)^(1/30) = x⁻¹ = 1/x."), note = "En el original la fracción está bajo una raíz de índice 30: arriba, 50 factores iguales a la raíz quinta de x², y abajo, 20 factores iguales a la raíz cuadrada de x⁵. La comprobación con Giac compara el exponente de x, que es −1.", theory = "Leyes de exponentes: aᵐ·aⁿ = aᵐ⁺ⁿ, aᵐ/aⁿ = aᵐ⁻ⁿ, (aᵐ)ⁿ = aᵐⁿ, a⁻ⁿ = 1/aⁿ y la raíz de índice n de aᵐ es a^(m/n). Un producto de n factores iguales a es aⁿ.", idea = "Se cuenta cuánto exponente aporta cada grupo de factores.", mistake = "Sumar 50 + 20 en lugar de multiplicar el exponente por la cantidad de factores.", verify = "Los exponentes: 2/5·50 = 20 y 5/2·20 = 50. Su resta es −30 y al dividir entre 30 queda −1.", src = "ficha", group = "Semana 1 · Álgebra", answer = "M = x⁻¹ = 1/x", answerVal = "-1", num = 16))
        l.add(BProb(id = "s1alg_17", topic = "alg", level = 2, text = "Simplifique.\n§T=surd((2^(n+1)+2^(n+2)+2^(n+3)+2^(n+4))/(2^(n-1)+2^(n-2)+2^(n-3)+2^(n-4)),5)", opts = emptyList(), vals = emptyList(), correct = -1, check = "simplify(((2^(n+1)+2^(n+2)+2^(n+3)+2^(n+4))/(2^(n-1)+2^(n-2)+2^(n-3)+2^(n-4)))^(1/5))", steps = listOf("Arriba: 2ⁿ·(2 + 4 + 8 + 16) = 2ⁿ·30.", "Abajo: 2ⁿ·(1/2 + 1/4 + 1/8 + 1/16) = 2ⁿ·15/16.", "Cociente: 30·16/15 = 32.", "T = raíz quinta de 32 = 2."), theory = "Leyes de exponentes: aᵐ·aⁿ = aᵐ⁺ⁿ, aᵐ/aⁿ = aᵐ⁻ⁿ, (aᵐ)ⁿ = aᵐⁿ, a⁻ⁿ = 1/aⁿ y la raíz de índice n de aᵐ es a^(m/n).", idea = "Se saca 2ⁿ como factor común. Luego se calcula la raíz quinta del número que queda.", mistake = "Olvidar la raíz y responder 32.", verify = "2⁵ = 32.", src = "ficha", group = "Semana 1 · Álgebra", answer = "2", answerVal = "2", num = 17))
        l.add(BProb(id = "s1alg_18", topic = "alg", level = 3, text = "Si\n§a*b=2\ny\n§b^b=2\nreduzca.\n§M=a*b^(a*b^(a*b))", opts = emptyList(), vals = emptyList(), correct = -1, check = "round(1000*4*(2/fsolve(b^b=2,b=1..2)[0]))", steps = listOf("Como ab = 2, el exponente más alto es b^(ab) = b².", "Entonces el exponente siguiente es a·b² = (a·b)·b = 2b.", "b^(2b) = (bᵇ)² = 2² = 4.", "M = a·4 = 4a. Como a = 2/b, M = 8/b.", "bᵇ = 2 no tiene solución exacta sencilla: b ≈ 1,5596, a ≈ 1,2823 y M ≈ 5,129."), note = "En la ficha la condición se escribe en una sola línea, ab = bᵇ = 2; aquí se separa en dos igualdades. En el original la torre se lee como a por b elevado a, a por b elevado a, ab. Si la base fuera el producto ab, M sería 2 elevado a 2², es decir 16. Es solo una hipótesis y la academia debe confirmarlo.", theory = "Leyes de exponentes: aᵐ·aⁿ = aᵐ⁺ⁿ, aᵐ/aⁿ = aᵐ⁻ⁿ, (aᵐ)ⁿ = aᵐⁿ, a⁻ⁿ = 1/aⁿ y la raíz de índice n de aᵐ es a^(m/n). Además (aᵐ)ⁿ = aᵐⁿ.", idea = "Con ab = 2 se baja la torre de exponentes un nivel a la vez.", mistake = "Usar bᵇ = 2 para suponer b = √2. Pero √2 elevado a √2 no vale 2.", verify = "Con esos valores: ab = 1,5596·1,2823 = 2 y bᵇ = 1,5596^1,5596 = 2.", warn = "Con el enunciado tal cual, el resultado no es limpio. La lectura de la torre de exponentes puede no ser la que la ficha pretende.", src = "ficha", group = "Semana 1 · Álgebra", answer = "M = 4a = 8/b, aproximadamente 5,129", answerVal = "5129", num = 18, review = true))
    }
    private fun p5(l: MutableList<BProb>) {
        l.add(BProb(id = "s1alg_19", topic = "alg", level = 3, text = "Resolver:\nSi\n§sqrt(x)^(sqrt(x))=2\nreduzca\n§E=sqrt(x^(sqrt(4*x)))+sqrt(x^(sqrt(9*x)))+sqrt(x^(sqrt(16*x)))", opts = emptyList(), vals = emptyList(), correct = -1, check = "round(subs(sqrt(x^(sqrt(4*x)))+sqrt(x^(sqrt(9*x)))+sqrt(x^(sqrt(16*x))),x=fsolve(t^t=2,t=1..2)[0]^2))", steps = listOf("Sea t = √x. Entonces x = t² y el dato es tᵗ = 2.", "√(4x) = 2t. x^(2t) = (t²)^(2t) = t^(4t). Su raíz cuadrada es t^(2t) = (tᵗ)² = 4.", "√(9x) = 3t. x^(3t) = t^(6t). Su raíz cuadrada es t^(3t) = (tᵗ)³ = 8.", "√(16x) = 4t. x^(4t) = t^(8t). Su raíz cuadrada es t^(4t) = (tᵗ)⁴ = 16.", "E = 4 + 8 + 16 = 28."), theory = "Leyes de exponentes: aᵐ·aⁿ = aᵐ⁺ⁿ, aᵐ/aⁿ = aᵐ⁻ⁿ, (aᵐ)ⁿ = aᵐⁿ, a⁻ⁿ = 1/aⁿ y la raíz de índice n de aᵐ es a^(m/n). Conviene un cambio de variable: t = √x.", idea = "Con t = √x el dato es tᵗ = 2 y cada raíz se vuelve una potencia de tᵗ.", mistake = "Pensar que x = 2. El dato es sobre √x elevado a √x, no sobre x.", verify = "Con el valor numérico t ≈ 1,5596, que cumple tᵗ = 2, la expresión da 28.", src = "ficha", group = "Semana 1 · Álgebra", answer = "28", answerVal = "28", num = 19))
        l.add(BProb(id = "s1alg_20", topic = "alg", level = 2, text = "Simplificar:\n§P=(7^(2*m+1)+49^(m+1))/(49^(m+1)-7^(2*m+1))", opts = emptyList(), vals = emptyList(), correct = -1, check = "(7^(2*m+1)+49^(m+1))/(49^(m+1)-7^(2*m+1))", steps = listOf("49^(m+1) = 7^(2m+2) = 7^(2m+1)·7.", "Sea u = 7^(2m+1). El numerador es u + 7u = 8u y el denominador es 7u − u = 6u.", "P = 8u/6u = 4/3."), theory = "Leyes de exponentes: aᵐ·aⁿ = aᵐ⁺ⁿ, aᵐ/aⁿ = aᵐ⁻ⁿ, (aᵐ)ⁿ = aᵐⁿ, a⁻ⁿ = 1/aⁿ y la raíz de índice n de aᵐ es a^(m/n).", idea = "49 = 7², así que todo se escribe con la misma base 7.", mistake = "Cancelar 7^(2m+1) entre sumandos como si fueran factores.", verify = "Con m = 0: 7 + 49 = 56 y 49 − 7 = 42. Y 56/42 = 4/3.", src = "ficha", group = "Semana 1 · Álgebra", answer = "4/3", answerVal = "4/3", num = 20))
        l.add(BProb(id = "s1arit_01", topic = "frac", level = 1, text = "Efectúa:\n§(1/3)^2+7/9", opts = listOf("8/9", "7/9", "9/8", "1", "9/7"), vals = listOf("8/9", "7/9", "9/8", "1", "9/7"), correct = 0, check = "(1/3)^2+7/9", steps = listOf("(1/3)² = 1/9.", "1/9 + 7/9 = 8/9."), theory = "Una fracción se calcula con denominador común. Un decimal exacto es una fracción con denominador 10, 100, 1000, …", idea = "Se eleva la fracción al cuadrado y se suma con el mismo denominador.", mistake = "Elevar solo el numerador: 1/3² = 1/9 sale igual aquí, pero con otras fracciones falla. Hay que elevar numerador y denominador.", verify = "8/9 ≈ 0,889 y 1/9 + 7/9 = 0,111 + 0,778.", letters = "abcde", src = "ficha", group = "Semana 1 · Aritmética", num = 1))
        l.add(BProb(id = "s1arit_02", topic = "frac", level = 1, text = "Calcula el valor de \"x\":\n§x+sqrt(1/25)=sqrt(16/25)", opts = listOf("1", "2", "1/2", "3/5", "5/3"), vals = listOf("1", "2", "1/2", "3/5", "5/3"), correct = 3, check = "solve(x+sqrt(1/25)=sqrt(16/25),x)[0]", steps = listOf("√(1/25) = 1/5 y √(16/25) = 4/5.", "x + 1/5 = 4/5.", "x = 4/5 − 1/5 = 3/5."), theory = "Una raíz exacta se obtiene factorizando: √(a/b) = √a/√b y la raíz cúbica de a/b es la raíz cúbica de a entre la de b.", idea = "Se calculan las dos raíces y se despeja x.", mistake = "Restar mal: 4/5 − 1/5 = 3/5, no 3.", verify = "3/5 + 1/5 = 4/5.", letters = "abcde", src = "ficha", group = "Semana 1 · Aritmética", num = 2))
        l.add(BProb(id = "s1arit_03", topic = "frac", level = 1, text = "Efectúa:\n(0,5)² + √0,64", opts = listOf("1,05", "1,10", "1,15", "1", "1,04"), vals = listOf("21/20", "11/10", "23/20", "1", "26/25"), correct = 0, check = "(1/2)^2+sqrt(16/25)", steps = listOf("(0,5)² = 0,25.", "√0,64 = 0,8, porque 0,8·0,8 = 0,64.", "0,25 + 0,8 = 1,05."), note = "Las alternativas se comprueban como fracciones: 1,05 es 21/20.", theory = "Una fracción se calcula con denominador común. Un decimal exacto es una fracción con denominador 10, 100, 1000, … Una raíz exacta se obtiene factorizando: √(a/b) = √a/√b y la raíz cúbica de a/b es la raíz cúbica de a entre la de b.", idea = "0,5 = 1/2 y 0,64 = 64/100.", mistake = "Tomar √0,64 = 0,08. La raíz de 0,64 es 0,8.", verify = "0,25 + 0,80 = 1,05.", letters = "abcde", src = "ficha", group = "Semana 1 · Aritmética", num = 3))
        l.add(BProb(id = "s1arit_04", topic = "frac", level = 2, text = "Efectúa:\n§(surd(125/64,3))^2+sqrt(100/256)", opts = listOf("33/16", "35/16", "37/16", "39/16", "41/16"), vals = listOf("33/16", "35/16", "37/16", "39/16", "41/16"), correct = 1, check = "(exact(evalf((125/64)^(1/3))))^2+sqrt(100/256)", steps = listOf("La raíz cúbica de 125/64 es 5/4. Su cuadrado es 25/16.", "√(100/256) = 10/16.", "25/16 + 10/16 = 35/16."), theory = "Una raíz exacta se obtiene factorizando: √(a/b) = √a/√b y la raíz cúbica de a/b es la raíz cúbica de a entre la de b.", idea = "Las dos raíces son exactas: 125 = 5³, 64 = 4³, 100 = 10² y 256 = 16².", mistake = "Calcular la raíz cúbica de 125/64 como 25/16, sin simplificar. Ese número es el cuadrado.", verify = "35/16 = 2,1875 y 1,5625 + 0,625.", letters = "abcde", src = "ficha", group = "Semana 1 · Aritmética", num = 4))
        l.add(BProb(id = "s1arit_05", topic = "frac", level = 2, text = "Si: P = (0,02)² − 5 × 0,3 + (0,3)²\nCalcula el valor de: P + 0,4096", opts = listOf("−1", "−2", "−3", "−4", "−5"), vals = listOf("-1", "-2", "-3", "-4", "-5"), correct = 0, check = "(2/100)^2-5*3/10+(3/10)^2+4096/10000", steps = listOf("(0,02)² = 0,0004 y (0,3)² = 0,09.", "5 × 0,3 = 1,5.", "P = 0,0004 − 1,5 + 0,09 = −1,4096.", "P + 0,4096 = −1,4096 + 0,4096 = −1."), theory = "Una fracción se calcula con denominador común. Un decimal exacto es una fracción con denominador 10, 100, 1000, …", idea = "Se calcula P y luego se suma 0,4096.", mistake = "Olvidar que 5 × 0,3 resta: sumarlo daría un número positivo.", verify = "−1,4096 + 0,4096 = −1,0000.", letters = "abcde", src = "ficha", group = "Semana 1 · Aritmética", num = 5))
        l.add(BProb(id = "s1arit_06", topic = "frac", level = 2, text = "Calcula: (0, 3)² − 2 + (0, 4)²", opts = listOf("389/225", "383/225", "387/225", "381/225", "385/225"), vals = listOf("389/225", "383/225", "387/225", "381/225", "385/225"), correct = -1, check = "(3/10)^2-2+(4/10)^2", steps = listOf("(0,3)² = 0,09 y (0,4)² = 0,16.", "0,09 − 2 + 0,16 = −1,75 = −7/4.", "Ninguna alternativa vale −7/4."), note = "Si el 3 fuera periódico, es decir 0,333…, que vale 1/3, el resultado sería (1/3)² − 2 + (0,4)² = −389/225. Eso coincide con la alternativa a salvo el signo. Es solo una hipótesis y la academia debe confirmar el enunciado.", theory = "Una fracción se calcula con denominador común. Un decimal exacto es una fracción con denominador 10, 100, 1000, …", idea = "Se calcula cada cuadrado y se suma.", mistake = "Marcar la alternativa a por el parecido del número. El valor es negativo y no coincide.", verify = "0,09 + 0,16 = 0,25 y 0,25 − 2 = −1,75.", warn = "Con el enunciado tal cual, el resultado es −7/4 y ninguna alternativa lo recoge. La ficha tiene una errata.", letters = "abcde", src = "ficha", group = "Semana 1 · Aritmética", answer = "−7/4", answerVal = "-7/4", num = 6, review = true))
    }
    private fun p6(l: MutableList<BProb>) {
        l.add(BProb(id = "s1arit_07", topic = "frac", level = 1, text = "Calcula el valor de \"x\" en:\n§x+(1/2)^2+3/4", opts = listOf("0,5", "0,6", "0,7", "0,8", "0,9"), vals = listOf("1/2", "3/5", "7/10", "4/5", "9/10"), correct = -1, check = "(1/2)^2+3/4", steps = listOf("La expresión es x + (1/2)² + 3/4 = x + 1/4 + 3/4 = x + 1.", "No hay un signo igual ni un valor a la derecha: x queda sin determinar."), theory = "Una ecuación necesita dos miembros: sin el segundo no se puede despejar x.", idea = "Los términos conocidos suman 1, pero falta el valor al que debe ser igual toda la expresión.", mistake = "Suponer un valor para el segundo miembro y elegir una alternativa sin que el enunciado la respalde.", verify = "Si la expresión fuera igual a 1,5, x = 0,5; si fuera igual a 1,6, x = 0,6. Cada alternativa corresponde a un valor distinto.", warn = "A la ficha le falta el segundo miembro de la ecuación. Con los datos dados, x no queda determinado.", letters = "abcde", src = "ficha", group = "Semana 1 · Aritmética", answer = "No se puede determinar: falta el segundo miembro de la ecuación. Los términos conocidos suman 1.", answerVal = "1", num = 7, review = true))
