        l.add(BProb(id = "s1arit_09", topic = "frac", level = 1, text = "Efectúa:\n§surd(0.027,3)-(0.2)^3", opts = listOf("0,290", "0,291", "0,292", "0,293", "0,294"), vals = listOf("290/1000", "291/1000", "292/1000", "293/1000", "294/1000"), correct = 2, check = "exact(evalf((27/1000)^(1/3)))-(1/5)^3", steps = listOf("La raíz cúbica de 0,027 es 0,3.", "(0,2)³ = 0,008.", "0,3 − 0,008 = 0,292."), note = "En la fórmula los decimales se escriben con punto; en la ficha llevan coma.", theory = "Una raíz exacta se obtiene factorizando: √(a/b) = √a/√b y la raíz cúbica de a/b es la raíz cúbica de a entre la de b.", idea = "0,027 = 27/1000 y 27 = 3³, 1000 = 10³.", mistake = "Calcular (0,2)³ = 0,06, multiplicando 0,2 por 3.", verify = "0,292 + 0,008 = 0,300.", letters = "abcde", src = "ficha", group = "Semana 1 · Aritmética", num = 9))
        l.add(BProb(id = "s1arit_10", topic = "frac", level = 2, text = "Efectúa:\n§(2/3)^2+(sqrt(16/81))^(-1)", opts = listOf("1", "2", "3", "4", "5"), vals = listOf("1", "2", "3", "4", "5"), correct = -1, check = "(2/3)^2+(sqrt(16/81))^(-1)", steps = listOf("(2/3)² = 4/9.", "√(16/81) = 4/9 y su inverso es 9/4.", "4/9 + 9/4 = 16/36 + 81/36 = 97/36 ≈ 2,69."), theory = "Un exponente −1 invierte la fracción. Una raíz exacta se obtiene factorizando: √(a/b) = √a/√b y la raíz cúbica de a/b es la raíz cúbica de a entre la de b.", idea = "Se calcula cada sumando y se suman.", mistake = "Redondear 2,69 a 3 y marcar la alternativa c. El resultado exacto no es 3.", verify = "97/36 = 2,694, que no es entero.", warn = "Con el enunciado tal cual, el resultado es 97/36 y ninguna alternativa lo recoge. La ficha tiene una errata.", letters = "abcde", src = "ficha", group = "Semana 1 · Aritmética", answer = "97/36, aproximadamente 2,69", answerVal = "97/36", num = 10, review = true))
        l.add(BProb(id = "s1arit_11", topic = "frac", level = 2, text = "Calcula el valor de la siguiente expresión:\nA = (0,5)² ÷ (0,1) + √0,64 ÷ 2 − 0,02", opts = listOf("2,88", "2,90", "2,50", "2,95", "2,80"), vals = listOf("288/100", "290/100", "250/100", "295/100", "280/100"), correct = 0, check = "(1/2)^2/(1/10)+sqrt(64/100)/2-2/100", steps = listOf("(0,5)² ÷ 0,1 = 0,25 ÷ 0,1 = 2,5.", "√0,64 ÷ 2 = 0,8 ÷ 2 = 0,4.", "A = 2,5 + 0,4 − 0,02 = 2,88."), theory = "Una fracción se calcula con denominador común. Un decimal exacto es una fracción con denominador 10, 100, 1000, … Dividir entre 0,1 es multiplicar por 10.", idea = "Se hace cada operación y se suman los resultados con signo.", mistake = "Olvidar restar 0,02 y marcar 2,90, alternativa b.", verify = "2,5 + 0,4 = 2,9 y 2,9 − 0,02 = 2,88.", trap = "290/100", letters = "abcde", src = "ficha", group = "Semana 1 · Aritmética", num = 11, trapOpt = 1))
        l.add(BProb(id = "s1arit_12", topic = "frac", level = 3, text = "Calcula el resultado de la siguiente expresión:\n§M=((((5/6-1/3)^2+1)/(1/24)))/sqrt(5/4-5/9)\ny luego da como resultado la raíz cuadrada de M.", opts = listOf("6", "7", "8", "9", "10"), vals = listOf("6", "7", "8", "9", "10"), correct = 0, check = "sqrt((((5/6-1/3)^2+1)/(1/24))/sqrt(5/4-5/9))", steps = listOf("5/6 − 1/3 = 1/2. Su cuadrado es 1/4 y 1/4 + 1 = 5/4.", "5/4 ÷ 1/24 = 5/4 · 24 = 30.", "Denominador: 5/4 − 5/9 = 45/36 − 20/36 = 25/36, y su raíz es 5/6.", "M = 30 ÷ 5/6 = 30 · 6/5 = 36.", "La raíz cuadrada de M es 6."), theory = "Una fracción se calcula con denominador común. Un decimal exacto es una fracción con denominador 10, 100, 1000, … Dividir entre una fracción es multiplicar por su inversa.", idea = "Se resuelve primero el numerador, luego el denominador y al final se divide.", mistake = "Responder M = 36, que no está entre las alternativas. La pregunta pide la raíz cuadrada de M.", verify = "6² = 36 y 36 · 5/6 = 30.", letters = "abcde", src = "ficha", group = "Semana 1 · Aritmética", num = 12))
        l.add(BProb(id = "s1arit_13", topic = "frac", level = 2, text = "Si:\n§M=(surd((36/100)/(6/10),3))^3\n§N=(surd(1/8,3)*sqrt(25/9))^2\nCalcula el valor de \"MxN\":", opts = listOf("5/12", "7/12", "9/11", "11/12", "1/12"), vals = listOf("5/12", "7/12", "9/11", "11/12", "1/12"), correct = 0, check = "((36/100)/(6/10))*(exact(evalf((1/8)^(1/3)))*sqrt(25/9))^2", steps = listOf("M = (36/100) ÷ (6/10) = 36/100 · 10/6 = 3/5.", "En N: la raíz cúbica de 1/8 es 1/2 y √(25/9) = 5/3. Su producto es 5/6 y al cuadrado 25/36.", "M × N = 3/5 · 25/36 = 75/180 = 5/12."), note = "En la ficha, la división de M está escrita con el signo ÷ entre dos fracciones.", theory = "Una raíz exacta se obtiene factorizando: √(a/b) = √a/√b y la raíz cúbica de a/b es la raíz cúbica de a entre la de b. Elevar al cubo la raíz cúbica de un número da el mismo número.", idea = "En M la raíz cúbica y el cubo se anulan. En N se calculan las raíces.", mistake = "Elevar al cubo 3/5 una segunda vez, en lugar de ver que raíz cúbica y cubo se anulan.", verify = "0,6 · 0,6944 = 0,4167 = 5/12.", letters = "abcde", src = "ficha", group = "Semana 1 · Aritmética", num = 13))
