        l.add(BProb(id = "s1arit_17", topic = "arit", level = 2, text = "Realiza la siguiente operación y expresa el resultado en notación científica con tres cifras significativas.\n(1,44 × 10⁴)(4,9 × 10⁻⁶)(2,15 × 10⁻¹²)", opts = listOf("1,52x10⁻¹¹", "1,52x10⁻¹²", "1,52x10⁻¹³", "1,52x10⁻¹⁴", "1,52x10⁻¹⁵"), vals = listOf("abs((38/25)*10^(-11)-((144/100*10^4)*(49/10*10^(-6))*(215/100*10^(-12))))<5/1000*10^(-11)", "abs((38/25)*10^(-12)-((144/100*10^4)*(49/10*10^(-6))*(215/100*10^(-12))))<5/1000*10^(-12)", "abs((38/25)*10^(-13)-((144/100*10^4)*(49/10*10^(-6))*(215/100*10^(-12))))<5/1000*10^(-13)", "abs((38/25)*10^(-14)-((144/100*10^4)*(49/10*10^(-6))*(215/100*10^(-12))))<5/1000*10^(-14)", "abs((38/25)*10^(-15)-((144/100*10^4)*(49/10*10^(-6))*(215/100*10^(-12))))<5/1000*10^(-15)"), correct = 2, check = "true", steps = listOf("1,44 · 4,9 · 2,15 = 15,1704.", "Potencias: 10⁴ · 10⁻⁶ · 10⁻¹² = 10⁻¹⁴.", "15,1704 × 10⁻¹⁴ = 1,51704 × 10⁻¹³.", "Con tres cifras significativas: 1,52 × 10⁻¹³."), note = "Las alternativas se comprueban por cercanía: la correcta es la única que se acerca al valor real con un error menor que media unidad de la última cifra.", theory = "Notación científica: a × 10ⁿ con 1 ≤ a < 10. Cada lugar que se mueve la coma hacia la izquierda suma 1 al exponente y cada lugar hacia la derecha resta 1. Al multiplicar potencias de 10 se suman los exponentes.", idea = "Se multiplican los números y las potencias por separado.", mistake = "Dejar 15,17 × 10⁻¹⁴ sin pasar a notación científica y marcar 10⁻¹⁴, alternativa d.", verify = "1,44 · 4,9 = 7,056 y 7,056 · 2,15 = 15,1704.", letters = "abcde", src = "ficha", group = "Semana 1 · Aritmética", num = 17))
        l.add(BProb(id = "s1arit_18", topic = "arit", level = 1, text = "Se sabe que una molécula de grasa mide 0,0023  m. Al analizar una muestra, se encontró 3 millones de estas moléculas. Supón que colocamos las moléculas, una a continuación de otra, formando una cadena, ¿cuántos metros mediría dicha cadena?", opts = listOf("6,9x10⁵ m", "6,9x10⁴ m", "6,9x10³ m", "6,9x10² m", "6,9x10 m"), vals = listOf("(69/10)*10^(5)==6900 and 69/10>=1 and 69/10<10", "(69/10)*10^(4)==6900 and 69/10>=1 and 69/10<10", "(69/10)*10^(3)==6900 and 69/10>=1 and 69/10<10", "(69/10)*10^(2)==6900 and 69/10>=1 and 69/10<10", "(69/10)*10^(1)==6900 and 69/10>=1 and 69/10<10"), correct = 2, check = "true", steps = listOf("3 millones = 3 000 000.", "Longitud: 0,0023 · 3 000 000 = 6900 m.", "6900 = 6,9 × 10³ m."), note = "En la ficha el exponente de las alternativas aparece sin formato, por ejemplo 6,9x103. Aquí se muestra como potencia de 10.", theory = "Notación científica: a × 10ⁿ con 1 ≤ a < 10. Cada lugar que se mueve la coma hacia la izquierda suma 1 al exponente y cada lugar hacia la derecha resta 1.", idea = "La longitud de la cadena es la longitud de una molécula por la cantidad de moléculas.", mistake = "Calcular 0,0023 · 300 000 y obtener 690, es decir 6,9×10², alternativa d.", verify = "0,0023 · 3 = 0,0069 y 0,0069 · 10⁶ = 6900.", letters = "abcde", src = "ficha", group = "Semana 1 · Aritmética", num = 18))
        l.add(BProb(id = "s1arit_19", topic = "arit", level = 3, text = "Expresa en notación científica. Muestra el resultado con dos cifras significativas.\n§((30000)^4*(0.00002)^5)/((500)^2*(25000000)*(0.0004)^3)", opts = listOf("6,5x10⁻⁷", "6,5x10⁻⁸", "6,5x10⁻⁹", "6,5x10⁻¹⁰", "6,5x10⁻¹¹"), vals = listOf("abs((13/2)*10^(-7)-((30000^4*(2/100000)^5)/(500^2*25000000*(4/10000)^3)))<5/100*10^(-7)", "abs((13/2)*10^(-8)-((30000^4*(2/100000)^5)/(500^2*25000000*(4/10000)^3)))<5/100*10^(-8)", "abs((13/2)*10^(-9)-((30000^4*(2/100000)^5)/(500^2*25000000*(4/10000)^3)))<5/100*10^(-9)", "abs((13/2)*10^(-10)-((30000^4*(2/100000)^5)/(500^2*25000000*(4/10000)^3)))<5/100*10^(-10)", "abs((13/2)*10^(-11)-((30000^4*(2/100000)^5)/(500^2*25000000*(4/10000)^3)))<5/100*10^(-11)"), correct = 2, check = "true", steps = listOf("Arriba: (3×10⁴)⁴ = 81×10¹⁶ y (2×10⁻⁵)⁵ = 32×10⁻²⁵. Producto: 2592×10⁻⁹.", "Abajo: 500² = 25×10⁴, 25 000 000 = 25×10⁶ y (4×10⁻⁴)³ = 64×10⁻¹². Producto: 100 000 000 × 10⁻⁸... = 40 000 × 10⁶ × 10⁻¹²... cuyo valor es 400.", "Cociente: 2592×10⁻⁹ ÷ 400 = 6,48×10⁻⁹.", "Con dos cifras significativas: 6,5×10⁻⁹."), note = "En la fórmula los decimales se escriben con punto; en la ficha llevan coma. Las alternativas se comprueban por cercanía.", theory = "Notación científica: a × 10ⁿ con 1 ≤ a < 10. Cada lugar que se mueve la coma hacia la izquierda suma 1 al exponente y cada lugar hacia la derecha resta 1.", idea = "Cada número se escribe en notación científica y se agrupan las potencias de 10.", mistake = "No sumar bien los exponentes de potencias de 10 al cancelar. Un error de uno cambia la alternativa.", verify = "6,48 × 10⁻⁹ redondeado a dos cifras da 6,5 × 10⁻⁹.", letters = "abcde", src = "ficha", group = "Semana 1 · Aritmética", num = 19))
        l.add(BProb(id = "s1arit_20", topic = "arit", level = 3, text = "Realiza la siguiente operación. Expresa el resultado en notación científica con tres cifras significativas.\n§(((1.5*10^(-5)-8*10^(-6))/(3*10^(-6)))*((2*10^7-5*10^8)/(4*10^3)))", opts = listOf("−2,80x10⁵", "−2,80x10⁴", "−2,80x10³", "−2,80x10²", "−2,80x10⁶"), vals = listOf("-280/100*10^(5)==((15/1000000-8/1000000)/(3/1000000))*((20000000-500000000)/4000)", "-280/100*10^(4)==((15/1000000-8/1000000)/(3/1000000))*((20000000-500000000)/4000)", "-280/100*10^(3)==((15/1000000-8/1000000)/(3/1000000))*((20000000-500000000)/4000)", "-280/100*10^(2)==((15/1000000-8/1000000)/(3/1000000))*((20000000-500000000)/4000)", "-280/100*10^(6)==((15/1000000-8/1000000)/(3/1000000))*((20000000-500000000)/4000)"), correct = 0, check = "true", steps = listOf("Primer corchete: 1,5×10⁻⁵ − 8×10⁻⁶ = 15×10⁻⁶ − 8×10⁻⁶ = 7×10⁻⁶. Dividido entre 3×10⁻⁶ da 7/3.", "Segundo corchete: 2×10⁷ − 5×10⁸ = 2×10⁷ − 50×10⁷ = −48×10⁷. Dividido entre 4×10³ da −12×10⁴.", "Producto: 7/3 · (−12×10⁴) = −28×10⁴ = −2,80×10⁵."), note = "En la fórmula el decimal 1,5 se escribe con punto; en la ficha lleva coma.", theory = "Notación científica: a × 10ⁿ con 1 ≤ a < 10. Cada lugar que se mueve la coma hacia la izquierda suma 1 al exponente y cada lugar hacia la derecha resta 1.", idea = "Cada corchete se resuelve por separado.", mistake = "Restar mal 2×10⁷ − 5×10⁸ y obtener −3×10⁷. Se deben igualar las potencias antes de restar.", verify = "−2,80 × 10⁵ = −280 000 y 7/3 · (−120 000) = −280 000.", letters = "abcde", src = "ficha", group = "Semana 1 · Aritmética", num = 20))
        l.add(BProb(id = "s1arit_21", topic = "frac", level = 1, text = "En una canasta de frutas hay 5 manzanas y 7 naranjas, 12 frutas en total. Si Pedro coge 3 frutas, ¿qué parte del total representan las frutas que quedaron?", opts = listOf("3/4", "3/5", "3/7", "3/8", "2/5"), vals = listOf("3/4", "3/5", "3/7", "3/8", "2/5"), correct = 0, check = "(12-3)/12", steps = listOf("Quedan 12 − 3 = 9 frutas.", "Parte del total: 9/12 = 3/4."), theory = "Una parte del total es lo que se toma entre el total.", idea = "Pedro coge 3 de 12, pero se pregunta por las que quedan.", mistake = "Responder 3/12 = 1/4, que es lo que cogió Pedro. Esa fracción no está entre las alternativas.", verify = "3/4 de 12 es 9.", letters = "abcde", src = "ficha", group = "Semana 1 · Aritmética", num = 21))
