        l.add(BProb(id = "s1arit_25", topic = "frac", level = 2, text = "Pedro emplea 2/5 del día para trabajar; 1/74 del día, para comer; y 3/7 del día los emplea para dormir. ¿Qué fracción del día lo dedica a otras actividades?", opts = listOf("109/840", "107/840", "109/810", "109/800", "109/830"), vals = listOf("109/840", "107/840", "109/810", "109/800", "109/830"), correct = -1, check = "1-(2/5+1/74+3/7)", steps = listOf("Con los datos tal cual: 2/5 + 1/74 + 3/7 = 1036/2590 + 35/2590 + 1110/2590 = 2181/2590.", "Otras actividades: 1 − 2181/2590 = 409/2590.", "Ninguna alternativa vale 409/2590."), note = "Si la fracción fuera 1/24, el cálculo sería 2/5 + 1/24 + 3/7 = 731/840 y quedarían 109/840, que es la alternativa a. Es muy probable que ese sea el dato correcto, pero la academia debe confirmarlo.", theory = "Una fracción se calcula con denominador común. Un decimal exacto es una fracción con denominador 10, 100, 1000, …", idea = "Lo que queda del día es 1 menos la suma de las tres partes.", mistake = "Calcular con 1/24 sin avisar del cambio. El enunciado impreso dice 1/74.", verify = "2181/2590 + 409/2590 = 1.", warn = "Con el enunciado tal cual, el resultado es 409/2590 y ninguna alternativa lo recoge. Parece que 1/74 es una errata.", letters = "abcde", src = "ficha", group = "Semana 1 · Aritmética", answer = "409/2590", answerVal = "409/2590", num = 25, review = true))
