        l.add(BProb(id = "s1arit_27", topic = "frac", level = 2, text = "Tenía S/ 900, presté los 3/10 de esa cantidad, luego gasté una cantidad igual a los 4/15 de lo que presté, finalmente, invertí una cantidad igual a los 5/9 de lo que gasté. ¿Cuánto me queda?", opts = listOf("518", "520", "525", "530", "535"), vals = listOf("518", "520", "525", "530", "535"), correct = 0, check = "900-3/10*900-4/15*(3/10*900)-5/9*(4/15*(3/10*900))", steps = listOf("Presté 3/10 de 900 = 270.", "Gasté 4/15 de 270 = 72.", "Invertí 5/9 de 72 = 40.", "Me queda 900 − 270 − 72 − 40 = 518."), theory = "Cada fracción se toma de la cantidad que indica el enunciado, no siempre del total.", idea = "Hay tres fracciones, cada una de una cantidad distinta.", mistake = "Tomar las fracciones 4/15 y 5/9 de 900. Cada una es de la cantidad anterior.", verify = "270 + 72 + 40 = 382 y 900 − 382 = 518.", letters = "abcde", src = "ficha", group = "Semana 1 · Aritmética", num = 27))
