    private fun p9(l: MutableList<BProb>) {
        l.add(BProb(id = "s1est_01", topic = "porc", level = 1, text = "En una tienda comercial, una casaca cuesta S/ 300. Si por liquidación se le aplica un descuento del 30%, ¿cuánto se paga finalmente?", opts = listOf("S/ 90", "S/ 240", "S/ 210", "S/ 270"), vals = listOf("90", "240", "210", "270"), correct = 2, check = "300*(1-30/100)", steps = listOf("Se paga 100% − 30% = 70% del precio.", "70% de 300 = 210."), theory = "Un porcentaje r% de una cantidad es r/100 de ella. Un aumento de r% multiplica por 1 + r/100 y un descuento de r% por 1 − r/100. Los cambios sucesivos se multiplican.", idea = "Con un descuento de 30% se paga 70%.", mistake = "Responder el descuento, S/ 90, alternativa a, en vez de lo que se paga.", verify = "El descuento es 90 y 300 − 90 = 210.", trap = "90", letters = "abcd", src = "ficha", group = "Semana 1 · Estadística", num = 1, trapOpt = 0))
        l.add(BProb(id = "s1est_02", topic = "porc", level = 1, text = "Luego de aplicarle un aumento del 25% al precio de una tablet, su costo final es de S/ 750. ¿Cuál era su precio original?", opts = listOf("S/ 560", "S/ 600", "S/ 580", "S/ 625"), vals = listOf("560", "600", "580", "625"), correct = 1, check = "solve(X*(1+25/100)=750,X)[0]", steps = listOf("1,25 · original = 750.", "original = 750/1,25 = 600."), theory = "Un porcentaje r% de una cantidad es r/100 de ella. Un aumento de r% multiplica por 1 + r/100 y un descuento de r% por 1 − r/100. Los cambios sucesivos se multiplican.", idea = "El precio final es 125% del original.", mistake = "Restar el 25% de 750 y obtener 562,5. El 25% es del precio original, no del final.", verify = "600 · 1,25 = 750.", letters = "abcd", src = "ficha", group = "Semana 1 · Estadística", num = 2))
        l.add(BProb(id = "s1est_03", topic = "porc", level = 1, text = "Un escritorio de oficina cuesta S/ 1200. Primero recibe un descuento del 20% y luego, sobre dicho monto rebajado, se le aplica otro descuento adicional del 15%. ¿Cuánto se paga al final?", opts = listOf("S/ 780", "S/ 840", "S/ 816", "S/ 900"), vals = listOf("780", "840", "816", "900"), correct = 2, check = "1200*(1-20/100)*(1-15/100)", steps = listOf("Primer descuento: 1200 · 0,80 = 960.", "Segundo descuento: 960 · 0,85 = 816."), theory = "Un porcentaje r% de una cantidad es r/100 de ella. Un aumento de r% multiplica por 1 + r/100 y un descuento de r% por 1 − r/100. Los cambios sucesivos se multiplican.", idea = "Cada descuento se aplica sobre el precio ya rebajado.", mistake = "Sumar los descuentos, 35%, y obtener 780, alternativa a.", verify = "Descuento único: 1 − 0,8 · 0,85 = 32%, y 1200 · 0,68 = 816.", trap = "1200*(1-35/100)", letters = "abcd", src = "ficha", group = "Semana 1 · Estadística", num = 3, trapOpt = 0))
        l.add(BProb(id = "s1est_04", topic = "porc", level = 1, text = "Una bicicleta cuesta S/ 600. Se le aplica un descuento del 20% y, posteriormente, sobre el valor ya descontado, se recarga un 15% por el servicio de ensamblaje e instalación. ¿Cuál es el precio final?", opts = listOf("S/ 552", "S/ 528", "S/ 540", "S/ 570"), vals = listOf("552", "528", "540", "570"), correct = 0, check = "600*(1-20/100)*(1+15/100)", steps = listOf("Con descuento: 600 · 0,80 = 480.", "Con recargo: 480 · 1,15 = 552."), theory = "Un porcentaje r% de una cantidad es r/100 de ella. Un aumento de r% multiplica por 1 + r/100 y un descuento de r% por 1 − r/100. Los cambios sucesivos se multiplican.", idea = "El recargo se aplica sobre el valor ya descontado.", mistake = "Restar 20% y sumar 15% sobre 600: 600 − 120 + 90 = 570, alternativa d.", verify = "El recargo es 72 y 480 + 72 = 552.", trap = "600-120+90", letters = "abcd", src = "ficha", group = "Semana 1 · Estadística", num = 4, trapOpt = 3))
        l.add(BProb(id = "s1est_05", topic = "porc", level = 2, text = "En una academia de 80 alumnos, el 60% son hombres. Si el 25% de los hombres y el 40% de las mujeres usan lentes, ¿qué porcentaje del total de alumnos usan lentes?", opts = listOf("29%", "33%", "31%", "35%"), vals = listOf("29", "33", "31", "35"), correct = 2, check = "(25/100*(60/100*80)+40/100*(40/100*80))/80*100", steps = listOf("Hombres: 60% de 80 = 48. Mujeres: 80 − 48 = 32.", "Usan lentes: 25% de 48 = 12 y 40% de 32 = 12,8. Total 24,8.", "24,8/80 = 0,31 = 31%."), theory = "Un porcentaje r% de una cantidad es r/100 de ella. Un aumento de r% multiplica por 1 + r/100 y un descuento de r% por 1 − r/100. Los cambios sucesivos se multiplican.", idea = "Se cuentan los que usan lentes entre hombres y entre mujeres por separado.", mistake = "Promediar 25% y 40%: 32,5%, que no está entre las alternativas.", verify = "0,6 · 0,25 + 0,4 · 0,4 = 0,15 + 0,16 = 0,31.", letters = "abcd", src = "ficha", group = "Semana 1 · Estadística", num = 5))
        l.add(BProb(id = "s1est_06", topic = "porc", level = 2, text = "El costo de un equipo de sonido subió un 20% y, un mes después, sobre el nuevo valor, aumentó otro 10%. Si el precio final del equipo es de S/ 792, ¿cuál era su valor inicial?", opts = listOf("S/ 580", "S/ 620", "S/ 600", "S/ 640"), vals = listOf("580", "620", "600", "640"), correct = 2, check = "solve(X*(1+20/100)*(1+10/100)=792,X)[0]", steps = listOf("Precio final = inicial · 1,32.", "inicial = 792/1,32 = 600."), theory = "Un porcentaje r% de una cantidad es r/100 de ella. Un aumento de r% multiplica por 1 + r/100 y un descuento de r% por 1 − r/100. Los cambios sucesivos se multiplican.", idea = "Los dos aumentos se multiplican: 1,2 · 1,1 = 1,32.", mistake = "Restar 30% de 792 y obtener 554,4.", verify = "600 · 1,2 = 720 y 720 · 1,1 = 792.", letters = "abcd", src = "ficha", group = "Semana 1 · Estadística", num = 6))
        l.add(BProb(id = "s1est_07", topic = "porc", level = 3, text = "Se sabe que M = X · Y³. ¿Cómo varía M si la variable X aumenta en 20% y la variable Y disminuye en 10%?", opts = listOf("Disminuye 12.58%", "Aumenta 8.24%", "Disminuye 12.52%", "Disminuye 15.40%"), vals = listOf("-1258/100", "824/100", "-1252/100", "-1540/100"), correct = 2, check = "((12/10)*(9/10)^3-1)*100", steps = listOf("Factor de X: 1,2. Factor de Y³: 0,9³ = 0,729.", "M se multiplica por 1,2 · 0,729 = 0,8748.", "Disminuye 100% − 87,48% = 12,52%."), theory = "Un porcentaje r% de una cantidad es r/100 de ella. Un aumento de r% multiplica por 1 + r/100 y un descuento de r% por 1 − r/100. Los cambios sucesivos se multiplican. Si una variable está al cubo, su factor también.", idea = "X se multiplica por 1,2 y Y³ por 0,9³.", mistake = "Olvidar el cubo y calcular 1,2 · 0,9 = 1,08, aumento de 8%, que se parece a la alternativa b.", verify = "Con X = 10 e Y = 10: M = 10000. Con X = 12 e Y = 9: 12 · 729 = 8748.", letters = "abcd", src = "ficha", group = "Semana 1 · Estadística", num = 7))
        l.add(BProb(id = "s1est_08", topic = "porc", level = 2, text = "Marina desea comprar una licuadora por lo que visita dos tiendas en las que encuentra la licuadora que quiere con un mismo precio de etiqueta (precio sin descuento), pero con las ofertas que se muestran a continuación:\n[tabla]\nSegún la información mostrada para estas ofertas, ¿cuál de las siguientes afirmaciones es correcta para la compra de Marina?", opts = listOf("Le conviene la oferta, ya sea de la tienda 1 o de la tienda 2, porque el descuento total en cada una de estas es el mismo", "Le conviene comprar en la tienda 2 porque el descuento total en la tienda 1 equivale al 54 % del precio de etiqueta y en la tienda 2 el descuento total equivale al 56 % del precio de etiqueta.", "Le conviene comprar en la tienda 1 porque el descuento total en esta tienda equivale al 46 % del precio de etiqueta y en la tienda 2 el descuento total equivale al 44 % del precio de etiqueta.", "Le conviene comprar en la tienda 2 porque el descuento total obtenido en la tienda 1 equivale a 4% y en la tienda 2 equivale a 6%"), vals = listOf("(1-60/100*90/100==1-70/100*80/100)", "(1-60/100*90/100==54/100 and 1-70/100*80/100==56/100)", "(1-60/100*90/100==46/100 and 1-70/100*80/100==44/100)", "(1-60/100*90/100==4/100 and 1-70/100*80/100==6/100)"), correct = 2, check = "true", steps = listOf("Tienda 1: se paga 0,60 · 0,90 = 0,54, es decir 54%. El descuento total es 46%.", "Tienda 2: se paga 0,70 · 0,80 = 0,56. El descuento total es 44%.", "Conviene la tienda 1, con 46% frente a 44%."), note = "En la ficha las ofertas son dos carteles; aquí sus datos están en la tabla. Es el mismo problema que el 14 del examen 2024.", theory = "Un porcentaje r% de una cantidad es r/100 de ella. Un aumento de r% multiplica por 1 + r/100 y un descuento de r% por 1 − r/100. Los cambios sucesivos se multiplican.", idea = "Se calcula qué fracción del precio de etiqueta se paga en cada tienda.", mistake = "Sumar 40% + 10% = 30% + 20%, como en la alternativa a.", verify = "Con una licuadora de S/ 100: en la tienda 1 se paga 54 y en la tienda 2, 56.", letters = "abcd", src = "ficha", group = "Semana 1 · Estadística", table = listOf(listOf("", "Oferta en tienda 1", "Oferta en tienda 2"), listOf("Descuento en todo electrodomésticos", "40 %", "30 %"), listOf("Descuento adicional pagando en efectivo", "+10 %", "+20 %")), num = 8))
