    private fun p10(l: MutableList<BProb>) {
        l.add(BProb(id = "s1est_09", topic = "porc", level = 2, text = "Said posee un cupón con el 15% de descuento sobre cualquier compra. Al ingresar a una tienda, ve un abrigo que ya presenta un descuento automático del 20%. Si Said aplica su cupón al comprar dicho abrigo, ¿qué porcentaje de descuento total obtendrá?", opts = listOf("32%", "28%", "35%", "30%"), vals = listOf("32", "28", "35", "30"), correct = 0, check = "(1-(85/100)*(80/100))*100", steps = listOf("Se paga 0,80 · 0,85 = 0,68.", "Descuento total: 100% − 68% = 32%."), theory = "Un porcentaje r% de una cantidad es r/100 de ella. Un aumento de r% multiplica por 1 + r/100 y un descuento de r% por 1 − r/100. Los cambios sucesivos se multiplican.", idea = "Se paga 80% con el descuento automático y 85% con el cupón.", mistake = "Sumar 15% + 20% = 35%, alternativa c.", verify = "Con S/ 100: 80 y luego 68.", trap = "35", letters = "abcd", src = "ficha", group = "Semana 1 · Estadística", num = 9, trapOpt = 2))
