        l.add(BProb(id = "s1est_11", topic = "est", level = 1, text = "En una comunidad vecinal se realizó una encuesta sobre la cantidad de integrantes que conforman cada núcleo familiar, obteniendo la siguiente tabla:\n[tabla]\n¿Cuántas familias componen en total la comunidad vecinal y cuántas tienen de 7 a más integrantes?", opts = listOf("600 y 120", "600 y 80", "550 y 120", "600 y 230"), vals = listOf("[600,120]", "[600,80]", "[550,120]", "[600,230]"), correct = 0, check = "[120+250+110+80+40,80+40]", steps = listOf("Total: 120 + 250 + 110 + 80 + 40 = 600 familias.", "De 7 a más integrantes: 80 + 40 = 120 familias."), note = "En la ficha la segunda alternativa está rotulada d por error. Aquí se muestra como b.", theory = "En una tabla de frecuencias, el total es la suma de las frecuencias y los que están en un grupo o más se suman.", idea = "De 7 a más integrantes son los dos últimos grupos: [7 - 9> y [9 - 11>.", mistake = "Contar solo el grupo [7 - 9> y obtener 80, alternativa b.", verify = "120 + 250 + 110 = 480 y 600 − 480 = 120.", trap = "[600,80]", letters = "abcd", src = "ficha", group = "Semana 1 · Estadística", table = listOf(listOf("Composición (N° integrantes)", "N° de familias"), listOf("[1 - 3>", "120"), listOf("[3 - 5>", "250"), listOf("[5 - 7>", "110"), listOf("[7 - 9>", "80"), listOf("[9 - 11>", "40")), num = 11, trapOpt = 1))
