        l.add(BProb(id = "s2geo_02", topic = "geo", level = 2, text = "Halle el valor de x.", opts = listOf("100°", "25°", "10°", "30°", "50°"), vals = listOf("100", "25", "10", "30", "50"), correct = 4, check = "(2*20+2*30)/2", steps = listOf("∠BAC = 20° es inscrito: arco BC = 40°.", "∠DAE = 30° es inscrito: arco DE = 60°.", "x se forma con las cuerdas BE y CD, y abarca los arcos BC y DE: x = (40° + 60°)/2 = 50°."), fig = "f2g_02", theory = "Un ángulo inscrito mide la mitad del arco que abarca; un ángulo central mide lo mismo que su arco. El ángulo formado por dos cuerdas que se cortan dentro del círculo mide la semisuma de los arcos que abarcan él y su opuesto.", idea = "Con los ángulos inscritos en A se obtienen los arcos BC y DE, que son justamente los que abarca x.", mistake = "Promediar directamente los ángulos 20° y 30°: 25°, alternativa B. Hay que usar los arcos, que son el doble.", verify = "Los arcos son el doble de los ángulos en A: 40° y 60°. Su semisuma es 50°.", trap = "(20+30)/2", src = "ficha", group = "Semana 2 · Geometría", num = 2, trapOpt = 1))
        l.add(BProb(id = "s2geo_03", topic = "geo", level = 3, text = "Halle el valor de x si O es centro y T es punto de tangencia.", opts = listOf("10°", "15°", "18°", "12°", "20°"), vals = listOf("10", "15", "18", "12", "20"), correct = 2, check = "solve(t=90-(180-6*t),t)[0]", steps = listOf("Sea arco TB = b. Como AB es diámetro, arco AT = 180° − b.", "∠TBA = 3x es inscrito y abarca el arco AT: 3x = (180° − b)/2, así que b = 180° − 6x.", "En el punto exterior, la tangente y la secante forman x = (arco AT − arco TB)/2 = (180° − 2b)/2 = 90° − b.", "Reemplazamos: x = 90° − (180° − 6x) = 6x − 90°, así que 5x = 90° y x = 18°."), fig = "f2g_03", theory = "Un ángulo inscrito mide la mitad del arco que abarca; un ángulo central mide lo mismo que su arco. El ángulo exterior formado por una tangente y una secante mide la semidiferencia de los arcos que abarca.", idea = "Los dos ángulos dependen de los arcos AT y TB, que juntos forman la semicircunferencia.", mistake = "Usar la suma de arcos en lugar de la diferencia para el ángulo exterior.", verify = "Con x = 18°: b = 72°, arco AT = 108°. 3x = 54° = 108°/2 y x = (108 − 72)/2 = 18°.", src = "ficha", group = "Semana 2 · Geometría", num = 3))
        l.add(BProb(id = "s2geo_04", topic = "geo", level = 2, text = "Halle el valor de x si O es centro.", opts = listOf("45°", "18°", "72°", "36°", "63°"), vals = listOf("45", "18", "72", "36", "63"), correct = 4, check = "(180-(90-2*18))/2", steps = listOf("∠DBA = 18° es inscrito: arco AD = 36°, así que ∠AOD = 36°.", "OC es perpendicular a AB: ∠AOC = 90°, así que ∠DOC = 90° − 36° = 54°.", "OD = OC, porque son radios: el triángulo DOC es isósceles. x = (180° − 54°)/2 = 63°."), fig = "f2g_04", theory = "Un ángulo inscrito mide la mitad del arco que abarca; un ángulo central mide lo mismo que su arco. Los radios son iguales, así que un triángulo con dos radios como lados es isósceles.", idea = "Con el ángulo de 18° se halla el arco AD; con él, el ángulo DOC; y el triángulo DOC es isósceles.", mistake = "Responder el ángulo AOD = 36°, alternativa D.", verify = "En el triángulo DOC: 54° + 63° + 63° = 180°.", trap = "2*18", src = "ficha", group = "Semana 2 · Geometría", num = 4, trapOpt = 3))
        l.add(BProb(id = "s2geo_05", topic = "geo", level = 2, text = "En el trapecio rectángulo circunscriptible, un ángulo interno mide 30° y su altura mide 4. Calcule el perímetro de la región trapecial.", opts = listOf("24", "16", "18", "20", "28"), vals = listOf("24", "16", "18", "20", "28"), correct = 0, check = "2*(4+4/sin(pi/6))", steps = listOf("El lado perpendicular a las bases mide igual que la altura: 4.", "El otro lado forma 30° con la base mayor, y la altura es el cateto opuesto a 30°: ese lado mide 2·4 = 8.", "Por Pitot: suma de bases = suma de lados no paralelos = 4 + 8 = 12.", "Perímetro: 12 + 12 = 24."), theory = "Teorema de Pitot: en un cuadrilátero circunscriptible, la suma de dos lados opuestos es igual a la suma de los otros dos. Triángulo de 30° y 60°: el cateto opuesto a 30° es la mitad de la hipotenusa.", idea = "En el trapecio rectángulo, un lado no paralelo es la altura. El otro se halla con el ángulo de 30°.", mistake = "Olvidar Pitot y sumar solo los lados conocidos: 4 + 8 = 12, que no está entre las opciones.", verify = "Perímetro = 2·(suma de lados no paralelos) = 2·12 = 24.", src = "ficha", group = "Semana 2 · Geometría", num = 5))
        l.add(BProb(id = "s2geo_06", topic = "geo", level = 2, text = "En la figura, halle AB si A es punto de tangencia, O es centro, BE = 1 y CD = 8.", opts = listOf("10°", "15°", "12°", "20°", "18°"), vals = emptyList(), correct = -1, check = "", steps = listOf("La figura muestra la tangente BA y la secante BCD. No hay ningún punto E.", "Si se toma BC = 1, la secante entera es BD = 1 + 8 = 9.", "Teorema de la tangente: AB² = BC·BD = 1·9 = 9, así que AB = 3.", "Las alternativas están en grados, pero AB es una longitud. Ninguna puede ser la respuesta."), fig = "f2g_06", theory = "Teorema de la tangente: si desde un punto exterior se trazan una tangente y una secante, el cuadrado de la tangente es igual al producto de la secante entera por su parte exterior.", idea = "En la figura no hay punto E. Si el dato BE = 1 se refiere a BC, se aplica el teorema de la tangente desde B.", mistake = "Elegir una alternativa en grados para una longitud.", verify = "Con AB = 3: 3² = 9 = 1·9.", warn = "La ficha tiene dos errores: la figura no tiene punto E y las alternativas están en grados aunque se pide una longitud.", src = "ficha", group = "Semana 2 · Geometría", answer = "AB = 3, si BE se refiere a BC. Ninguna alternativa es una longitud.", num = 6, review = true))
