    private fun p13(l: MutableList<BProb>) {
        l.add(BProb(id = "s2geo_07", topic = "geo", level = 3, text = "Halle el valor de x si T es punto de tangencia y O es centro.", opts = listOf("75°", "53°", "45°", "30°", "60°"), vals = listOf("75", "53", "45", "30", "60"), correct = 4, check = "180/3", steps = listOf("Llamamos K a la esquina recta, P al punto de la derecha en la circunferencia, Q al de abajo y S al punto donde QO corta a TP.", "En el triángulo TKP, recto en K: ∠KTP = 90° − x. Por tangente y cuerda, ∠TQP = ∠KTP = 90° − x.", "En P, sobre la recta vertical: x + ∠TPQ + β = 180°, así que ∠TPQ = 180° − x − β. Entonces ∠QTP = 180° − (90° − x) − (180° − x − β) = 2x + β − 90°.", "OT es perpendicular a la tangente y el triángulo TOQ es isósceles: ∠TQO = ∠QTO = 90° − ∠TPQ = x + β − 90°.", "2β es ángulo exterior del triángulo QST en S: 2β = ∠QTS + ∠TQS = (2x + β − 90°) + (x + β − 90°) = 3x + 2β − 180°.", "β se cancela: 3x = 180° y x = 60°."), fig = "f2g_07", theory = "Un ángulo inscrito mide la mitad del arco que abarca; un ángulo central mide lo mismo que su arco. El ángulo entre una tangente y una cuerda mide lo mismo que el ángulo inscrito que abarca el mismo arco. El radio al punto de tangencia es perpendicular a la tangente.", idea = "Los ángulos del triángulo TQP y el ángulo exterior en S se escriben en función de x y β. Al final β se cancela.", mistake = "Pensar que hace falta conocer β. El valor de β se cancela.", verify = "En la figura, la cuerda TP forma con la vertical un ángulo de unos 58°, cerca de 60°, como se obtuvo.", src = "ficha", group = "Semana 2 · Geometría", num = 7))
        l.add(BProb(id = "s2geo_08", topic = "geo", level = 3, text = "Dadas las semicircunferencias, halle el valor de x si A y B son puntos de tangencia.", opts = listOf("60°", "75°", "45°", "90°", "82°"), vals = listOf("60", "75", "45", "90", "82"), correct = 3, check = "180-p/2-(90-p/2)", steps = listOf("Sea φ el ángulo que forman O₁A y O₂B con la recta de los diámetros, medido hacia la derecha. Son iguales porque ambos son perpendiculares a la misma tangente.", "Sea P el extremo izquierdo del diámetro grande. El triángulo O₁PA es isósceles y su ángulo en O₁ es 180° − φ. Entonces ∠APO₁ = φ/2.", "Sea Q el extremo derecho del diámetro pequeño. El triángulo O₂QB es isósceles y su ángulo en O₂ es φ. Entonces ∠BQO₂ = 90° − φ/2.", "En el triángulo PVQ, con V el vértice de arriba: x = 180° − φ/2 − (90° − φ/2) = 90°."), fig = "f2g_08", theory = "El radio al punto de tangencia es perpendicular a la tangente. En un triángulo isósceles los ángulos de la base son iguales.", idea = "Los radios O₁A y O₂B son perpendiculares a la misma recta tangente, así que son paralelos y forman el mismo ángulo φ con el diámetro.", mistake = "Medir el ángulo a ojo en la figura. Hay que demostrarlo con los radios paralelos.", verify = "El resultado no depende de φ: para cualquier par de semicircunferencias así, el ángulo es recto.", src = "ficha", group = "Semana 2 · Geometría", num = 8))
        l.add(BProb(id = "s2geo_09", topic = "geo", level = 3, text = "Halle el valor de x si A, B y C son puntos de tangencia.", opts = listOf("16°", "18°", "15°", "10°", "12°"), vals = listOf("16", "18", "15", "10", "12"), correct = 4, check = "solve(180-4*t=(180+7*t)/2,t)[0]", steps = listOf("Por la figura, el ángulo marcado 7x es exterior en D: ∠ADC = 180° − 7x. Y 4x es exterior en B: ∠ABC = 180° − 4x.", "Sea t la tangente común en B. El ángulo entre t y BA es igual al ángulo DAB, porque ambos son ángulos semiinscritos del arco AB. Igual con C: el ángulo entre t y BC es igual a ∠DCB.", "Entonces ∠ABC = ∠DAB + ∠DCB.", "En el cuadrilátero DABC: ∠ADC + ∠DAB + ∠ABC + ∠DCB = 360°, es decir (180° − 7x) + 2·∠ABC = 360°, así que ∠ABC = (180° + 7x)/2.", "Igualamos: 180° − 4x = (180° + 7x)/2, de donde 360° − 8x = 180° + 7x y x = 12°."), fig = "f2g_09", theory = "El ángulo entre una tangente y una cuerda mide lo mismo que el ángulo inscrito del arco que abarca. En un cuadrilátero los ángulos suman 360°.", idea = "La tangente común en B separa el ángulo ABC en dos partes que coinciden con los ángulos en A y en C.", mistake = "Suponer que el ángulo ABC es recto, como cuando la tangente es común a las dos circunferencias. Aquí las tangentes por A y por C son distintas.", verify = "Con x = 12°: ∠ABC = 132° y ∠ADC = 96°. Además (180 + 84)/2 = 132.", src = "ficha", group = "Semana 2 · Geometría", num = 9))
        l.add(BProb(id = "s2geo_10", topic = "geo", level = 2, text = "En la semicircunferencia mostrada, halle el valor de x.", opts = listOf("60°", "70°", "80°", "90°", "50°"), vals = listOf("60", "70", "80", "90", "50"), correct = 2, check = "2*130-180", steps = listOf("AD es diámetro: el arco de abajo, de A a D, mide 180°.", "∠ABC = 130° es inscrito y abarca el arco ADC, sin pasar por B: 180° + x.", "130° = (180° + x)/2, así que 260° = 180° + x y x = 80°."), fig = "f2g_10", theory = "Un ángulo inscrito mide la mitad del arco que abarca; un ángulo central mide lo mismo que su arco.", idea = "∠ABC abarca el arco que va de A a C pasando por abajo, es decir 180° más el arco CD.", mistake = "Calcular 180° − 130° = 50°, alternativa E, como si B formara un ángulo llano.", verify = "(180 + 80)/2 = 130°.", trap = "180-130", src = "ficha", group = "Semana 2 · Geometría", num = 10, trapOpt = 4))
        l.add(BProb(id = "s2geo_11", topic = "geo", level = 1, text = "En la figura se tiene una circunferencia inscrita. Halle el valor de x.", opts = listOf("6", "2", "3", "4", "5"), vals = listOf("6", "2", "3", "4", "5"), correct = 4, check = "(12+11+13)/2-13", steps = listOf("Semiperímetro: p = (12 + 11 + 13)/2 = 18.", "Desde el vértice de arriba, la tangente mide p − (lado opuesto) = 18 − 13 = 5.", "x = 5."), fig = "f2g_11", theory = "Los dos segmentos tangentes trazados desde un mismo punto a una circunferencia son iguales. En un triángulo con circunferencia inscrita, la tangente desde un vértice mide el semiperímetro menos el lado opuesto.", idea = "x es el segmento tangente desde el vértice de arriba, y el lado opuesto a ese vértice es la base de 13.", mistake = "Restar el lado equivocado: 18 − 12 = 6, alternativa A.", verify = "Tangentes: desde arriba 5, desde la izquierda 12 − 5 = 7 y desde la derecha 11 − 5 = 6. Base: 7 + 6 = 13.", trap = "(12+11+13)/2-12", src = "ficha", group = "Semana 2 · Geometría", num = 11, trapOpt = 0))
        l.add(BProb(id = "s2geo_12", topic = "geo", level = 3, text = "Halle el valor de x si O es centro.", opts = listOf("37°", "30°", "45°", "60°", "53°"), vals = listOf("37", "30", "45", "60", "53"), correct = 0, check = "round(evalf(90-2*asin(1/sqrt(5))*180/pi))", steps = listOf("Los dos lados que salen de O son radios: el triángulo es isósceles. El ángulo en O es 4α y los de la base miden x = 90° − 2α.", "La ceviana desde O divide la base en 11 y 5. En los dos triángulos que se forman, la ceviana es común y los ángulos de la base son iguales.", "Por ley de senos: 11/sen 3α = 5/sen α, así que sen 3α/sen α = 11/5.", "3 − 4 sen²α = 11/5, de donde sen²α = 1/5 y sen α = 1/√5.", "Entonces tan α = 1/2 y 2α es el ángulo del notable 3, 4, 5 con tangente 4/3: 2α = 53°. x = 90° − 53° = 37°."), fig = "f2g_12", theory = "Ley de senos. Identidad sen 3α = 3 sen α − 4 sen³α. Triángulo notable de 37° y 53°.", idea = "Los extremos de la cuerda están en la circunferencia: el triángulo es isósceles y sus ángulos de la base son x. Con la ley de senos se relacionan 11 y 5 con 3α y α.", mistake = "Quedarse con 2α = 53° y responder 53°, alternativa E.", verify = "tan 2α = 2·(1/2)/(1 − 1/4) = 4/3, que corresponde a 53°. 90° − 53° = 37°.", trap = "90-round(evalf(90-2*asin(1/sqrt(5))*180/pi))", src = "ficha", group = "Semana 2 · Geometría", num = 12, trapOpt = 4))
        l.add(BProb(id = "s2geo_13", topic = "geo", level = 2, text = "Halle el valor de x si I es incentro del triángulo ABC y CD=CE.", opts = listOf("80°", "60°", "40°", "30°", "20°"), vals = listOf("80", "60", "40", "30", "20"), correct = 2, check = "90-(180-80)/2", steps = listOf("CD = CE: en el triángulo CDE, ∠CDE = ∠CED = (180° − C)/2 = 90° − C/2.", "∠ADI es el suplemento de ∠CDE: ∠ADI = 90° + C/2.", "AI es bisectriz: ∠DAI = A/2.", "En el triángulo AID: x = 180° − A/2 − (90° + C/2) = 90° − (A + C)/2.", "A + C = 180° − 80° = 100°, así que x = 90° − 50° = 40°."), fig = "f2g_13", theory = "El incentro está en las bisectrices: AI divide al ángulo A en dos iguales. En un triángulo isósceles los ángulos de la base son iguales.", idea = "El triángulo CDE es isósceles. Con su ángulo en D y la mitad de A se halla x en el triángulo AID.", mistake = "Confundir x con el ángulo B, 80°, alternativa A. El 80° está en B, no en I.", verify = "El resultado no depende de cómo se repartan A y C: solo de que A + C = 100°.", src = "ficha", group = "Semana 2 · Geometría", num = 13))
        l.add(BProb(id = "s2geo_14", topic = "geo", level = 1, text = "En un triángulo rectángulo de hipotenusa igual a 30, halle la distancia del baricentro al circuncentro.", opts = listOf("15", "10", "9", "6", "5"), vals = listOf("15", "10", "9", "6", "5"), correct = 4, check = "30/2/3", steps = listOf("El circuncentro O es el punto medio de la hipotenusa.", "La mediana desde el ángulo recto mide la mitad de la hipotenusa: 15.", "El baricentro G está en esa mediana, a un tercio de ella desde O: GO = 15/3 = 5."), theory = "En un triángulo rectángulo el circuncentro es el punto medio de la hipotenusa, y la mediana a la hipotenusa mide la mitad de ella. El baricentro está a un tercio de cada mediana, contado desde el lado.", idea = "El circuncentro y el baricentro están en la misma mediana: la que va del ángulo recto al punto medio de la hipotenusa.", mistake = "Tomar los dos tercios de la mediana: 10, alternativa B. Esa es la distancia del vértice al baricentro.", verify = "Desde el vértice del ángulo recto hasta G hay 10, y de G a O hay 5. Total 15.", trap = "2*15/3", src = "ficha", group = "Semana 2 · Geometría", num = 14, trapOpt = 1))
    }
    private fun p14(l: MutableList<BProb>) {
        l.add(BProb(id = "s2geo_15", topic = "geo", level = 1, text = "Halle el valor de x si H es ortocentro del triángulo ABC.", opts = listOf("26,5°", "15°", "30°", "60°", "37°"), vals = listOf("53/2", "15", "30", "60", "37"), correct = 2, check = "solve(5*t=180-t,t)[0]", steps = listOf("AH y CH son alturas: AH es perpendicular a BC y CH es perpendicular a AB.", "En el cuadrilátero que forman B, los pies de las alturas y H, dos ángulos son rectos: ∠AHC + ∠B = 180°.", "5x + x = 180°, así que x = 30°."), fig = "f2g_15", theory = "Propiedad del ortocentro: en un triángulo acutángulo, el ángulo AHC es el suplemento del ángulo B, es decir ∠AHC = 180° − ∠B.", idea = "El ángulo en H y el ángulo en B suman 180°.", mistake = "Pensar que ∠AHC = 2∠B, como en el circuncentro. Eso da 5x = 2x, que no tiene solución positiva.", verify = "∠AHC = 150° y ∠B = 30°. Suman 180°.", src = "ficha", group = "Semana 2 · Geometría", num = 15))
        l.add(BProb(id = "s2geo_16", topic = "geo", level = 2, text = "Halle el valor de x si O es circuncentro del triángulo ABC.", opts = listOf("9°", "12°", "10°", "15°", "13°"), vals = listOf("9", "12", "10", "15", "13"), correct = 2, check = "solve(t=(180-16*t)/2,t)[0]", steps = listOf("∠AOC = 2·8x = 16x.", "OA = OC: en el triángulo AOC los ángulos de la base son iguales, ∠OCA = ∠OAC = x.", "16x + x + x = 180°, así que x = 10°."), fig = "f2g_16", theory = "Propiedad del circuncentro: ∠AOC = 2∠B. Además OA = OC, porque son radios de la circunferencia circunscrita.", idea = "El triángulo AOC es isósceles y su ángulo en O es el doble del ángulo B.", mistake = "Tomar ∠AOC = 8x en lugar de 16x. Daría x = 18°, que no está.", verify = "∠AOC = 160° y 160 + 10 + 10 = 180.", src = "ficha", group = "Semana 2 · Geometría", num = 16))
        l.add(BProb(id = "s2geo_17", topic = "geo", level = 2, text = "Halle el valor de x si E es excentro del triángulo ABC.", opts = listOf("40°", "50°", "60°", "80°", "70°"), vals = listOf("40", "50", "60", "80", "70"), correct = 3, check = "180-(180-2*30-2*40)/2-2*40", steps = listOf("E está frente al lado BC: es el excentro relativo a BC. AE es bisectriz de A.", "∠AEB = C/2 = 30°, así que C = 60°. ∠AEC = B/2 = 40°, así que B = 80°.", "A = 180° − 80° − 60° = 40°, y ∠BAD = 20°.", "En el triángulo ABD: x = ∠ADB = 180° − 20° − 80° = 80°."), fig = "f2g_17", theory = "Si E es el excentro opuesto a A: ∠AEB = C/2 y ∠AEC = B/2. Además AE es bisectriz del ángulo A.", idea = "Con los ángulos en E se obtienen B y C; luego A, y x sale del triángulo ABD.", mistake = "Responder el ángulo A = 40°, alternativa A.", verify = "∠ADC = 100° y en el triángulo ADC: 20 + 100 + 60 = 180.", trap = "180-2*30-2*40", src = "ficha", group = "Semana 2 · Geometría", num = 17, trapOpt = 0))
        l.add(BProb(id = "s2geo_18", topic = "geo", level = 2, text = "Halle el valor de x si O es circuncentro del triángulo ABC.", opts = listOf("20°", "30°", "40°", "25°", "15°"), vals = listOf("20", "30", "40", "25", "15"), correct = 0, check = "(180-(360-2*110))/2", steps = listOf("El arco AC que no contiene a B mide 2·110° = 220°. El ángulo central AOC que da hacia B abarca el otro arco: 360° − 220° = 140°.", "OA = OC: el triángulo AOC es isósceles. x = (180° − 140°)/2 = 20°."), fig = "f2g_18", theory = "Si el ángulo B es obtuso, el circuncentro queda fuera del triángulo y el ángulo central AOC que da hacia B mide 360° − 2B.", idea = "El triángulo AOC es isósceles. Solo hay que hallar su ángulo en O.", mistake = "Calcular 180° − 140° = 40° y no dividir entre 2: alternativa C.", verify = "20 + 20 + 140 = 180.", trap = "180-(360-2*110)", src = "ficha", group = "Semana 2 · Geometría", num = 18, trapOpt = 2))
        l.add(BProb(id = "s2geo_19", topic = "geo", level = 3, text = "Halle BC si G es baricentro del triángulo ABC y GM=1.", opts = listOf("§5*sqrt(2)", "§4*sqrt(2)", "§3*sqrt(2)", "§2*sqrt(2)", "§sqrt(2)"), vals = listOf("5*sqrt(2)", "4*sqrt(2)", "3*sqrt(2)", "2*sqrt(2)", "sqrt(2)"), correct = 1, check = "sqrt(4^2+4^2)", steps = listOf("GM = 1 y BG = 2. Ponemos G = (0; 0), B = (0; 2) y M = (0; −1).", "AG es perpendicular a BM: A = (a; 0). M es punto medio de AC: C = (−a; −2).", "∠GBC = 45°: el vector BC = (−a; −4) forma 45° con la vertical, así que |a| = 4.", "BC = √(4² + 4²) = 4√2."), fig = "f2g_19", theory = "El baricentro divide a cada mediana en razón 2 a 1. Coordenadas: el punto medio de dos puntos es el promedio de sus coordenadas.", idea = "Se ubica G en el origen y la mediana BM sobre el eje vertical. AG perpendicular a BM pone a A sobre el eje horizontal.", mistake = "Tomar BG = 2 como cateto del triángulo de 45° y responder 2√2, alternativa D.", verify = "En la figura BC está marcado como x. Con a = −4: A = (−4; 0) y C = (4; −2); M = (0; −1) es su punto medio.", trap = "2*sqrt(2)", src = "ficha", group = "Semana 2 · Geometría", num = 19, trapOpt = 3))
        l.add(BProb(id = "s2geo_20", topic = "geo", level = 3, text = "Halle el valor de x si H es ortocentro e I es incentro del triángulo ABC.", opts = listOf("30°", "15°", "20°", "25°", "35°"), vals = listOf("30", "15", "20", "25", "35"), correct = 3, check = "solve(80+2*t+2*t=180,t)[0]", steps = listOf("BH es perpendicular a AC: en el triángulo formado con A, ∠A = 90° − 10° = 80°.", "x es el ángulo entre BI y BC, así que ∠B = 2x.", "Suma de ángulos: 80° + 2x + 2x = 180°, así que x = 25°."), fig = "f2g_20", theory = "BH es altura: es perpendicular a AC. BI es bisectriz: divide al ángulo B en dos iguales.", idea = "En la figura, x está entre BI y BC: es la mitad de B. Con el ángulo de 10° se obtiene A.", mistake = "Tomar x como el ángulo entre BH y BI. Ese ángulo mide 25° − 10° = 15°, alternativa B.", verify = "Con x = 25°: B = 50°, C = 50° y A = 80°. Suman 180°.", trap = "(180-80-2*25)/2-(90-80)", src = "ficha", group = "Semana 2 · Geometría", num = 20, trapOpt = 1))
        l.add(BProb(id = "s2geo_21", topic = "geo", level = 2, text = "Halle el valor de x si H es ortocentro y O es circuncentro del triángulo ABC.", opts = listOf("25°", "15°", "20°", "30°", "40°"), vals = listOf("25", "15", "20", "30", "40"), correct = 2, check = "90-(90-20)", steps = listOf("CH es altura: es perpendicular a AB. En el triángulo formado con A: ∠ACH = 90° − A = 20°.", "El ángulo central BOC mide 2A y el triángulo OBC es isósceles, porque OB = OC. Sus ángulos de la base miden (180° − 2A)/2 = 90° − A.", "Entonces x = ∠OCB = 90° − A = 20°."), fig = "f2g_21", theory = "Propiedad: en un vértice, la altura y el segmento al circuncentro forman ángulos iguales con los dos lados. ∠ACH = ∠OCB = 90° − A.", idea = "x está entre CO y CB; el 20° está entre CA y CH. Son ángulos iguales.", mistake = "Pensar que x debe ser distinto de 20° porque está al otro lado. La altura y el circuncentro son simétricos respecto a la bisectriz.", verify = "Con A = 70°: ∠BOC = 140° y los ángulos de la base del triángulo OBC miden (180 − 140)/2 = 20°.", src = "ficha", group = "Semana 2 · Geometría", num = 21))
        l.add(BProb(id = "s2geo_22", topic = "geo", level = 3, text = "Halle el valor de x si H es ortocentro y O es circuncentro del triángulo ABC.", opts = listOf("15°", "30°", "25°", "40°", "20°"), vals = listOf("15", "30", "25", "40", "20"), correct = 1, check = "linsolve([b-c=20,a-b=10,a+b+c=180],[a,b,c])[0]-linsolve([b-c=20,a-b=10,a+b+c=180],[a,b,c])[2]", steps = listOf("En A: ∠HAO = |B − C| = 20°. En C: ∠HCO = |A − B| = 10°. En B: x = |A − C|.", "En la figura, en A el segmento AO queda más cerca de AC que la altura AH: B > C, así que B − C = 20°.", "En C, el segmento CO queda más alejado de CA que la altura CH: A > B, así que A − B = 10°.", "Entonces B = C + 20° y A = C + 30°. Con A + B + C = 180°: C + (C + 20) + (C + 30) = 180, de donde C = 130/3, B = 190/3 y A = 220/3.", "x = A − C = 30°."), fig = "f2g_22", note = "Las posiciones de H y O en la figura deciden qué ángulo es mayor. Si se leyera B > A, la diferencia A − C sería 10°, que no está entre las opciones.", theory = "En cada vértice, el ángulo entre la altura y el segmento al circuncentro es igual a la diferencia de los otros dos ángulos del triángulo: ∠HAO = |B − C|, ∠HCO = |A − B| y ∠HBO = |A − C|.", idea = "Se plantean las diferencias con los dos datos y la suma de ángulos. La figura indica cuál ángulo es mayor.", mistake = "Sumar los dos datos sin mirar el orden de los ángulos.", verify = "Con esos ángulos: B − C = 20, A − B = 10 y A − C = 30.", src = "ficha", group = "Semana 2 · Geometría", num = 22, review = true))
