        l.add(BProb(id = "s2est_17", topic = "est", level = 1, text = "Un jugador titular de un equipo de básquet se ha lesionado. Dilan y Jacob son dos jugadores del equipo, ellos esperan el llamado del entrenador para ser titulares. La decisión de la elección por parte del entrenador se basa en el promedio de los puntos obtenidos en los 5 últimos encuentros del entrenamiento de sus jugadores.\n[tabla]\n¿Qué jugador será seleccionado para reemplazar al titular lesionado? ¿Por qué?", opts = listOf("Dilan, porque obtuvo 20 puntos en el segundo partido.", "Jacob, porque obtuvo el mismo puntaje en dos partidos.", "Dilan, porque obtuvo un promedio superior al de Jacob.", "Jacob, porque obtuvo el mayor promedio en los dos últimos partidos."), vals = listOf("false", "false", "((12+20+10+10+12)/5>(14+16+8+12+12)/5)", "false"), correct = 2, check = "true", steps = listOf("Dilan: 12 + 20 + 10 + 10 + 12 = 64, promedio 12,8.", "Jacob: 14 + 16 + 8 + 12 + 12 = 62, promedio 12,4.", "Dilan tiene mayor promedio y por eso es el elegido."), note = "Las alternativas se comprueban como afirmaciones: solo la c cumple el criterio del promedio. Es el mismo problema que el 29 del examen 2025.", theory = "Media: la suma de los datos entre la cantidad de datos. Mediana: el dato central cuando se ordenan; si son una cantidad par, el promedio de los dos centrales. Moda: el dato que más se repite. Media ponderada: cada dato se multiplica por su frecuencia y se divide entre el total de datos.", idea = "El criterio del entrenador es el promedio de los 5 partidos.", mistake = "Elegir la a porque 20 es el puntaje más alto, aunque no es el criterio.", verify = "12,8 > 12,4.", letters = "abcd", src = "ficha", group = "Semana 2 · Estadística", table = listOf(listOf("", "Primer partido", "Segundo partido", "Tercer partido", "Cuarto partido", "Quinto partido"), listOf("Dilan", "12", "20", "10", "10", "12"), listOf("Jacob", "14", "16", "8", "12", "12")), num = 17))
        l.add(BProb(id = "s2est_18", topic = "est", level = 2, text = "El ingreso promedio semanal de 80 trabajadores es de S/ 600. Se retira un subgrupo de 30 trabajadores cuyo ingreso promedio era de S/ 400. ¿Cuál es el promedio de ingreso de los trabajadores que permanecen?", opts = listOf("s/ 680", "s/ 720", "s/ 750", "s/ 780"), vals = listOf("680", "720", "750", "780"), correct = 1, check = "(80*600-30*400)/50", steps = listOf("Total de ingresos: 80 · 600 = 48 000.", "Ingresos del subgrupo: 30 · 400 = 12 000.", "Quedan 50 trabajadores con 36 000. Promedio: 36 000/50 = 720."), theory = "Media: la suma de los datos entre la cantidad de datos. Mediana: el dato central cuando se ordenan; si son una cantidad par, el promedio de los dos centrales. Moda: el dato que más se repite. Media ponderada: cada dato se multiplica por su frecuencia y se divide entre el total de datos.", idea = "Se restan las sumas totales de ingresos.", mistake = "Hacer 600 + 120 = 720 por casualidad en otros datos; hay que usar las sumas.", verify = "720 · 50 + 400 · 30 = 48 000.", letters = "abcd", src = "ficha", group = "Semana 2 · Estadística", num = 18))
        l.add(BProb(id = "s2est_19", topic = "est", level = 2, text = "El peso promedio de \"m\" maletas es \"n\" kilos. Si se agregan \"m\" kilos a cada una de las \"m\" maletas. ¿Cuál es el nuevo peso promedio?", opts = listOf("n", "m+n", "2n", "2m"), vals = listOf("10", "3+10", "20", "6"), correct = 1, check = "(3*10+3*3)/3", steps = listOf("Cada maleta pesa m kilos más.", "El promedio también sube m kilos: n + m."), note = "Las alternativas se comprueban con m = 3 y n = 10.", theory = "Media: la suma de los datos entre la cantidad de datos. Mediana: el dato central cuando se ordenan; si son una cantidad par, el promedio de los dos centrales. Moda: el dato que más se repite. Media ponderada: cada dato se multiplica por su frecuencia y se divide entre el total de datos.", idea = "Si a cada dato se le suma una constante, la media también aumenta en esa constante.", mistake = "Pensar que el promedio no cambia, alternativa a.", verify = "Con m = 3 y n = 10: suma 30, se agregan 9 y el promedio es 39/3 = 13 = 3 + 10.", letters = "abcd", src = "ficha", group = "Semana 2 · Estadística", num = 19))
        l.add(BProb(id = "s2est_20", topic = "est", level = 2, text = "Oxana tiene un pendrive de 32Gb de capacidad, al parecer un virus lo ha contaminado y desea salvar su contenido cuanto antes. Los archivos guardados tienen un tamaño que varían de 50Mb a 70Mb(1Gb = 1024Mb). ¿Cuál es el número máximo de archivos que potencialmente puede salvar?", opts = listOf("655", "468", "474", "642"), vals = listOf("655", "468", "474", "642"), correct = 0, check = "floor(32*1024/50)", steps = listOf("32 Gb = 32 · 1024 = 32 768 Mb.", "32 768/50 = 655,36.", "Solo cuentan archivos completos: 655."), note = "Es el mismo problema que el 13 del examen 2023.", theory = "Para tener la mayor cantidad de archivos, cada uno debe ser lo más pequeño posible.", idea = "Con el tamaño mínimo, 50 Mb, caben más archivos.", mistake = "Dividir entre 70 Mb y obtener 468.", verify = "655 · 50 = 32 750 Mb.", trap = "floor(32*1024/70)", letters = "abcd", src = "ficha", group = "Semana 2 · Estadística", num = 20, trapOpt = 1))
        l.add(BProb(id = "s2est_21", topic = "est", level = 2, text = "Un supervisor agroindustrial evalúa el rendimiento de producción de harina de camote de dos líneas de procesado (A y B) durante 5 turnos de trabajo:\n[tabla]\n¿Qué línea recomendará si busca mayor promedio y estabilidad en el proceso?", opts = listOf("Línea A, porque su promedio es 50 y tiene menor variación.", "Línea B, porque su promedio es 50 y tiene mayor regularidad.", "Línea A por llegar a 60.", "Ambas por tener el mismo promedio."), vals = listOf("(60-40<52-48)", "(52-48<60-40 and 250/5==250/5)", "false", "false"), correct = 1, check = "true", steps = listOf("Línea A: 45 + 50 + 40 + 55 + 60 = 250, promedio 50. Rango: 60 − 40 = 20.", "Línea B: 48 + 52 + 50 + 49 + 51 = 250, promedio 50. Rango: 52 − 48 = 4.", "Mismo promedio, pero B varía menos: es más estable."), note = "Las alternativas se comprueban como afirmaciones.", theory = "Media: la suma de los datos entre la cantidad de datos. Mediana: el dato central cuando se ordenan; si son una cantidad par, el promedio de los dos centrales. Moda: el dato que más se repite. Media ponderada: cada dato se multiplica por su frecuencia y se divide entre el total de datos. La estabilidad se mide con cuánto se separan los datos: un rango menor indica más regularidad.", idea = "Las dos líneas tienen el mismo promedio. Se decide por la variación.", mistake = "Elegir la d, que solo mira el promedio e ignora la estabilidad.", verify = "Las notas de B están todas a 2 o menos de 50.", letters = "abcd", src = "ficha", group = "Semana 2 · Estadística", table = listOf(listOf("Línea", "T1", "T2", "T3", "T4", "T5"), listOf("Línea A", "45", "50", "40", "55", "60"), listOf("Línea B", "48", "52", "50", "49", "51")), num = 21))
        l.add(BProb(id = "s2est_22", topic = "est", level = 2, text = "El gráfico muestra las ventas realizadas en miles de soles por varones y mujeres en una tienda comercial:\nHallar el promedio de ventas de varones en total.", opts = listOf("50", "51", "51.66", "52.66"), vals = listOf("abs(50-155/3)<1/100", "abs(51-155/3)<1/100", "abs(5166/100-155/3)<1/100", "abs(5266/100-155/3)<1/100"), correct = 2, check = "true", steps = listOf("Varones: 60 + 40 + 60 + 70 + 50 + 30 = 310.", "Promedio: 310/6 ≈ 51,67."), fig = "fe1_ventas", note = "El gráfico es compartido por las preguntas 22 y 23. Las alternativas se comprueban por cercanía.", theory = "Media: la suma de los datos entre la cantidad de datos. Mediana: el dato central cuando se ordenan; si son una cantidad par, el promedio de los dos centrales. Moda: el dato que más se repite. Media ponderada: cada dato se multiplica por su frecuencia y se divide entre el total de datos.", idea = "Se suman las seis barras de los varones y se divide entre 6.", mistake = "Dividir entre 5 meses y obtener 62.", verify = "310/6 = 51,666…, que se escribe 51,66 en la alternativa.", letters = "abcd", src = "ficha", group = "Semana 2 · Estadística", num = 22))
        l.add(BProb(id = "s2est_23", topic = "est", level = 2, text = "El gráfico muestra las ventas realizadas en miles de soles por varones y mujeres en una tienda comercial:\nHallar la diferencia entre el promedio de ventas de mujeres con el de varones desde enero a mayo.", opts = listOf("0", "10", "6", "30"), vals = listOf("0", "10", "6", "30"), correct = 2, check = "abs((70+60+50+40+30)/5-(60+40+60+70+50)/5)", steps = listOf("Mujeres: 70 + 60 + 50 + 40 + 30 = 250 y 250/5 = 50.", "Varones: 60 + 40 + 60 + 70 + 50 = 280 y 280/5 = 56.", "Diferencia: 56 − 50 = 6."), fig = "fe1_ventas", theory = "Media: la suma de los datos entre la cantidad de datos. Mediana: el dato central cuando se ordenan; si son una cantidad par, el promedio de los dos centrales. Moda: el dato que más se repite. Media ponderada: cada dato se multiplica por su frecuencia y se divide entre el total de datos.", idea = "Solo se usan cinco meses, de enero a mayo.", mistake = "Incluir junio y calcular con seis meses.", verify = "El promedio de varones es mayor en 6.", letters = "abcd", src = "ficha", group = "Semana 2 · Estadística", num = 23))
    }
    private fun p24(l: MutableList<BProb>) {
        l.add(BProb(id = "s2est_24", topic = "est", level = 3, text = "El profesor Otto reporta a la dirección académica que, en una prueba de nivelación de 6 preguntas evaluadas de 1 a 22, el promedio fue 15, la mediana 14, la moda 12 y la calificación más baja fue 10. Halle la nota máxima obtenida en una de las preguntas.", opts = listOf("18", "19", "20", "22"), vals = listOf("18", "19", "20", "22"), correct = 3, check = "max(select(f->size(select(e->e<f and e>=17 and 10+12+12+16+e+f==90,seq(e,e,16,22)))>0,seq(f,f,16,22)))", steps = listOf("Suma: 6 · 15 = 90. Mínima: 10.", "La moda 12 aparece dos veces, así que la segunda y la tercera nota valen 12.", "Mediana: (12 + c4)/2 = 14, así que la cuarta nota es 16.", "10 + 12 + 12 + 16 + e + f = 90, así que e + f = 40. Con f ≤ 22 y e < f, f = 22 con e = 18, o f = 21 con e = 19.", "La nota máxima entre las alternativas es 22."), note = "También sirve 10, 12, 12, 16, 19, 21, con máxima 21, que no está entre las alternativas. La clave 22 corresponde a la primera solución.", theory = "Media: la suma de los datos entre la cantidad de datos. Mediana: el dato central cuando se ordenan; si son una cantidad par, el promedio de los dos centrales. Moda: el dato que más se repite. Media ponderada: cada dato se multiplica por su frecuencia y se divide entre el total de datos.", idea = "Con 6 notas, la mediana es el promedio de la tercera y la cuarta. La moda 12 se repite dos veces.", mistake = "Elegir 20, que obliga a e = f = 20 y duplica una nota, haciendo bimodal la serie.", verify = "10, 12, 12, 16, 18, 22: suma 90, mediana 14 y moda 12.", letters = "abcd", src = "ficha", group = "Semana 2 · Estadística", num = 24, review = true))
        l.add(BProb(id = "s2est_25", topic = "est", level = 1, text = "En la siguiente tabla se muestra los equipos de fútbol de la I.E Fe y Alegría, conformados por integrantes del equipo A y B, con un total de 15 integrantes por equipo.\n[tabla]\nCalcule el promedio de edad en el equipo A", opts = listOf("12", "12.2", "12.6", "13"), vals = listOf("12", "61/5", "63/5", "13"), correct = 1, check = "(11*3+12*7+13*4+14*1)/15", steps = listOf("Equipo A: 11·3 = 33, 12·7 = 84, 13·4 = 52 y 14·1 = 14.", "Suma: 183. Media: 183/15 = 12,2."), note = "Las alternativas se comprueban como fracciones: 12,2 es 61/5 y 12,6 es 63/5.", theory = "Media: la suma de los datos entre la cantidad de datos. Mediana: el dato central cuando se ordenan; si son una cantidad par, el promedio de los dos centrales. Moda: el dato que más se repite. Media ponderada: cada dato se multiplica por su frecuencia y se divide entre el total de datos.", idea = "Es una media ponderada: cada edad se multiplica por su frecuencia.", mistake = "Promediar las cuatro edades, 12,5, sin ponderar.", verify = "12,2 · 15 = 183.", letters = "abcd", src = "ficha", group = "Semana 2 · Estadística", table = listOf(listOf("Edad (años)", "Equipo A", "Equipo B"), listOf("11", "3", "2"), listOf("12", "7", "2"), listOf("13", "4", "5"), listOf("14", "1", "6"), listOf("", "n = 15", "n = 15")), num = 25))
        l.add(BProb(id = "s2est_26", topic = "est", level = 2, text = "En la siguiente tabla se muestra los equipos de fútbol de la I.E Fe y Alegría, conformados por integrantes del equipo A y B, con un total de 15 integrantes por equipo.\n[tabla]\nEn cuanto varía el promedio de edad comparando con el equipo B.", opts = listOf("Disminuye en 0.8", "Disminuye en 0.6", "Aumenta en 0.8", "No varía, son iguales."), vals = listOf("-4/5", "-3/5", "4/5", "0"), correct = 0, check = "(11*3+12*7+13*4+14*1)/15-(11*2+12*2+13*5+14*6)/15", steps = listOf("Equipo B: 11·2 = 22, 12·2 = 24, 13·5 = 65 y 14·6 = 84. Suma 195 y media 195/15 = 13.", "Equipo A: 12,2.", "12,2 − 13 = −0,8: el promedio del equipo A disminuye 0,8 respecto al equipo B."), note = "Las alternativas se comprueban como fracciones: 0,8 es 4/5 y 0,6 es 3/5.", theory = "Media: la suma de los datos entre la cantidad de datos. Mediana: el dato central cuando se ordenan; si son una cantidad par, el promedio de los dos centrales. Moda: el dato que más se repite. Media ponderada: cada dato se multiplica por su frecuencia y se divide entre el total de datos.", idea = "Se halla la media del equipo B y se compara con la del equipo A.", mistake = "Invertir la comparación y responder que aumenta 0,8.", verify = "13 − 12,2 = 0,8.", letters = "abcd", src = "ficha", group = "Semana 2 · Estadística", table = listOf(listOf("Edad (años)", "Equipo A", "Equipo B"), listOf("11", "3", "2"), listOf("12", "7", "2"), listOf("13", "4", "5"), listOf("14", "1", "6"), listOf("", "n = 15", "n = 15")), num = 26))
        l.add(BProb(id = "s3geo_01", topic = "geo", level = 3, text = "Halle AQ si BQ = 3, CM = 9, MB = 2 y PQ = MN.", opts = listOf("6", "9", "§3*sqrt(2)", "3", "5"), vals = listOf("6", "9", "3*sqrt(2)", "3", "5"), correct = 0, check = "9*2/3", steps = listOf("Sea PQ = MN = a y QM = b. Entonces PM = a + b y QN = b + a.", "En M se cortan CB y PN: CM·MB = PM·MN, es decir 9·2 = (a + b)·a = 18.", "En Q se cortan AB y PN: AQ·QB = PQ·QN = a·(a + b) = 18.", "AQ·3 = 18, así que AQ = 6."), fig = "f3g_01", theory = "Teorema de las cuerdas: si dos cuerdas se cortan, el producto de los dos trozos de una es igual al producto de los dos trozos de la otra.", idea = "La cuerda PN pasa por Q y por M. Como PQ = MN, los productos en Q y en M tienen los mismos factores.", mistake = "Aplicar el teorema solo en Q sin notar que PQ·QN es el mismo producto que PM·MN.", verify = "Los dos productos valen 18: en M, 9·2, y en Q, 6·3.", src = "ficha", group = "Semana 3 · Geometría", num = 1))
        l.add(BProb(id = "s3geo_02", topic = "geo", level = 2, text = "En la figura, halle el valor de x si O es centro.", opts = listOf("30°", "37°", "45°", "53°", "60°"), vals = listOf("30", "37", "45", "53", "60"), correct = 4, check = "2*asin(solve(4*(4+c)=3*(3+5),c)[0]/(2*2))*180/pi", steps = listOf("Sea c la cuerda de la secante de arriba. Teorema de las secantes: 4·(4 + c) = 3·(3 + 5) = 24.", "16 + 4c = 24, así que c = 2.", "La cuerda mide 2, igual que el radio. El triángulo formado con el centro es equilátero: el arco x mide 60°."), fig = "f3g_02", note = "Con radio 2 el diámetro es 4, así que la secante de abajo no puede tener una cuerda de 5. La respuesta 60° sale de la secante de arriba, que es la que usa la pregunta.", theory = "Teorema de las secantes: desde un punto exterior, el producto de la secante entera por su parte exterior es el mismo para todas las secantes; para una tangente, es el cuadrado de la tangente. Una cuerda igual al radio abarca un arco de 60°.", idea = "Con el teorema de las secantes se halla la cuerda de arriba. Si mide igual que el radio, su arco mide 60°.", mistake = "Usar el teorema de las cuerdas en lugar del de las secantes. El punto de donde salen está fuera de la circunferencia.", verify = "4·6 = 24 y 3·8 = 24.", warn = "Los datos de la ficha no son consistentes: con radio 2 una cuerda no puede medir 5. Lee la nota.", src = "ficha", group = "Semana 3 · Geometría", num = 2, review = true))
        l.add(BProb(id = "s3geo_03", topic = "trig", level = 2, text = "De la figura, halle el valor de x.", opts = listOf("30°", "37°", "45°", "53°", "60°"), vals = emptyList(), correct = -1, check = "", steps = listOf("Pitágoras: (√a)² + 6² = (√(2a + 7))², es decir a + 36 = 2a + 7.", "a = 29.", "x está frente al cateto √a = √29 y junto al cateto 6: tan x = √29/6 ≈ 0,897.", "x ≈ 41,9°, que no es ninguno de los ángulos de las alternativas."), fig = "f3g_03", theory = "Teorema de Pitágoras. En un triángulo rectángulo, tan x = cateto opuesto / cateto adyacente.", idea = "El ángulo recto está arriba, así que √(2a + 7) es la hipotenusa.", mistake = "Tomar 6 como hipotenusa. La figura marca el ángulo recto entre √a y 6.", verify = "Lados: √29 ≈ 5,39, 6 y √65 ≈ 8,06. Se cumple 29 + 36 = 65.", warn = "Con los datos de la ficha, x no da ninguno de los ángulos de las alternativas. Lee la solución.", src = "ficha", group = "Semana 3 · Geometría", answer = "x ≈ 41,9°, con tan x = √29/6. Ninguna alternativa es correcta.", num = 3, review = true))
        l.add(BProb(id = "s3geo_04", topic = "geo", level = 3, text = "En la figura, halle el valor de x.", opts = listOf("6", "5", "2", "3", "4"), vals = listOf("6", "5", "2", "3", "4"), correct = 3, check = "max(solve(t^2=t+6,t))", steps = listOf("El triángulo grande es rectángulo arriba. Sea h la altura: h² = 4·(2 + x).", "Cateto derecho: c² = (2 + x)·(6 + x), su proyección por la hipotenusa.", "En el triángulo formado por la altura y el cateto derecho, la ceviana es bisectriz: 2/x = h/c.", "Elevamos al cuadrado: 4/x² = 4(2 + x)/((2 + x)(6 + x)) = 4/(6 + x).", "x² = x + 6, es decir (x − 3)(x + 2) = 0. Como x > 0, x = 3."), fig = "f3g_04", theory = "En el triángulo rectángulo, la altura h a la hipotenusa cumple h² = m·n, y cada cateto cumple c² = (su proyección)·(hipotenusa). Teorema de la bisectriz: la bisectriz divide al lado opuesto en la misma razón que los lados que la forman.", idea = "El segmento del medio es bisectriz del ángulo entre la altura y el cateto de la derecha.", mistake = "Pensar que la ceviana divide la base en partes iguales. Es bisectriz, no mediana.", verify = "Con x = 3: h² = 20 y c² = 45. 2/3 = √20/√45 = √(4/9) = 2/3.", src = "ficha", group = "Semana 3 · Geometría", num = 4))
        l.add(BProb(id = "s3geo_05", topic = "geo", level = 3, text = "De la figura, T es punto de tangencia, CT = 8 y TP = 4. Halle TQ.", opts = listOf("3/8", "6/5", "5", "8/3", "§4*sqrt(2)"), vals = listOf("3/8", "6/5", "5", "8/3", "4*sqrt(2)"), correct = 3, check = "4-4^2/(4+8)", steps = listOf("Para la circunferencia pequeña: PT es tangente, así que PT² = PB·PA.", "Para la grande: PQ·PC = PB·PA.", "Entonces PT² = PQ·PC: 4² = PQ·(4 + 8), así que PQ = 16/12 = 4/3.", "TQ = TP − PQ = 4 − 4/3 = 8/3."), fig = "f3g_05", theory = "Teorema de las secantes: desde un punto exterior, el producto de la secante entera por su parte exterior es el mismo para todas las secantes; para una tangente, es el cuadrado de la tangente.", idea = "P está en la recta AB, que es común a las dos circunferencias. Su potencia es la misma para las dos.", mistake = "Responder PQ = 4/3 en lugar de TQ. Ese valor no está; hay que restarlo de TP.", verify = "PQ·PC = (4/3)·12 = 16 = PT².", src = "ficha", group = "Semana 3 · Geometría", num = 5))
    }
    private fun p25(l: MutableList<BProb>) {
        l.add(BProb(id = "s3geo_06", topic = "geo", level = 2, text = "En la figura, halle el valor de x si: A es punto de tangencia y BC = CD.", opts = listOf("37°", "45°", "30°", "60°", "53°"), vals = listOf("37", "45", "30", "60", "53"), correct = 1, check = "(180-90)/2", steps = listOf("C y D están en la circunferencia y ∠ACD = 90°: AD es diámetro.", "La tangente BA es perpendicular al diámetro AD: ∠BAD = 90°.", "AC es altura del triángulo ABD y, como BC = CD, también es mediana: AB = AD.", "El triángulo BAD es rectángulo e isósceles: x = 45°."), fig = "f3g_06", theory = "Un ángulo inscrito recto abarca un diámetro. La tangente es perpendicular al diámetro en el punto de tangencia. Si una altura es también mediana, el triángulo es isósceles.", idea = "∠ACD = 90° y C está en la circunferencia, así que AD es diámetro y la tangente en A es perpendicular a AD.", mistake = "No notar que C está en la circunferencia y que eso hace de AD un diámetro.", verify = "En el triángulo BAD: 90° + 45° + 45° = 180°.", src = "ficha", group = "Semana 3 · Geometría", num = 6))
        l.add(BProb(id = "s3geo_07", topic = "geo", level = 2, text = "En la figura, halle el valor de x.", opts = listOf("3", "4", "5", "6", "7"), vals = listOf("3", "4", "5", "6", "7"), correct = 2, check = "(2+6)/(2*4/5)", steps = listOf("Las cuerdas 2 y 6 forman un ángulo de 74°, y x es su bisectriz.", "Propiedad: 2 + 6 = 2·x·cos 37°.", "8 = 2·x·(4/5) = 8x/5, así que x = 5."), fig = "f3g_07", theory = "Si desde un punto de la circunferencia se trazan dos cuerdas y la bisectriz del ángulo entre ellas como cuerda, se cumple: suma de las dos cuerdas = 2·(bisectriz)·cos de la mitad del ángulo.", idea = "x es la cuerda que divide al ángulo de 74° en dos de 37°. cos 37° = 4/5.", mistake = "Promediar las cuerdas: (2 + 6)/2 = 4, alternativa B.", verify = "Se puede comprobar con Ptolomeo en el cuadrilátero que forman los cuatro puntos: el resultado es el mismo, x = 5.", trap = "(2+6)/2", src = "ficha", group = "Semana 3 · Geometría", num = 7, trapOpt = 1))
        l.add(BProb(id = "s3geo_08", topic = "geo", level = 1, text = "Halle la distancia del ortocentro al baricentro de una región triangular rectangular cuyos catetos miden 9 y 12.", opts = listOf("6", "7,5", "3", "5", "2,5"), vals = listOf("6", "15/2", "3", "5", "5/2"), correct = 3, check = "2/3*15/2", steps = listOf("Hipotenusa: √(81 + 144) = 15.", "El ortocentro es el vértice del ángulo recto. La mediana desde ese vértice mide la mitad de la hipotenusa: 7,5.", "El baricentro está a 2/3 de esa mediana desde el vértice: (2/3)·7,5 = 5."), theory = "En un triángulo rectángulo el ortocentro es el vértice del ángulo recto. El baricentro está a dos tercios de la mediana desde el vértice.", idea = "La distancia pedida está sobre la mediana que sale del ángulo recto.", mistake = "Dar la mediana completa, 7,5, alternativa B. Esa es la distancia del ortocentro al circuncentro.", verify = "Del baricentro al punto medio de la hipotenusa quedan 2,5, y 5 + 2,5 = 7,5.", trap = "15/2", src = "ficha", group = "Semana 3 · Geometría", num = 8, trapOpt = 1))
        l.add(BProb(id = "s3geo_09", topic = "geo", level = 3, text = "Halle la longitud del lado del cuadrado ABCD si PQ // BC, PN = 9 y NQ = 3.", opts = listOf("§3*sqrt(5)", "§6*sqrt(5)", "§3*sqrt(10)", "§4*sqrt(5)", "§5*sqrt(3)"), vals = listOf("3*sqrt(5)", "6*sqrt(5)", "3*sqrt(10)", "4*sqrt(5)", "5*sqrt(3)"), correct = 2, check = "2*sqrt((((9+3)/2)^2+((9-3)/2)^2)/2)", steps = listOf("Centro en el origen y lado 2h. La circunferencia tiene radio h√2 y la diagonal AC es la recta y = x.", "PQ mide 9 + 3 = 12 y su punto medio está sobre el eje vertical. N está a 6 − 3 = 3 a la derecha de ese punto medio.", "N está en y = x, así que PQ está a la altura 3: N = (3; 3), P = (−6; 3) y Q = (6; 3).", "P está en la circunferencia: 6² + 3² = 2h², así que h² = 45/2.", "Lado: 2h = 2·√(45/2) = √90 = 3√10."), fig = "f3g_09", theory = "La diagonal del cuadrado inscrito es diámetro. Coordenadas con el centro en el origen; la diagonal AC es la recta y = x.", idea = "PQ es horizontal y corta a la diagonal en N. Con PN y NQ se sabe dónde está N respecto al punto medio de PQ.", mistake = "Pensar que PQ es el lado del cuadrado. PQ es una cuerda más larga que el lado.", verify = "También por cuerdas: PN·NQ = 27 y AN·NC = (h√2 + 3√2)(h√2 − 3√2) = 2h² − 18 = 45 − 18 = 27.", src = "ficha", group = "Semana 3 · Geometría", num = 9))
        l.add(BProb(id = "s3geo_10", topic = "geo", level = 3, text = "En la figura, AC y AD son diámetros de las circunferencias. Si BM = MH y (AH)(CD) = 27, halle BH.", opts = listOf("3", "4", "5", "6", "7"), vals = listOf("3", "4", "5", "6", "7"), correct = 3, check = "sqrt(4*27/3)", steps = listOf("En la grande: BH² = AH·HD. En la pequeña: MH² = AH·HC.", "BM = MH, así que BH = 2MH y BH² = 4MH²: AH·HD = 4·AH·HC, de donde HD = 4HC.", "HD = HC + CD, así que CD = 3HC.", "BH² = AH·HD = AH·4HC = 4·AH·CD/3 = 4·27/3 = 36. BH = 6."), fig = "f3g_10", theory = "Si un segmento perpendicular al diámetro va hasta la circunferencia, su cuadrado es el producto de los dos trozos del diámetro: BH² = AH·HD.", idea = "B está en la semicircunferencia grande y M en la pequeña. Como BH = 2·MH, se comparan los dos productos.", mistake = "Responder MH = 3, alternativa A.", verify = "Por ejemplo AH = 9, HC = 1 y CD = 3: AH·CD = 27, BH² = 9·4 = 36 y MH² = 9·1 = 9.", trap = "sqrt(4*27/3)/2", src = "ficha", group = "Semana 3 · Geometría", num = 10, trapOpt = 0))
        l.add(BProb(id = "s3geo_11", topic = "geo", level = 2, text = "Halle el valor de R si O es centro.", opts = listOf("§sqrt(38)", "§sqrt(52)", "§4*sqrt(2)", "§5*sqrt(2)", "§sqrt(41)"), vals = listOf("sqrt(38)", "sqrt(52)", "4*sqrt(2)", "5*sqrt(2)", "sqrt(41)"), correct = 3, check = "sqrt(((2+4*6/2)/2)^2+((6-4)/2)^2)", steps = listOf("La cuerda vertical tiene trozos 4 y 6; la horizontal, 2 y y. Cuerdas: 2·y = 4·6, así que y = 12.", "La cuerda horizontal mide 14 y su mitad es 7. La vertical mide 10 y su punto medio está 1 por debajo del cruce.", "Entonces el centro está a 1 de la cuerda horizontal.", "R² = 7² + 1² = 50, así que R = 5√2."), fig = "f3g_11", theory = "Teorema de las cuerdas: si dos cuerdas se cortan, el producto de los dos trozos de una es igual al producto de los dos trozos de la otra. La perpendicular desde el centro a una cuerda cae en su punto medio.", idea = "Primero se completa la cuerda horizontal con el teorema de las cuerdas. Luego se ubica el centro con los puntos medios.", mistake = "Olvidar el trozo de 12 y usar solo los números de la figura.", verify = "Con el centro a 5 a la derecha del cruce: la distancia a la cuerda vertical es 5 y su mitad es 5. R² = 25 + 25 = 50 también.", src = "ficha", group = "Semana 3 · Geometría", num = 11))
        l.add(BProb(id = "s3geo_12", topic = "geo", level = 3, text = "Halle la longitud del radio de la circunferencia que pasa por A, H y C.", opts = listOf("§sqrt(15)", "§sqrt(13)", "§sqrt(10)", "§sqrt(11)", "5"), vals = listOf("sqrt(15)", "sqrt(13)", "sqrt(10)", "sqrt(11)", "5"), correct = 1, check = "sqrt(4^2+6^2)/2", steps = listOf("H es el ortocentro, porque es el cruce de dos alturas.", "BH = 2R·cos B = 4 y AC = 2R·sen B = 6.", "Sumamos los cuadrados: (2R)²·(cos² B + sen² B) = 16 + 36 = 52, así que 2R = √52 = 2√13 y R = √13.", "La circunferencia por A, H y C tiene el mismo radio: √13."), fig = "f3g_12", theory = "Propiedad del ortocentro: la circunferencia que pasa por A, H y C tiene el mismo radio que la circunscrita al triángulo ABC. Además BH = 2R·cos B y AC = 2R·sen B.", idea = "Con BH y AC se obtiene 2R por Pitágoras, usando sen² B + cos² B = 1.", mistake = "Pensar que el radio es la mitad de AC, 3. Eso solo pasaría si AC fuera diámetro.", verify = "Con R = √13: cos B = 4/(2√13) y sen B = 6/(2√13). Sus cuadrados suman 16/52 + 36/52 = 1.", src = "ficha", group = "Semana 3 · Geometría", num = 12))
        l.add(BProb(id = "s3geo_13", topic = "geo", level = 3, text = "Halle el valor de x.", opts = listOf("60°", "45°", "37°", "53°", "30°"), vals = listOf("60", "45", "37", "53", "30"), correct = 1, check = "asin(1/sqrt(2))*180/pi", steps = listOf("Las cuerdas se cortan en el punto medio de la horizontal: a·2a = b·b, así que b² = 2a² y b = a√2.", "El triángulo de la izquierda es rectángulo: su hipotenusa es b y el cateto opuesto a x es a.", "sen x = a/b = 1/√2, así que x = 45°."), fig = "f3g_13", theory = "Teorema de las cuerdas: si dos cuerdas se cortan, el producto de los dos trozos de una es igual al producto de los dos trozos de la otra. En un triángulo rectángulo, sen x = cateto opuesto / hipotenusa.", idea = "Con el teorema de las cuerdas se relaciona b con a. Luego x sale del triángulo rectángulo de la izquierda.", mistake = "Tomar b como cateto y a como hipotenusa.", verify = "El otro cateto mide √(b² − a²) = a, igual al opuesto. Es el triángulo isósceles rectángulo.", src = "ficha", group = "Semana 3 · Geometría", num = 13))
    }
    private fun p26(l: MutableList<BProb>) {
        l.add(BProb(id = "s3geo_14", topic = "trig", level = 1, text = "Halle el valor de x si AH=4, HC=9 y BM=MH.", opts = listOf("37°", "53°", "45°", "30°", "26,5°"), vals = listOf("37", "53", "45", "30", "53/2"), correct = 0, check = "round(evalf(atan(3/4))*180/pi)", steps = listOf("BH² = 4·9 = 36, así que BH = 6.", "M es punto medio de BH: MH = 3.", "En el triángulo AHM, recto en H: tan x = MH/AH = 3/4. Es el notable: x = 37°."), fig = "f3g_14", theory = "Relación métrica: la altura a la hipotenusa cumple BH² = AH·HC. Triángulo notable de 37° y 53°.", idea = "Con la altura se obtiene MH y luego la tangente de x.", mistake = "Tomar el ángulo opuesto del notable: 53°, alternativa B.", verify = "AM = √(16 + 9) = 5. Lados 3, 4 y 5.", trap = "90-round(evalf(atan(3/4))*180/pi)", src = "ficha", group = "Semana 3 · Geometría", num = 14, trapOpt = 1))
        l.add(BProb(id = "s3geo_15", topic = "geo", level = 2, text = "Halle el valor de x si O es centro y A es punto de tangencia.", opts = listOf("6", "5", "3", "8", "4"), vals = listOf("6", "5", "3", "8", "4"), correct = 4, check = "sqrt(2*(2+3+3))", steps = listOf("La recta de abajo corta a la circunferencia a 2 del punto exterior. La perpendicular desde O cae a 3 de ese punto de corte.", "Ese pie es el punto medio de la cuerda: la cuerda mide 6 y la secante entera 2 + 6 = 8.", "Tangente: x² = 2·8 = 16, así que x = 4."), fig = "f3g_15", theory = "Teorema de las secantes: desde un punto exterior, el producto de la secante entera por su parte exterior es el mismo para todas las secantes; para una tangente, es el cuadrado de la tangente. La perpendicular desde el centro a una cuerda cae en su punto medio.", idea = "La recta de abajo es una secante. El pie de la perpendicular desde O es el punto medio de la cuerda, así que la cuerda mide 3 + 3.", mistake = "Responder la secante entera, 8, alternativa D, en lugar de su raíz.", verify = "Con radio 5 y la distancia del centro a la recta 4: la mitad de la cuerda es √(25 − 16) = 3, como en la figura.", trap = "2+3+3", src = "ficha", group = "Semana 3 · Geometría", num = 15, trapOpt = 3))
        l.add(BProb(id = "s3arit_01", topic = "ineq", level = 2, text = "Luego de resolver:\n§x/2-1/4>2*x+1/3\n, que valor no puede tomar x", opts = listOf("− 3", "− 6", "− 8", "− 1", "0"), vals = listOf("-3", "-6", "-8", "-1", "0"), correct = 4, check = "select(v->not(v<solve(x/2-1/4=2*x+1/3,x)[0]),[-3,-6,-8,-1,0])[0]", steps = listOf("x/2 − 2x > 1/3 + 1/4, es decir −3x/2 > 7/12.", "Al multiplicar por −2/3 el sentido se invierte: x < −7/18, que es x < −0,39.", "Valen −3, −6, −8 y −1. El 0 no es menor que −0,39."), theory = "Una inecuación lineal se resuelve como una ecuación, cuidando de invertir el sentido si se multiplica o divide por un negativo.", idea = "Se resuelve la desigualdad y se busca la alternativa que no está en el conjunto solución.", mistake = "No invertir el sentido y obtener x > −7/18, con lo que −3 parecería el valor que no puede tomar.", verify = "−1 < −0,39 sí cumple, y 0 > −0,39 no.", letters = "abcde", src = "ficha", group = "Semana 3 · Aritmética", num = 1))
        l.add(BProb(id = "s3arit_02", topic = "ineq", level = 2, text = "Resolver:\n§4*x/3-1<=3*x/5+2", opts = listOf("R", "φ", "<−∞, 45/11>", "<45/11, +∞>", "<−∞, 45/11]"), vals = listOf("[-inf,inf,0,0]", "[]", "[-inf,45/11,0,0]", "[45/11,inf,0,0]", "[-inf,45/11,0,1]"), correct = 4, check = "[-inf,solve(4*x/3-1=3*x/5+2,x)[0],0,1]", steps = listOf("4x/3 − 3x/5 ≤ 2 + 1, es decir 11x/15 ≤ 3.", "x ≤ 45/11.", "Como la desigualdad es ≤, el extremo 45/11 se incluye: <−∞, 45/11]."), note = "Las alternativas se comprueban como [inicio, fin, ¿incluye el inicio?, ¿incluye el fin?]. φ es el conjunto vacío.", theory = "Un intervalo se escribe con sus extremos. El extremo incluido lleva corchete cerrado y el no incluido lleva corchete abierto, que en la ficha también se escribe con < o >. Al multiplicar o dividir una desigualdad por un número negativo, el sentido se invierte. Una inecuación lineal se resuelve como una ecuación, cuidando de invertir el sentido si se multiplica o divide por un negativo.", idea = "Se pasan las x a un lado y el desigual es \"menor o igual\", así que el extremo se incluye.", mistake = "Escribir el extremo abierto por descuido, alternativa c. Con ≤ el extremo sí se incluye.", verify = "Con x = 45/11: 60/11 − 1 = 49/11 y 27/11 + 2 = 49/11. Se cumple la igualdad.", trap = "[-inf,45/11,0,0]", letters = "abcde", src = "ficha", group = "Semana 3 · Aritmética", num = 2, trapOpt = 2))
        l.add(BProb(id = "s3arit_03", topic = "ineq", level = 2, text = "Resolver:\n§(2*x+6)/3-x/4<5", opts = listOf("x ∈ <−∞, 36/5>", "x ∈ <−1, 1>", "x ∈ <36/5, +∞>", "N.A.", "x ∈ <1, 36/5>"), vals = listOf("[-inf,36/5,0,0]", "[-1,1,0,0]", "[36/5,inf,0,0]", "undef", "[1,36/5,0,0]"), correct = 0, check = "[-inf,solve((2*x+6)/3-x/4=5,x)[0],0,0]", steps = listOf("4(2x + 6) − 3x < 60.", "8x + 24 − 3x < 60, es decir 5x < 36.", "x < 36/5: <−∞, 36/5>."), theory = "Un intervalo se escribe con sus extremos. El extremo incluido lleva corchete cerrado y el no incluido lleva corchete abierto, que en la ficha también se escribe con < o >. Al multiplicar o dividir una desigualdad por un número negativo, el sentido se invierte. Una inecuación lineal se resuelve como una ecuación, cuidando de invertir el sentido si se multiplica o divide por un negativo.", idea = "Se multiplica por 12 para quitar denominadores. Como 12 es positivo, el sentido no cambia.", mistake = "Olvidar multiplicar el 5 por 12 y obtener 5x < −24.", verify = "Con x = 7: 20/3 − 7/4 = 4,92 < 5. Con x = 8: 22/3 − 2 = 5,33 > 5.", letters = "abcde", src = "ficha", group = "Semana 3 · Aritmética", num = 3))
        l.add(BProb(id = "s3arit_04", topic = "ineq", level = 2, text = "Resolver:   −2 < −4 + 3x ≤ 5", opts = listOf("x ∈ <2/3, 3]", "x ∈ <3, +∞>", "x ∈ <1/3, 3>", "N.A.", "x ∈ <−∞, 2/3>"), vals = listOf("[2/3,3,0,1]", "[3,inf,0,0]", "[1/3,3,0,0]", "undef", "[-inf,2/3,0,0]"), correct = 0, check = "[solve(-4+3*x=-2,x)[0],solve(-4+3*x=5,x)[0],0,1]", steps = listOf("Sumamos 4 a las tres partes: 2 < 3x ≤ 9.", "Dividimos entre 3: 2/3 < x ≤ 3.", "El extremo 2/3 no se incluye y el 3 sí: <2/3, 3]."), theory = "Un intervalo se escribe con sus extremos. El extremo incluido lleva corchete cerrado y el no incluido lleva corchete abierto, que en la ficha también se escribe con < o >. Al multiplicar o dividir una desigualdad por un número negativo, el sentido se invierte. Una inecuación lineal se resuelve como una ecuación, cuidando de invertir el sentido si se multiplica o divide por un negativo.", idea = "Es una doble desigualdad: se opera en las tres partes a la vez.", mistake = "Cerrar el extremo 2/3, porque la primera desigualdad es estricta.", verify = "Con x = 3: −4 + 9 = 5 ≤ 5. Con x = 2/3: −4 + 2 = −2, que no es mayor que −2.", letters = "abcde", src = "ficha", group = "Semana 3 · Aritmética", num = 4))
        l.add(BProb(id = "s3arit_05", topic = "ineq", level = 2, text = "Hallar el conjunto solución de:\n2x + 1 ≤ x + 3 < 4x − 1", opts = listOf("[2, +∞[", "[4/3, +∞[", "φ", "<4/3, 2>", "<4/3, +2]"), vals = listOf("[2,inf,1,0]", "[4/3,inf,1,0]", "[]", "[4/3,2,0,0]", "[4/3,2,0,1]"), correct = 4, check = "[solve(x+3=4*x-1,x)[0],solve(2*x+1=x+3,x)[0],0,1]", steps = listOf("Primera: 2x + 1 ≤ x + 3 da x ≤ 2.", "Segunda: x + 3 < 4x − 1 da 4 < 3x, es decir x > 4/3.", "Intersección: 4/3 < x ≤ 2, que es <4/3, 2]."), note = "La alternativa e está escrita <4/3, +2] en la ficha. Es <4/3, 2].", theory = "Un intervalo se escribe con sus extremos. El extremo incluido lleva corchete cerrado y el no incluido lleva corchete abierto, que en la ficha también se escribe con < o >. Al multiplicar o dividir una desigualdad por un número negativo, el sentido se invierte. Una inecuación lineal se resuelve como una ecuación, cuidando de invertir el sentido si se multiplica o divide por un negativo.", idea = "Una desigualdad doble se separa en dos y se intersectan las soluciones.", mistake = "Responder <4/3, 2>, alternativa d, sin incluir el 2. Con ≤ el 2 sí está.", verify = "Con x = 2: 5 ≤ 5 < 7. Con x = 4/3: 13/3 no es menor que 13/3.", trap = "[4/3,2,0,0]", letters = "abcde", src = "ficha", group = "Semana 3 · Aritmética", num = 5, trapOpt = 3))
        l.add(BProb(id = "s3arit_06", topic = "ineq", level = 2, text = "Si x ∈ ]2, 4[ y luego\n§1/(2*x+3)\n, a qué intervalo pertenece:", opts = listOf("]1/11, 1/7[", "]−1/2, 1/6[", "]1/5, 1/3[", "]1/12, 3/4[", "]1/13, 1/6["), vals = listOf("[1/11,1/7,0,0]", "[-1/2,1/6,0,0]", "[1/5,1/3,0,0]", "[1/12,3/4,0,0]", "[1/13,1/6,0,0]"), correct = 0, check = "[1/(2*4+3),1/(2*2+3),0,0]", steps = listOf("2 < x < 4, así que 4 < 2x < 8 y 7 < 2x + 3 < 11.", "Al tomar el inverso de números positivos, el orden se invierte: 1/11 < 1/(2x + 3) < 1/7.", "Intervalo: ]1/11, 1/7[."), theory = "Un intervalo se escribe con sus extremos. El extremo incluido lleva corchete cerrado y el no incluido lleva corchete abierto, que en la ficha también se escribe con < o >. Al multiplicar o dividir una desigualdad por un número negativo, el sentido se invierte. Al invertir números positivos, el orden se invierte.", idea = "Primero se halla el intervalo de 2x + 3 y luego se invierte.", mistake = "Escribir 1/7 < ... < 1/11 sin invertir el orden.", verify = "Con x = 3: 1/9, que está entre 1/11 y 1/7.", letters = "abcde", src = "ficha", group = "Semana 3 · Aritmética", num = 6))
    }
    private fun p27(l: MutableList<BProb>) {
        l.add(BProb(id = "s3arit_07", topic = "ineq", level = 2, text = "Si: (2x − 1) ∈ [−5; 7>, entonces, ¿a qué intervalo pertenece \"x\"?", opts = listOf("x ∈ [−2 ; 4]", "x ∈ <−2 ; 4>", "x ∈ <−2 ; 4]", "x ∈ [−4 ; 2>", "x ∈ [−2 ; 4>"), vals = listOf("[-2,4,1,1]", "[-2,4,0,0]", "[-2,4,0,1]", "[-4,2,1,0]", "[-2,4,1,0]"), correct = 4, check = "[solve(2*x-1=-5,x)[0],solve(2*x-1=7,x)[0],1,0]", steps = listOf("−5 ≤ 2x − 1 < 7.", "Sumamos 1: −4 ≤ 2x < 8.", "Dividimos entre 2: −2 ≤ x < 4. El −2 se incluye y el 4 no: [−2 ; 4>."), theory = "Un intervalo se escribe con sus extremos. El extremo incluido lleva corchete cerrado y el no incluido lleva corchete abierto, que en la ficha también se escribe con < o >. Al multiplicar o dividir una desigualdad por un número negativo, el sentido se invierte.", idea = "Se despeja x en la doble desigualdad y se conserva si cada extremo se incluye o no.", mistake = "Cerrar el 4 por costumbre, alternativa a. El 7 del enunciado no se incluye.", verify = "Con x = −2: 2x − 1 = −5, incluido. Con x = 4: 7, que no está.", letters = "abcde", src = "ficha", group = "Semana 3 · Aritmética", num = 7))
        l.add(BProb(id = "s3arit_08", topic = "ineq", level = 2, text = "Si:\n§1/(2*x+8)\n∈ [1/12 ; 1/6]\nentonces: x ∈ [m ; n]. Halle: mn", opts = listOf("2", "−2", "−15", "−6", "−3"), vals = listOf("2", "-2", "-15", "-6", "-3"), correct = 1, check = "solve(2*x+8=6,x)[0]*solve(2*x+8=12,x)[0]", steps = listOf("1/12 ≤ 1/(2x + 8) ≤ 1/6. Al invertir, 6 ≤ 2x + 8 ≤ 12.", "Restamos 8: −2 ≤ 2x ≤ 4. Dividimos entre 2: −1 ≤ x ≤ 2.", "m = −1 y n = 2, así que mn = −2."), theory = "Un intervalo se escribe con sus extremos. El extremo incluido lleva corchete cerrado y el no incluido lleva corchete abierto, que en la ficha también se escribe con < o >. Al multiplicar o dividir una desigualdad por un número negativo, el sentido se invierte. Al invertir números positivos, el orden se invierte.", idea = "Se invierte la doble desigualdad y se despeja x.", mistake = "Intercambiar m y n o multiplicar mal y obtener −3.", verify = "Con x = −1: 1/6 y con x = 2: 1/12. Los dos extremos del intervalo.", letters = "abcde", src = "ficha", group = "Semana 3 · Aritmética", num = 8))
        l.add(BProb(id = "s3arit_09", topic = "ineq", level = 2, text = "Dar como respuesta el número de soluciones enteras\n2x − 5 < x + 3 < 3x − 7", opts = listOf("1", "2", "3", "4", "5"), vals = listOf("1", "2", "3", "4", "5"), correct = 1, check = "size(seq(x,x,floor(solve(x+3=3*x-7,x)[0])+1,ceil(solve(2*x-5=x+3,x)[0])-1))", steps = listOf("Primera: 2x − 5 < x + 3 da x < 8.", "Segunda: x + 3 < 3x − 7 da 10 < 2x, es decir x > 5.", "5 < x < 8: los enteros son 6 y 7. Son 2 soluciones."), theory = "Una inecuación lineal se resuelve como una ecuación, cuidando de invertir el sentido si se multiplica o divide por un negativo.", idea = "Se separan las dos desigualdades y se intersectan.", mistake = "Contar el 5 y el 8, que no están porque las desigualdades son estrictas.", verify = "Con x = 6: 7 < 9 < 11. Con x = 7: 9 < 10 < 14.", letters = "abcde", src = "ficha", group = "Semana 3 · Aritmética", num = 9))
        l.add(BProb(id = "s3arit_10", topic = "ineq", level = 3, text = "Si: x ∈ <−2;4>\nAdemás\n§(x+1)/(x+3)\n∈ <−c; a/b>\nHallar: \"a + b\"", opts = listOf("2", "4", "16", "6", "12"), vals = listOf("2", "4", "16", "6", "12"), correct = 4, check = "numer((4+1)/(4+3))+denom((4+1)/(4+3))", steps = listOf("−2 < x < 4, así que 1 < x + 3 < 7.", "Al invertir: 1/7 < 1/(x + 3) < 1. Por 2: 2/7 < 2/(x + 3) < 2.", "Al multiplicar por −1: −2 < −2/(x + 3) < −2/7. Sumamos 1: −1 < (x + 1)/(x + 3) < 5/7.", "Entonces −c = −1, es decir c = 1, y a/b = 5/7. Con a = 5 y b = 7, a + b = 12."), note = "Se toma a/b = 5/7 como fracción irreducible.", theory = "Un intervalo se escribe con sus extremos. El extremo incluido lleva corchete cerrado y el no incluido lleva corchete abierto, que en la ficha también se escribe con < o >. Al multiplicar o dividir una desigualdad por un número negativo, el sentido se invierte.", idea = "(x + 1)/(x + 3) = 1 − 2/(x + 3). Se sigue el intervalo paso a paso.", mistake = "Olvidar que multiplicar por −1 invierte el orden de la desigualdad.", verify = "Con x = 4: 5/7, el extremo de arriba. Con x = −2: −1/1 = −1, el de abajo.", letters = "abcde", src = "ficha", group = "Semana 3 · Aritmética", num = 10))
        l.add(BProb(id = "s3arit_11", topic = "ineq", level = 3, text = "El número de plumas contenidas en una caja es tal que su duplo, disminuido en 86, es mayor que 200. De la caja se sacan 17 y quedan menos que la diferencia entre 200 y la mitad de las que había inicialmente. ¿Cuántas eran éstas?", opts = listOf("156", "188", "144", "123", "132"), vals = listOf("156", "188", "144", "123", "132"), correct = 2, check = "max(select(n->2*n-86>200 and n-17<200-n/2,seq(n,n,100,200)))", steps = listOf("2n − 86 > 200 da n > 143.", "n − 17 < 200 − n/2 da 3n/2 < 217, es decir n < 144,67.", "143 < n < 144,67 y n entero: n = 144."), theory = "En los problemas de planteo, los datos se vuelven desigualdades con la misma incógnita. Si la incógnita cuenta objetos, solo valen números enteros.", idea = "Dos desigualdades sobre el mismo número n.", mistake = "Olvidar que n debe ser entero y dejar el intervalo sin decidir.", verify = "Con n = 144: 288 − 86 = 202 > 200, y 127 < 200 − 72 = 128.", letters = "abcde", src = "ficha", group = "Semana 3 · Aritmética", num = 11))
        l.add(BProb(id = "s3arit_12", topic = "ineq", level = 3, text = "Un número entero y positivo, es tal que la tercera parte del que le precede, disminuida en 10, es mayor que 14, y que la cuarta parte del que le sigue, aumentada en 10, es menor que 29. ¿Con qué cifra comienza el número?", opts = listOf("5", "7", "9", "8", "4"), vals = listOf("5", "7", "9", "8", "4"), correct = 1, check = "floor(select(n->(n-1)/3-10>14 and (n+1)/4+10<29,seq(n,n,1,200))[0]/10)", steps = listOf("(n − 1)/3 − 10 > 14 da (n − 1)/3 > 24, es decir n > 73.", "(n + 1)/4 + 10 < 29 da (n + 1)/4 < 19, es decir n < 75.", "73 < n < 75 y n entero: n = 74.", "El número empieza con 7."), theory = "En los problemas de planteo, los datos se vuelven desigualdades con la misma incógnita. Si la incógnita cuenta objetos, solo valen números enteros.", idea = "El que le precede es n − 1 y el que le sigue es n + 1.", mistake = "Responder 74, que no es una cifra.", verify = "Con n = 74: 73/3 − 10 = 14,33 > 14 y 75/4 + 10 = 28,75 < 29.", letters = "abcde", src = "ficha", group = "Semana 3 · Aritmética", num = 12))
        l.add(BProb(id = "s3arit_13", topic = "ineq", level = 3, text = "Entre Pedro y Luis tienen menos de 8 hijos. Luis tiene más hijos que Ramón y aunque Pedro tuviera tres hijos menos, seguiría teniendo más hijos que Ramón. ¿Cuántos hijos tiene Ramón?", opts = listOf("2", "1", "3", "5", "N.A."), vals = listOf("2", "1", "3", "5", "undef"), correct = 1, check = "max(select(R->size(select(L->size(select(P->P+L<8 and L>R and P-3>R,seq(P,P,0,10)))>0,seq(L,L,0,10)))>0,seq(R,R,0,10)))", steps = listOf("Sean P, L y R los hijos de Pedro, Luis y Ramón. Se pide P + L < 8, L > R y P − 3 > R.", "Con enteros: L ≥ R + 1 y P ≥ R + 4, así que P + L ≥ 2R + 5.", "2R + 5 ≤ 7 da R ≤ 1.", "Como el enunciado habla de los hijos de Ramón, se toma R = 1: por ejemplo Pedro 5, Luis 2 y Ramón 1."), note = "Con R = 0 también se cumplen las condiciones, por ejemplo Pedro 4 y Luis 1. La respuesta 1 supone que Ramón tiene al menos un hijo. La academia debe confirmar la clave.", theory = "En los problemas de planteo, los datos se vuelven desigualdades con la misma incógnita. Si la incógnita cuenta objetos, solo valen números enteros.", idea = "Con R los hijos de Ramón: L ≥ R + 1 y P − 3 ≥ R + 1, luego P + L ≥ 2R + 5.", mistake = "Aceptar R = 0 sin notar que el enunciado se refiere a los hijos de Ramón.", verify = "Con R = 1, P = 5 y L = 2: 5 + 2 = 7 < 8, 2 > 1 y 5 − 3 = 2 > 1.", letters = "abcde", src = "ficha", group = "Semana 3 · Aritmética", num = 13, review = true))
        l.add(BProb(id = "s3arit_14", topic = "ineq", level = 3, text = "La tercera parte de cierto número disminuida en 3 es mayor que 25; pero la cuarta parte del mismo número disminuida en 2 es menor que 20. ¿De qué número como máximo se trata?", opts = listOf("84", "85", "87", "81", "80"), vals = listOf("84", "85", "87", "81", "80"), correct = 2, check = "max(select(N->N/3-3>25 and N/4-2<20,seq(N,N,0,200)))", steps = listOf("N/3 − 3 > 25 da N/3 > 28, es decir N > 84.", "N/4 − 2 < 20 da N/4 < 22, es decir N < 88.", "84 < N < 88: N puede ser 85, 86 o 87. El máximo es 87."), note = "Se entiende que el número es entero.", theory = "En los problemas de planteo, los datos se vuelven desigualdades con la misma incógnita. Si la incógnita cuenta objetos, solo valen números enteros.", idea = "Dos desigualdades sobre el mismo número, que se asume entero.", mistake = "Marcar 85, el menor valor posible, en vez del máximo.", verify = "Con N = 87: 29 − 3 = 26 > 25 y 21,75 − 2 = 19,75 < 20.", letters = "abcde", src = "ficha", group = "Semana 3 · Aritmética", num = 14))
    }
    private fun p28(l: MutableList<BProb>) {
        l.add(BProb(id = "s3arit_15", topic = "ineq", level = 3, text = "El número de plumas contenidas en una caja es tal, que su duplo disminuido en 86, es mayor que 200. De la caja se sacan 17 plumas y quedan menos que la diferencia entre 200 y la mitad de plumas que había al inicio. ¿Cuántas eran éstas?", opts = listOf("140", "142", "144", "146", "138"), vals = listOf("140", "142", "144", "146", "138"), correct = 2, check = "max(select(n->2*n-86>200 and n-17<200-n/2,seq(n,n,100,200)))", steps = listOf("2n − 86 > 200 da n > 143.", "n − 17 < 200 − n/2 da n < 144,67.", "n = 144."), note = "Este problema es igual al 11 de la misma ficha, con otras alternativas.", theory = "En los problemas de planteo, los datos se vuelven desigualdades con la misma incógnita. Si la incógnita cuenta objetos, solo valen números enteros.", idea = "Es el mismo problema que el 11 de esta ficha.", mistake = "Elegir 146 o 142 por cercanía sin comprobar la segunda condición.", verify = "Con n = 144: 202 > 200 y 127 < 128.", letters = "abcde", src = "ficha", group = "Semana 3 · Aritmética", num = 15))
        l.add(BProb(id = "s3arit_16", topic = "ineq", level = 3, text = "En un examen de RM 3 alumnos: A, B y C, resolvieron correctamente más de 13 problemas en total. Si A hubiera resuelto 3 problemas más, habría tenido mayor número de problemas resueltos que B y C juntos, sin embargo, A resolvió menor cantidad de problemas que C, y los que éste resolvió no llegaron a 8. Calcule cuántos problemas resolvió B.", opts = listOf("1", "2", "0", "3", "4"), vals = listOf("1", "2", "0", "3", "4"), correct = 0, check = "select(B->size(select(A->size(select(C->A+B+C>13 and A+3>B+C and A<C and C<8,seq(C,C,0,20)))>0,seq(A,A,0,20)))>0,seq(B,B,0,20))[0]", steps = listOf("Datos: A + B + C > 13, A + 3 > B + C, A < C y C < 8.", "C ≤ 7 y A < C, así que A ≤ 6.", "De A + 3 > B + C se tiene B + C ≤ A + 2, y entonces A + B + C ≤ 2A + 2. Como A + B + C ≥ 14, resulta 2A + 2 ≥ 14, es decir A ≥ 6.", "A = 6 y C = 7. Entonces B + 7 ≤ 8 da B ≤ 1, y 6 + B + 7 ≥ 14 da B ≥ 1. B = 1."), theory = "En los problemas de planteo, los datos se vuelven desigualdades con la misma incógnita. Si la incógnita cuenta objetos, solo valen números enteros.", idea = "Se escribe cada dato como desigualdad y se acota C, luego A y luego B.", mistake = "Dejar B = 0 por ser el menor, alternativa c. Con B = 0 la suma sería 13 y no cumple más de 13.", verify = "Con A = 6, B = 1 y C = 7: 14 > 13, 9 > 8, 6 < 7 y 7 < 8.", letters = "abcde", src = "ficha", group = "Semana 3 · Aritmética", num = 16))
        l.add(BProb(id = "s3arit_17", topic = "ineq", level = 3, text = "Se tiene un número de dos cifras. El duplo de la cifra de las decenas, restado de la cifra de las unidades, es mayor que 5, y la diferencia entre 14 veces la cifra de las unidades y la cifra de las decenas es menor que 112. ¿Cuál es el número?", opts = listOf("81", "18", "19", "91", "72"), vals = listOf("81", "18", "19", "91", "72"), correct = 1, check = "select(n->irem(n,10)-2*iquo(n,10)>5 and 14*irem(n,10)-iquo(n,10)<112,seq(n,n,10,99))[0]", steps = listOf("Condiciones: u − 2d > 5 y 14u − d < 112.", "De la primera, u ≥ 2d + 6. Con d = 1: u = 8 o 9. Con d = 2: u ≥ 10, imposible.", "Con d = 1: 14u − 1 < 112 da u < 8,07, así que u = 8.", "El número es 18."), note = "Restado de la cifra de las unidades significa unidades menos el duplo de las decenas.", theory = "En los problemas de planteo, los datos se vuelven desigualdades con la misma incógnita. Si la incógnita cuenta objetos, solo valen números enteros.", idea = "Con d decenas y u unidades, el duplo de d restado de u es u − 2d.", mistake = "Calcular 2d − u en lugar de u − 2d. Con 2d − u > 5 varios números cumplen, como 81, 91 y 72.", verify = "u − 2d = 8 − 2 = 6 > 5 y 14·8 − 1 = 111 < 112.", letters = "abcde", src = "ficha", group = "Semana 3 · Aritmética", num = 17))
        l.add(BProb(id = "s3arit_18", topic = "ineq", level = 3, text = "Yo tengo tres canicas más que tú. Si duplicase el número de canicas que tengo y tú triplicases el número de canicas que tienes, el producto del número de canicas que tendríamos sería mayor que 1080. ¿Cuántas canicas tengo como mínimo?", opts = listOf("15", "12", "13", "14", "16"), vals = listOf("15", "12", "13", "14", "16"), correct = 4, check = "min(select(a->2*a*3*(a-3)>1080,seq(a,a,3,100)))", steps = listOf("Yo: t + 3. Duplicado: 2(t + 3). Tú triplicado: 3t.", "6t(t + 3) > 1080, es decir t² + 3t − 180 > 0.", "Se factoriza: (t − 12)(t + 15) > 0. Como t > 0, t > 12 y t ≥ 13.", "Yo tengo t + 3 ≥ 16."), theory = "En los problemas de planteo, los datos se vuelven desigualdades con la misma incógnita. Si la incógnita cuenta objetos, solo valen números enteros.", idea = "Si t son las canicas del otro, yo tengo t + 3. Se obtiene una desigualdad cuadrática.", mistake = "Tomar t = 12 y responder 15, alternativa a. Con t = 12 el producto vale justo 1080 y no lo supera.", verify = "Con t = 13: 6·13·16 = 1248 > 1080. Con t = 12: 6·12·15 = 1080, que no es mayor.", letters = "abcde", src = "ficha", group = "Semana 3 · Aritmética", num = 18))
        l.add(BProb(id = "s3arit_19", topic = "ineq", level = 3, text = "El número de manzanas que tengo está entre 370 y 470. Si las cuento por decenas me sobran 7, si las cuento por docenas me sobran 9 y si las cuento de 15 en 15 me sobran 12. ¿Cuántas manzanas tengo?", opts = listOf("437", "417", "427", "447", "457"), vals = listOf("437", "417", "427", "447", "457"), correct = 1, check = "select(N->irem(N,10)==7 and irem(N,12)==9 and irem(N,15)==12,seq(N,N,371,469))[0]", steps = listOf("N deja 7 al dividir entre 10, es decir N + 3 es múltiplo de 10. Igual para 12 (9) y 15 (12).", "N + 3 es múltiplo de MCM(10, 12, 15) = 60.", "N = 60k − 3: 357, 417, 477, …", "El único entre 370 y 470 es 417."), theory = "Si al dividir entre varios números sobra siempre una cantidad que le falta 3 a cada divisor, el número más 3 es múltiplo de todos los divisores.", idea = "Los residuos 7, 9 y 12 son los divisores menos 3.", mistake = "Elegir 437, que deja 7 con 10 pero no cumple con 12.", verify = "417 = 41·10 + 7 = 34·12 + 9 = 27·15 + 12.", letters = "abcde", src = "ficha", group = "Semana 3 · Aritmética", num = 19))
        l.add(BProb(id = "s3arit_20", topic = "ineq", level = 2, text = "La cantidad de canicas que tiene Jaimito es tal que, uno más el triple de dicho número es menor que 46; y uno más su cuádruplo es más que 53. ¿Cuántas canicas tiene Jaimito?", opts = listOf("10", "11", "12", "13", "14"), vals = listOf("10", "11", "12", "13", "14"), correct = 4, check = "select(x->1+3*x<46 and 1+4*x>53,seq(x,x,0,60))[0]", steps = listOf("1 + 3x < 46 da x < 15.", "1 + 4x > 53 da x > 13.", "13 < x < 15 y x entero: x = 14."), theory = "En los problemas de planteo, los datos se vuelven desigualdades con la misma incógnita. Si la incógnita cuenta objetos, solo valen números enteros.", idea = "Dos desigualdades sobre las canicas x.", mistake = "Quedarse con 13 o 15, que no cumplen alguna de las desigualdades estrictas.", verify = "Con x = 14: 43 < 46 y 57 > 53.", letters = "abcde", src = "ficha", group = "Semana 3 · Aritmética", num = 20))
        l.add(BProb(id = "s3arit_21", topic = "ineq", level = 3, text = "La edad de A es a la de B como 7 es a 9. Si el quíntuplo de A excede al triple de B en más de 16 años y B no es mayor que 40 años, entonces la máxima y mínima edad que puede tener A es:", opts = listOf("21 y 18", "24 y 21", "26 y 24", "32 y 25", "28 y 21"), vals = listOf("[21,18]", "[24,21]", "[26,24]", "[32,25]", "[28,21]"), correct = 4, check = "[7*max(select(k->35*k-27*k>16 and 9*k<=40,seq(k,k,1,20))),7*min(select(k->35*k-27*k>16 and 9*k<=40,seq(k,k,1,20)))]", steps = listOf("A = 7k y B = 9k.", "5A − 3B > 16 da 35k − 27k > 16, es decir 8k > 16 y k > 2.", "B ≤ 40 da 9k ≤ 40, es decir k ≤ 4,4.", "k = 3 o 4. A = 21 o 28: máxima 28 y mínima 21."), theory = "En los problemas de planteo, los datos se vuelven desigualdades con la misma incógnita. Si la incógnita cuenta objetos, solo valen números enteros. Una razón 7 a 9 se escribe A = 7k y B = 9k.", idea = "Se escribe todo con k y se busca los valores enteros de k.", mistake = "Permitir k = 2: A = 14 y B = 18, con 70 − 54 = 16, que no es más de 16.", verify = "Con k = 3: A = 21 y B = 27, y 105 − 81 = 24 > 16. Con k = 4: A = 28 y B = 36, y 140 − 108 = 32 > 16.", letters = "abcde", src = "ficha", group = "Semana 3 · Aritmética", num = 21))
        l.add(BProb(id = "s3arit_22", topic = "ineq", level = 3, text = "Iván tiene más de 3 hijos y Pedro menos de 9 hijos. Si juntos tienen menos de 8 hijos, ¿Cuántos miembros como máximo tiene la familia de Pedro en la casa donde viven, sabiendo que además vive con su suegro y su suegra?", opts = listOf("5", "9", "8", "6", "7"), vals = listOf("5", "9", "8", "6", "7"), correct = 4, check = "max(select(P->P<9 and size(select(I->I>3 and I+P<8,seq(I,I,0,20)))>0,seq(P,P,0,20)))+4", steps = listOf("Iván tiene al menos 4 hijos. Juntos tienen menos de 8, es decir a lo sumo 7.", "Pedro tiene como máximo 7 − 4 = 3 hijos.", "Familia de Pedro: él, su esposa, sus 3 hijos, su suegro y su suegra: 1 + 1 + 3 + 2 = 7."), note = "Se cuenta a Pedro y a su esposa, ya que el enunciado dice que vive con su suegro y su suegra.", theory = "En los problemas de planteo, los datos se vuelven desigualdades con la misma incógnita. Si la incógnita cuenta objetos, solo valen números enteros.", idea = "Iván tiene al menos 4 hijos, así que a Pedro le quedan pocos.", mistake = "No contar a la esposa de Pedro y obtener 6, alternativa d.", verify = "Con 3 hijos Pedro e Iván suman 7 hijos, que es menos de 8.", letters = "abcde", src = "ficha", group = "Semana 3 · Aritmética", num = 22))
    }
    private fun p29(l: MutableList<BProb>) {
        l.add(BProb(id = "s3arit_23", topic = "ineq", level = 3, text = "En el mes de noviembre, cumplió años Cecilia; si el triple del día en que nació ella es menor que el día en que nació Alfredo, y además el día en que nació Cecilia supera al mes en que nació Alfredo. Si Alfredo nació después del mes de mayo y un día que tiene la particularidad de tener sus cifras iguales. ¿En qué fechas cumplieron años Cecilia y Alfredo?", opts = listOf("7 de noviembre - 11 de junio", "7 de noviembre - 22 de junio", "6 de junio - 11 de noviembre", "9 de noviembre - 22 de junio", "N.A."), vals = listOf("(3*7<11 and 7>6 and 6>=6)", "(3*7<22 and 7>6 and 6>=6)", "(6==11 and 3*6<11 and 6>11)", "(3*9<22 and 9>6 and 6>=6)", "false"), correct = 1, check = "true", steps = listOf("Condiciones: 3c < a, c > m, m ≥ 6 y a = 11 o 22.", "Si a = 11, 3c < 11 da c ≤ 3, pero c > m ≥ 6. Imposible.", "Si a = 22, 3c < 22 da c ≤ 7, y c > m ≥ 6 da c = 7 y m = 6.", "Cecilia: 7 de noviembre. Alfredo: 22 de junio."), note = "Cada alternativa se comprueba como una condición que debe ser verdadera: solo la b cumple todo.", theory = "Se traducen las condiciones a desigualdades sobre el día c de Cecilia, el día a de Alfredo y su mes m.", idea = "Alfredo nació un día de cifras iguales: 11 o 22. Cecilia en noviembre.", mistake = "Elegir la a, que tiene 11 de junio. Con a = 11, el triple del día de Cecilia ya no es menor que a.", verify = "3·7 = 21 < 22, 7 > 6 y junio es el mes 6, después de mayo.", letters = "abcde", src = "ficha", group = "Semana 3 · Aritmética", num = 23))
        l.add(BProb(id = "s3arit_24", topic = "ineq", level = 3, text = "Si el número de coches se redujera a la sexta parte se ocuparía menos de la décima parte de la capacidad del estacionamiento; pero si se tratara de duplicar el número de coches; más de ocho coches no podrán ser estacionados por falta de espacio. ¿Cuántos coches hay en el estacionamiento?", opts = listOf("24", "35", "36", "28", "61"), vals = listOf("24", "35", "36", "28", "61"), correct = -1, check = "floor(solve(5*N/3=2*N-8,N)[0])+1", steps = listOf("N/6 < K/10 da K > 5N/3.", "2N − K > 8 da K < 2N − 8.", "5N/3 < K < 2N − 8 exige 5N/3 < 2N − 8, es decir N > 24.", "Con esa información cualquier N mayor que 24 con un K entero entre esos límites sirve: por ejemplo N = 28 con K = 47, o N = 35 con K = 60."), theory = "En los problemas de planteo, los datos se vuelven desigualdades con la misma incógnita. Si la incógnita cuenta objetos, solo valen números enteros.", idea = "Con N coches y capacidad K, el enunciado da dos desigualdades con dos incógnitas.", mistake = "Marcar una alternativa sin probar que las otras no sirven. Las alternativas 28, 35, 36 y 61 cumplen las dos condiciones.", verify = "Con N = 35 y K = 60: 35/6 = 5,8 < 6 y 70 − 60 = 10 > 8. Con N = 28 y K = 47: 4,67 < 4,7 y 56 − 47 = 9 > 8.", warn = "Con los datos de la ficha, el número de coches no queda determinado: falta la capacidad del estacionamiento. Varias alternativas cumplen.", letters = "abcde", src = "ficha", group = "Semana 3 · Aritmética", answer = "Solo se puede concluir que N es mayor que 24. Varias alternativas sirven.", answerVal = "25", num = 24, review = true))
        l.add(BProb(id = "s3arit_25", topic = "ineq", level = 2, text = "Si el doble de la edad de Ana no es menor que 57 y el triple de la edad de Ana no es mayor que 96. ¿Cuál es la máxima diferencia entre la edad de Ana con la de Luis que tiene 20 años?", opts = listOf("10", "11", "12", "13", "14"), vals = listOf("10", "11", "12", "13", "14"), correct = 2, check = "max(seq(abs(a-20),a,ceil(57/2),floor(96/3)))", steps = listOf("2a ≥ 57 da a ≥ 28,5, es decir a ≥ 29 si la edad es entera.", "3a ≤ 96 da a ≤ 32.", "La edad de Ana está entre 29 y 32. La diferencia con 20 es mayor para a = 32: 12."), note = "Se entiende que las edades son enteras.", theory = "En los problemas de planteo, los datos se vuelven desigualdades con la misma incógnita. Si la incógnita cuenta objetos, solo valen números enteros.", idea = "No es menor que se escribe ≥ y no es mayor que se escribe ≤.", mistake = "Tomar a = 28,5 y obtener 8,5, que no está entre las alternativas.", verify = "Con a = 32: 64 ≥ 57 y 96 ≤ 96, y 32 − 20 = 12.", letters = "abcde", src = "ficha", group = "Semana 3 · Aritmética", num = 25))
        l.add(BProb(id = "s3arit_26", topic = "ineq", level = 2, text = "La cantidad de canicas que tiene Jaimito es tal que, uno más el triple de dicho número es menor que 46; y uno más su cuádruplo es más que 53. ¿Cuántas canicas tiene Jaimito?", opts = listOf("10", "11", "12", "13", "14"), vals = listOf("10", "11", "12", "13", "14"), correct = 4, check = "select(x->1+3*x<46 and 1+4*x>53,seq(x,x,0,60))[0]", steps = listOf("1 + 3x < 46 da x < 15.", "1 + 4x > 53 da x > 13.", "x = 14."), note = "Este problema es igual al 20 de la misma ficha.", theory = "En los problemas de planteo, los datos se vuelven desigualdades con la misma incógnita. Si la incógnita cuenta objetos, solo valen números enteros.", idea = "Es el mismo problema que el 20 de esta ficha.", mistake = "Quedarse con 13 o 15.", verify = "Con x = 14: 43 < 46 y 57 > 53.", letters = "abcde", src = "ficha", group = "Semana 3 · Aritmética", num = 26))
        l.add(BProb(id = "s3arit_27", topic = "ineq", level = 2, text = "El quíntuplo del número de nietos que tiene don Federico, disminuido en 1 es menor que el cuadrado de 7; y siete veces dicho número, aumentado en 8, excede al cuadrado de 8. ¿Cuántos nietos tiene don Federico?", opts = listOf("8", "9", "10", "7", "11"), vals = listOf("8", "9", "10", "7", "11"), correct = 1, check = "select(n->5*n-1<49 and 7*n+8>64,seq(n,n,0,50))[0]", steps = listOf("5n − 1 < 49 da 5n < 50, es decir n < 10.", "7n + 8 > 64 da 7n > 56, es decir n > 8.", "8 < n < 10: n = 9."), theory = "En los problemas de planteo, los datos se vuelven desigualdades con la misma incógnita. Si la incógnita cuenta objetos, solo valen números enteros.", idea = "El cuadrado de 7 es 49 y el de 8 es 64.", mistake = "Confundir el cuadrado de 7 con su doble, 14. El cuadrado de 7 es 49.", verify = "Con n = 9: 44 < 49 y 71 > 64.", letters = "abcde", src = "ficha", group = "Semana 3 · Aritmética", num = 27))
        l.add(BProb(id = "s3arit_28", topic = "ineq", level = 3, text = "En un aula de la ACADEMIA YOMI, el número de varones es al de mujeres como 3 es a 2. El triple del número de alumnos, menos 10 es menor que 66, mas 1 es mayor que 50. Hallar el número de mujeres del aula.", opts = listOf("6", "12", "15", "10", "5"), vals = listOf("6", "12", "15", "10", "5"), correct = 3, check = "max(select(n->irem(n,5)==0 and 3*n-10<66 and 3*n-10+1>50,seq(n,n,1,100)))*2/5", steps = listOf("Varones 3k y mujeres 2k, con n = 5k alumnos.", "3n − 10 < 66 da n < 25,3. Y 3n − 10 + 1 > 50 da n > 19,7.", "n entero y múltiplo de 5 con 19,7 < n < 25,3: n = 20 o n = 25.", "Mujeres: 2k = 8 si n = 20 o 10 si n = 25. Solo 10 está entre las alternativas."), note = "El enunciado admite también 8 mujeres, pero ese valor no está entre las alternativas. La respuesta de la ficha es 10.", theory = "En los problemas de planteo, los datos se vuelven desigualdades con la misma incógnita. Si la incógnita cuenta objetos, solo valen números enteros. Una razón 3 a 2 hace que el total sea múltiplo de 5.", idea = "Con n alumnos, n es múltiplo de 5 y las mujeres son 2n/5.", mistake = "No notar que n = 20 también cumple y quedarse con la primera idea.", verify = "Con n = 25: 3·25 − 10 = 65 < 66 y 65 + 1 = 66 > 50.", letters = "abcde", src = "ficha", group = "Semana 3 · Aritmética", num = 28, review = true))
        l.add(BProb(id = "s3arit_29", topic = "ineq", level = 2, text = "Hallar el número entero y positivo que sumado con 11 resulte mayor que el triple de él, disminuido en 7 y que sumado con 5 resulte menos que el doble de él; disminuido en 2.", opts = listOf("6", "7", "8", "9", "10"), vals = listOf("6", "7", "8", "9", "10"), correct = 2, check = "select(n->n+11>3*n-7 and n+5<2*n-2,seq(n,n,1,50))[0]", steps = listOf("n + 11 > 3n − 7 da 18 > 2n, es decir n < 9.", "n + 5 < 2n − 2 da 7 < n.", "7 < n < 9: n = 8."), theory = "En los problemas de planteo, los datos se vuelven desigualdades con la misma incógnita. Si la incógnita cuenta objetos, solo valen números enteros.", idea = "El número es n: n + 11 > 3n − 7 y n + 5 < 2n − 2.", mistake = "Elegir 9 por seguir la desigualdad de arriba. Con 9, 20 > 20 es falso.", verify = "Con n = 8: 19 > 17 y 13 < 14.", letters = "abcde", src = "ficha", group = "Semana 3 · Aritmética", num = 29))
        l.add(BProb(id = "s3est_01", topic = "est", level = 1, text = "En un estudio sobre el peso (en kg) de 40 postulantes a una beca deportiva, se construyó la siguiente tabla de frecuencias agrupadas: (Responder desde el 1 al 5)\n[tabla]\n¿Qué porcentaje de postulantes pesan menos de 66 kg?", opts = listOf("50%", "55%", "60%", "65%"), vals = listOf("50", "55", "60", "65"), correct = 1, check = "22/40*100", steps = listOf("Frecuencia acumulada hasta [60; 66): 22.", "22/40 = 0,55 = 55%."), note = "La tabla es compartida por las preguntas 1 a 5.", theory = "En una tabla de frecuencias agrupadas: fi es la frecuencia absoluta, Fi la acumulada, hi la relativa y Hi la relativa acumulada. La marca de clase de un intervalo es el promedio de sus extremos. La media aproximada es la suma de marca por frecuencia dividida entre el total. Los porcentajes salen de dividir entre el total.", idea = "Los que pesan menos de 66 kg son los de los tres primeros intervalos.", mistake = "Contar también el intervalo [66; 72) y obtener 80%.", verify = "22 de 40 es 55%.", letters = "abcd", src = "ficha", group = "Semana 3 · Estadística", table = listOf(listOf("Peso (kg)", "Xi", "fi", "Fi", "hi", "Hi"), listOf("[48; 54)", "51", "2", "2", "2/40", "2/40"), listOf("[54; 60)", "57", "6", "8", "6/40", "8/40"), listOf("[60; 66)", "63", "14", "22", "14/40", "22/40"), listOf("[66; 72)", "69", "10", "32", "10/40", "32/40"), listOf("[72; 78)", "75", "5", "37", "5/40", "37/40"), listOf("[78; 84)", "81", "3", "40", "3/40", "40/40")), num = 1))
    }
    private fun p30(l: MutableList<BProb>) {
        l.add(BProb(id = "s3est_02", topic = "est", level = 1, text = "En un estudio sobre el peso (en kg) de 40 postulantes a una beca deportiva, se construyó la siguiente tabla de frecuencias agrupadas: (Responder desde el 1 al 5)\n[tabla]\nCalcule la suma de la marca de clase del segundo intervalo con la del quinto intervalo.", opts = listOf("128", "130", "132", "135"), vals = listOf("128", "130", "132", "135"), correct = 2, check = "(54+60)/2+(72+78)/2", steps = listOf("Segundo intervalo [54; 60): marca (54 + 60)/2 = 57.", "Quinto intervalo [72; 78): marca (72 + 78)/2 = 75.", "Suma: 57 + 75 = 132."), theory = "En una tabla de frecuencias agrupadas: fi es la frecuencia absoluta, Fi la acumulada, hi la relativa y Hi la relativa acumulada. La marca de clase de un intervalo es el promedio de sus extremos. La media aproximada es la suma de marca por frecuencia dividida entre el total. Los porcentajes salen de dividir entre el total.", idea = "La marca de clase es el punto medio del intervalo.", mistake = "Tomar el cuarto intervalo en lugar del quinto.", verify = "Las marcas coinciden con la columna Xi de la tabla: 57 y 75.", letters = "abcd", src = "ficha", group = "Semana 3 · Estadística", table = listOf(listOf("Peso (kg)", "Xi", "fi", "Fi", "hi", "Hi"), listOf("[48; 54)", "51", "2", "2", "2/40", "2/40"), listOf("[54; 60)", "57", "6", "8", "6/40", "8/40"), listOf("[60; 66)", "63", "14", "22", "14/40", "22/40"), listOf("[66; 72)", "69", "10", "32", "10/40", "32/40"), listOf("[72; 78)", "75", "5", "37", "5/40", "37/40"), listOf("[78; 84)", "81", "3", "40", "3/40", "40/40")), num = 2))
        l.add(BProb(id = "s3est_03", topic = "est", level = 1, text = "En un estudio sobre el peso (en kg) de 40 postulantes a una beca deportiva, se construyó la siguiente tabla de frecuencias agrupadas: (Responder desde el 1 al 5)\n[tabla]\nDetermine la suma de las frecuencias absolutas de los últimos tres intervalos de la tabla.", opts = listOf("16", "18", "20", "22"), vals = listOf("16", "18", "20", "22"), correct = 1, check = "10+5+3", steps = listOf("Últimos tres intervalos: [66; 72), [72; 78) y [78; 84).", "fi: 10, 5 y 3.", "Suma: 10 + 5 + 3 = 18."), theory = "En una tabla de frecuencias agrupadas: fi es la frecuencia absoluta, Fi la acumulada, hi la relativa y Hi la relativa acumulada. La marca de clase de un intervalo es el promedio de sus extremos. La media aproximada es la suma de marca por frecuencia dividida entre el total. Los porcentajes salen de dividir entre el total.", idea = "Las frecuencias absolutas son la columna fi.", mistake = "Sumar las frecuencias acumuladas, 32 + 37 + 40, en lugar de las absolutas.", verify = "40 − 22 = 18, porque las demás suman 22.", letters = "abcd", src = "ficha", group = "Semana 3 · Estadística", table = listOf(listOf("Peso (kg)", "Xi", "fi", "Fi", "hi", "Hi"), listOf("[48; 54)", "51", "2", "2", "2/40", "2/40"), listOf("[54; 60)", "57", "6", "8", "6/40", "8/40"), listOf("[60; 66)", "63", "14", "22", "14/40", "22/40"), listOf("[66; 72)", "69", "10", "32", "10/40", "32/40"), listOf("[72; 78)", "75", "5", "37", "5/40", "37/40"), listOf("[78; 84)", "81", "3", "40", "3/40", "40/40")), num = 3))
        l.add(BProb(id = "s3est_04", topic = "est", level = 2, text = "En un estudio sobre el peso (en kg) de 40 postulantes a una beca deportiva, se construyó la siguiente tabla de frecuencias agrupadas: (Responder desde el 1 al 5)\n[tabla]\nCalcule la media aproximada.", opts = listOf("64.8 kg", "66.3 kg", "67.2 kg", "68.0 kg"), vals = listOf("648/10", "663/10", "672/10", "680/10"), correct = -1, check = "(51*2+57*6+63*14+69*10+75*5+81*3)/40", steps = listOf("Productos: 51·2 = 102, 57·6 = 342, 63·14 = 882, 69·10 = 690, 75·5 = 375 y 81·3 = 243.", "Suma: 2634.", "Media: 2634/40 = 65,85 kg."), theory = "En una tabla de frecuencias agrupadas: fi es la frecuencia absoluta, Fi la acumulada, hi la relativa y Hi la relativa acumulada. La marca de clase de un intervalo es el promedio de sus extremos. La media aproximada es la suma de marca por frecuencia dividida entre el total. Los porcentajes salen de dividir entre el total.", idea = "Se multiplica cada marca de clase por su frecuencia.", mistake = "Marcar 66,3 kg por cercanía. El valor exacto es 65,85.", verify = "65,85 está entre las marcas 63 y 69, más cerca de 63 por la frecuencia alta.", warn = "Con la tabla tal cual, la media es 65,85 kg y ninguna alternativa lo recoge. La ficha tiene una errata en las alternativas.", letters = "abcd", src = "ficha", group = "Semana 3 · Estadística", answer = "65,85 kg, que es 1317/20. Ninguna alternativa lo recoge.", answerVal = "1317/20", table = listOf(listOf("Peso (kg)", "Xi", "fi", "Fi", "hi", "Hi"), listOf("[48; 54)", "51", "2", "2", "2/40", "2/40"), listOf("[54; 60)", "57", "6", "8", "6/40", "8/40"), listOf("[60; 66)", "63", "14", "22", "14/40", "22/40"), listOf("[66; 72)", "69", "10", "32", "10/40", "32/40"), listOf("[72; 78)", "75", "5", "37", "5/40", "37/40"), listOf("[78; 84)", "81", "3", "40", "3/40", "40/40")), num = 4, review = true))
        l.add(BProb(id = "s3est_05", topic = "est", level = 1, text = "En un estudio sobre el peso (en kg) de 40 postulantes a una beca deportiva, se construyó la siguiente tabla de frecuencias agrupadas: (Responder desde el 1 al 5)\n[tabla]\nReste la frecuencia absoluta del cuarto intervalo a la frecuencia acumulada del tercer intervalo", opts = listOf("10", "12", "14", "16"), vals = listOf("10", "12", "14", "16"), correct = 1, check = "22-10", steps = listOf("Frecuencia acumulada del tercer intervalo: F3 = 22.", "Frecuencia absoluta del cuarto intervalo: f4 = 10.", "22 − 10 = 12."), theory = "En una tabla de frecuencias agrupadas: fi es la frecuencia absoluta, Fi la acumulada, hi la relativa y Hi la relativa acumulada. La marca de clase de un intervalo es el promedio de sus extremos. La media aproximada es la suma de marca por frecuencia dividida entre el total. Los porcentajes salen de dividir entre el total.", idea = "F3 es la acumulada del tercer intervalo y f4 la absoluta del cuarto.", mistake = "Usar f3 = 14 en lugar de F3 = 22.", verify = "F3 = 2 + 6 + 14 = 22.", letters = "abcd", src = "ficha", group = "Semana 3 · Estadística", table = listOf(listOf("Peso (kg)", "Xi", "fi", "Fi", "hi", "Hi"), listOf("[48; 54)", "51", "2", "2", "2/40", "2/40"), listOf("[54; 60)", "57", "6", "8", "6/40", "8/40"), listOf("[60; 66)", "63", "14", "22", "14/40", "22/40"), listOf("[66; 72)", "69", "10", "32", "10/40", "32/40"), listOf("[72; 78)", "75", "5", "37", "5/40", "37/40"), listOf("[78; 84)", "81", "3", "40", "3/40", "40/40")), num = 5))
        l.add(BProb(id = "s3est_06", topic = "est", level = 3, text = "En una distribución de ancho de clase constante, se tiene:\n[tabla]\nDetermine la suma de m + n + k.", opts = listOf("63", "65", "68", "72"), vals = listOf("63", "65", "68", "72"), correct = -1, check = "7+25+34", steps = listOf("Intervalos de ancho w: [16 − w; 16), [16; 16 + w), [16 + w; 16 + 2w) y [28; k]. Entonces 16 + 2w = 28, así que w = 6.", "Intervalos: [10; 16), [16; 22), [22; 28) y [28; 34]. Entonces k = 34.", "F1 = 5 y F2 = 12, así que m = 12 − 5 = 7.", "F4 = 30 y f4 = 10, así que F3 = 20 y f3 = 8. La marca del tercer intervalo es n = (22 + 28)/2 = 25.", "m + n + k = 7 + 25 + 34 = 66."), note = "Si el último intervalo se tomara como [28; 33], con enteros, la suma sería 65, alternativa b. Pero entonces la media de la pregunta 7 no coincidiría con ninguna alternativa. Es solo una hipótesis y la academia debe confirmarlo.", theory = "En una tabla de frecuencias agrupadas: fi es la frecuencia absoluta, Fi la acumulada, hi la relativa y Hi la relativa acumulada. La marca de clase de un intervalo es el promedio de sus extremos. La media aproximada es la suma de marca por frecuencia dividida entre el total. Los porcentajes salen de dividir entre el total. Si el ancho es constante, cada intervalo empieza donde termina el anterior.", idea = "Con el ancho w constante, el segundo intervalo es [16; 16 + w) y el cuarto empieza en 16 + 2w = 28.", mistake = "Olvidar que n es la marca de clase del tercer intervalo y usar su frecuencia, 8.", verify = "Las frecuencias 5, 7, 8 y 10 suman 30, el total. Con esos datos la media es 23,6, como en la pregunta 7.", warn = "Con la tabla tal cual, la suma es 66 y ninguna alternativa lo recoge. La ficha tiene una errata.", letters = "abcd", src = "ficha", group = "Semana 3 · Estadística", answer = "66. Ninguna alternativa lo recoge.", answerVal = "66", table = listOf(listOf("Ii", "Xi", "fi", "Fi"), listOf("[ ; )", "", "5", ""), listOf("[16; )", "", "m", "12"), listOf("[ ; )", "n", "", ""), listOf("[28; k]", "", "10", "30")), num = 6, review = true))
        l.add(BProb(id = "s3est_07", topic = "est", level = 2, text = "Del ejercicio anterior, calcule la media.", opts = listOf("23.2", "22.6", "23.6", "708"), vals = listOf("116/5", "113/5", "118/5", "708"), correct = 2, check = "(13*5+19*7+25*8+31*10)/30", steps = listOf("Marcas de clase: 13, 19, 25 y 31. Frecuencias: 5, 7, 8 y 10.", "Suma de marca por frecuencia: 65 + 133 + 200 + 310 = 708.", "Media: 708/30 = 23,6."), note = "Las alternativas se comprueban como fracciones: 23,2 es 116/5, 22,6 es 113/5 y 23,6 es 118/5.", theory = "En una tabla de frecuencias agrupadas: fi es la frecuencia absoluta, Fi la acumulada, hi la relativa y Hi la relativa acumulada. La marca de clase de un intervalo es el promedio de sus extremos. La media aproximada es la suma de marca por frecuencia dividida entre el total. Los porcentajes salen de dividir entre el total.", idea = "Se usa la tabla de la pregunta 6 completa.", mistake = "Responder 708, la suma sin dividir entre 30, alternativa d.", verify = "23,6 está entre 19 y 25, cerca de 25 por las frecuencias altas.", trap = "708", letters = "abcd", src = "ficha", group = "Semana 3 · Estadística", table = listOf(listOf("Ii", "Xi", "fi", "Fi"), listOf("[ ; )", "", "5", ""), listOf("[16; )", "", "m", "12"), listOf("[ ; )", "n", "", ""), listOf("[28; k]", "", "10", "30")), num = 7, trapOpt = 3))
