    private fun p32(l: MutableList<BProb>) {
        l.add(BProb(id = "s3est_18", topic = "prob", level = 1, text = "¿Cuántos códigos de 3 cifras significativas se pueden formar empleando los dígitos {1, 3, 5, 7, 9}?", opts = listOf("30", "60", "120", "125"), vals = listOf("30", "60", "120", "125"), correct = 3, check = "5^3", steps = listOf("Cada una de las 3 posiciones tiene 5 opciones.", "5·5·5 = 125."), theory = "Principio de multiplicación: si hay m maneras de hacer una cosa y n de hacer otra, hay m·n maneras de hacer ambas. Un orden con n objetos distintos tiene n! maneras. Combinaciones: C(n, k) elige k de n sin importar el orden. Cuando se pueden repetir cifras, cada lugar tiene todas las opciones.", idea = "No se dice que las cifras sean distintas, así que se pueden repetir.", mistake = "Suponer que no se repiten y calcular 5·4·3 = 60, alternativa b.", verify = "5³ = 125.", trap = "5*4*3", letters = "abcd", src = "ficha", group = "Semana 3 · Estadística", num = 18, trapOpt = 1))
