        l.add(BProb(id = "s3est_20", topic = "prob", level = 1, text = "¿Cuántas palabras (con o sin sentido) se pueden formar con las letras de la palabra \"LUZ\"?", opts = listOf("3", "6", "9", "27"), vals = listOf("3", "6", "9", "27"), correct = 1, check = "3!", steps = listOf("Primera letra: 3 opciones. Segunda: 2. Tercera: 1.", "3·2·1 = 6."), theory = "Principio de multiplicación: si hay m maneras de hacer una cosa y n de hacer otra, hay m·n maneras de hacer ambas. Un orden con n objetos distintos tiene n! maneras. Combinaciones: C(n, k) elige k de n sin importar el orden.", idea = "Las tres letras son distintas y se usan todas.", mistake = "Calcular 3³ = 27, que permite repetir letras, alternativa d.", verify = "LUZ, LZU, ULZ, UZL, ZLU y ZUL.", trap = "3^3", letters = "abcd", src = "ficha", group = "Semana 3 · Estadística", num = 20, trapOpt = 3))
        l.add(BProb(id = "s3est_21", topic = "prob", level = 1, text = "Al lanzar dos dados, ¿De cuántas maneras me pueden salir dos números pares?", opts = listOf("3", "6", "9", "27"), vals = listOf("3", "6", "9", "27"), correct = 2, check = "3*3", steps = listOf("Primer dado: 3 pares. Segundo dado: 3 pares.", "3·3 = 9."), theory = "Principio de multiplicación: si hay m maneras de hacer una cosa y n de hacer otra, hay m·n maneras de hacer ambas. Un orden con n objetos distintos tiene n! maneras. Combinaciones: C(n, k) elige k de n sin importar el orden.", idea = "En un dado hay 3 números pares: 2, 4 y 6.", mistake = "Sumar 3 + 3 = 6, alternativa b.", verify = "(2,2), (2,4), (2,6), (4,2), …, (6,6): 9 pares.", trap = "3+3", letters = "abcd", src = "ficha", group = "Semana 3 · Estadística", num = 21, trapOpt = 1))
