        l.add(BProb(id = "s3est_29", topic = "est", level = 3, text = "Sea la siguiente tabla de frecuencias:\n[tabla]\nCalcule la suma de cifras de a+b+c", opts = listOf("44", "10", "8", "12"), vals = listOf("44", "10", "8", "12"), correct = 2, check = "iquo(18+2+24,10)+irem(18+2+24,10)", steps = listOf("Intervalos de ancho w: [12 − w; 12), [12; 12 + w), [12 + w; 12 + 2w) y [20; c]. Entonces 12 + 2w = 20 y w = 4.", "Intervalos: [8; 12), [12; 16), [16; 20) y [20; 24]. Entonces c = 24.", "F2 = 6 y f1 = 4, así que b = 6 − 4 = 2.", "a es la marca del tercer intervalo: (16 + 20)/2 = 18.", "a + b + c = 18 + 2 + 24 = 44. La suma de cifras de 44 es 4 + 4 = 8."), note = "Es el problema 4 de Las fijas del gran Sergio.", theory = "En una tabla de frecuencias agrupadas: fi es la frecuencia absoluta, Fi la acumulada, hi la relativa y Hi la relativa acumulada. La marca de clase de un intervalo es el promedio de sus extremos. La media aproximada es la suma de marca por frecuencia dividida entre el total. Los porcentajes salen de dividir entre el total. Si el ancho de clase es constante, cada intervalo empieza donde termina el anterior.", idea = "Con el ancho w, el cuarto intervalo empieza en 12 + 2w = 20.", mistake = "Responder 44, alternativa a, que es a + b + c y no la suma de sus cifras.", verify = "Las frecuencias son 4, 2, 6 y 8, que suman 20, la última acumulada.", trap = "44", letters = "abcd", src = "ficha", group = "Semana 3 · Estadística", table = listOf(listOf("Ii", "Xi", "fi", "Fi"), listOf("[ ; )", "", "4", ""), listOf("[12; )", "", "b", "6"), listOf("[ ; )", "a", "", ""), listOf("[20; c ]", "", "8", "20")), num = 29, trapOpt = 0))
