        l.add(BProb(id = "s4arit_20", topic = "porc", level = 3, text = "Si \"A\" aumenta en 10% y \"B\" aumenta en 20% entonces\n§((3*A^3)*(2*B))/5\n, se incrementa aproximadamente en:", opts = listOf("140%", "145%", "150%", "152%", "60%"), vals = listOf("140", "145", "150", "152", "60"), correct = 4, check = "round(((11/10)^3*(12/10)-1)*100)", steps = listOf("A se multiplica por 1,1, así que A³ se multiplica por 1,331.", "B se multiplica por 1,2.", "La expresión se multiplica por 1,331 · 1,2 = 1,5972.", "Aumenta aproximadamente 60%."), theory = "Un porcentaje r% de una cantidad es r/100 de ella. Un aumento de r% multiplica por 1 + r/100 y un descuento de r% multiplica por 1 − r/100. Los aumentos y descuentos sucesivos se multiplican, no se suman.", idea = "La expresión es proporcional a A³ por B: los números 3, 2 y 5 no cambian.", mistake = "Sumar 3 · 10% + 20% = 50% y marcar 150%, alternativa c.", verify = "1,5972 − 1 = 0,5972, que es 59,72%, cerca de 60%.", trap = "150", letters = "abcde", src = "ficha", group = "Semana 4 · Aritmética", num = 20, trapOpt = 2))
        l.add(BProb(id = "s4arit_21", topic = "porc", level = 3, text = "En una reunión el 60% del número de hombres es igual al 20% del número de mujeres. ¿Qué porcentaje del total son hombres?", opts = listOf("40%", "25%", "30%", "15%", "75%"), vals = listOf("40", "25", "30", "15", "75"), correct = 1, check = "1/(1+solve(60/100*1=20/100*M,M)[0])*100", steps = listOf("0,6H = 0,2M, así que M = 3H.", "Total: H + 3H = 4H.", "Hombres: H/4H = 25%."), theory = "Un porcentaje r% de una cantidad es r/100 de ella. Un aumento de r% multiplica por 1 + r/100 y un descuento de r% multiplica por 1 − r/100. Los aumentos y descuentos sucesivos se multiplican, no se suman.", idea = "Se escribe el número de mujeres en función del de hombres.", mistake = "Dividir H entre M y obtener 33%.", verify = "Con H = 10 y M = 30: 6 = 6 y 10/40 = 25%.", letters = "abcde", src = "ficha", group = "Semana 4 · Aritmética", num = 21))
        l.add(BProb(id = "s4arit_22", topic = "porc", level = 2, text = "En una granja de aves, el 40% es de gallinas. Si se ha vendido el 205 de gallinas. ¿En qué porcentaje ha disminuido el número de aves?", opts = listOf("10%", "6%", "8%", "12%", "7%"), vals = listOf("10", "6", "8", "12", "7"), correct = 2, check = "(20/100*40/100)*100", steps = listOf("Se vende el 20% de las gallinas: 20% de 40% = 8% del total.", "Las aves disminuyen 8%."), note = "Es muy probable que el 205 sea 20%. La academia debe confirmarlo.", theory = "Un porcentaje r% de una cantidad es r/100 de ella. Un aumento de r% multiplica por 1 + r/100 y un descuento de r% multiplica por 1 − r/100. Los aumentos y descuentos sucesivos se multiplican, no se suman.", idea = "Las gallinas son 40% del total y se vende una parte de ellas.", mistake = "Tomar el 20% del total de aves, y no de las gallinas.", verify = "Con 100 aves: 40 gallinas, se venden 8. Quedan 92.", warn = "La ficha dice el 205 de gallinas, que no tiene sentido. Se entiende el 20%, con el que el resultado coincide con la alternativa c.", letters = "abcde", src = "ficha", group = "Semana 4 · Aritmética", num = 22, review = true))
        l.add(BProb(id = "s4arit_23", topic = "porc", level = 3, text = "En una compañía trabajan 160 personas donde el 25% son mujeres. ¿Cuántas mujeres deben controlarse para que el 40% del personal sea de mujeres?", opts = listOf("60", "80", "25", "30", "40"), vals = listOf("60", "80", "25", "30", "40"), correct = 4, check = "solve((40+x)/(160+x)=40/100,x)[0]", steps = listOf("Mujeres actuales: 25% de 160 = 40.", "Con x mujeres más, el total es 160 + x y las mujeres 40 + x.", "(40 + x)/(160 + x) = 0,4 da 40 + x = 64 + 0,4x, es decir 0,6x = 24 y x = 40."), note = "Controlarse parece una errata de contratarse. Si en lugar de sumar se cambiaran hombres por mujeres, el total seguiría en 160 y harían falta 24 mujeres, que no está entre las alternativas.", theory = "Un porcentaje r% de una cantidad es r/100 de ella. Un aumento de r% multiplica por 1 + r/100 y un descuento de r% multiplica por 1 − r/100. Los aumentos y descuentos sucesivos se multiplican, no se suman.", idea = "Se entiende que se suman mujeres al personal, así que el total también crece.", mistake = "Mantener el total en 160 y obtener 24 mujeres, que no está entre las alternativas.", verify = "Con x = 40: 80 de 200 personas, que es 40%.", letters = "abcde", src = "ficha", group = "Semana 4 · Aritmética", num = 23, review = true))
        l.add(BProb(id = "s4arit_24", topic = "porc", level = 3, text = "En una granja el 25% del total de animales son pollos, el 30% son conejos y los restantes cuyes. Si el número de pollos fuera el doble. ¿Qué porcentaje del total serán los cuyes?", opts = listOf("24%", "36%", "40%", "48%", "54%"), vals = listOf("24", "36", "40", "48", "54"), correct = 1, check = "45/(2*25+30+45)*100", steps = listOf("Con 100 animales: 25 pollos, 30 conejos y 45 cuyes.", "Con el doble de pollos: 50 pollos, 30 conejos y 45 cuyes. Total 125.", "Cuyes: 45/125 = 36%."), theory = "Un porcentaje r% de una cantidad es r/100 de ella. Un aumento de r% multiplica por 1 + r/100 y un descuento de r% multiplica por 1 − r/100. Los aumentos y descuentos sucesivos se multiplican, no se suman.", idea = "Cuyes son 100% − 25% − 30% = 45%. Si los pollos se duplican, el total cambia.", mistake = "Dejar el total en 100 y responder 45%, que no está entre las alternativas.", verify = "45/125 = 0,36.", letters = "abcde", src = "ficha", group = "Semana 4 · Aritmética", num = 24))
        l.add(BProb(id = "s4arit_25", topic = "porc", level = 3, text = "Si Juan pierde el 40% del dinero que tiene y luego gana el 50% de lo que le queda estaría perdiendo S/. 57 800. ¿Cuánto tenía Juan?", opts = listOf("S/. 578 000", "520 000", "600 000", "N.A.", "480 000"), vals = listOf("578000", "520000", "600000", "undef", "480000"), correct = 0, check = "solve(60/100*X*(1+50/100)-X=-57800,X)[0]", steps = listOf("Después de perder 40%: 0,6X.", "Gana 50% de 0,6X: 0,9X en total.", "Pierde 0,1X = 57 800, así que X = 578 000."), theory = "Un porcentaje r% de una cantidad es r/100 de ella. Un aumento de r% multiplica por 1 + r/100 y un descuento de r% multiplica por 1 − r/100. Los aumentos y descuentos sucesivos se multiplican, no se suman.", idea = "Se sigue lo que pasa con el dinero X: queda 60%, luego sube 50%.", mistake = "Calcular 57 800 · 10 = 578 000 sin ver que el 10% viene de 0,9.", verify = "0,9 · 578 000 = 520 200 y 578 000 − 520 200 = 57 800.", letters = "abcde", src = "ficha", group = "Semana 4 · Aritmética", num = 25))
        l.add(BProb(id = "s4arit_26", topic = "porc", level = 2, text = "Un objeto se ofrece con el 20% de recargo y luego se descuenta el 20% por factura. El descuento es del:", opts = listOf("0%", "5%", "6%", "4%", "10%"), vals = listOf("0", "5", "6", "4", "10"), correct = 3, check = "(1-(12/10)*(8/10))*100", steps = listOf("Factor: 1,2 · 0,8 = 0,96.", "El precio final es 96% del original: 4% menos."), note = "El descuento neto se mide respecto al precio original. El descuento se aplica sobre el precio con recargo.", theory = "Un porcentaje r% de una cantidad es r/100 de ella. Un aumento de r% multiplica por 1 + r/100 y un descuento de r% multiplica por 1 − r/100. Los aumentos y descuentos sucesivos se multiplican, no se suman.", idea = "Un recargo de 20% multiplica por 1,2 y un descuento de 20% por 0,8.", mistake = "Pensar que 20% − 20% = 0% y marcar la alternativa a.", verify = "Con 100: 120 y luego 96.", trap = "0", letters = "abcde", src = "ficha", group = "Semana 4 · Aritmética", num = 26, trapOpt = 0))
    }
    private fun p45(l: MutableList<BProb>) {
        l.add(BProb(id = "s4arit_27", topic = "porc", level = 1, text = "Un comerciante compró una bicicleta a 1200 soles y lo vendió ganando el 20% del costo. ¿A cuánto la vendió?", opts = listOf("S/. 1440", "S/. 1400", "S/. 1300", "S/. 1700", "N.A."), vals = listOf("1440", "1400", "1300", "1700", "undef"), correct = 0, check = "1200*(1+20/100)", steps = listOf("Ganancia: 20% de 1200 = 240.", "Precio de venta: 1200 + 240 = 1440."), theory = "Un porcentaje r% de una cantidad es r/100 de ella. Un aumento de r% multiplica por 1 + r/100 y un descuento de r% multiplica por 1 − r/100. Los aumentos y descuentos sucesivos se multiplican, no se suman. Precio de venta = costo + ganancia. Una ganancia sobre el costo se calcula con el costo, y sobre el precio de venta, con el precio de venta.", idea = "La ganancia es 20% del costo.", mistake = "Responder solo la ganancia, 240.", verify = "1200 · 1,2 = 1440.", letters = "abcde", src = "ficha", group = "Semana 4 · Aritmética", num = 27))
        l.add(BProb(id = "s4arit_28", topic = "porc", level = 2, text = "Un libro que costo 140 soles se vende ganando el 20% del precio de venta. ¿En cuánto se vendió?", opts = listOf("S/. 150", "S/. 180", "S/. 200", "S/. 175", "S/. 130"), vals = listOf("150", "180", "200", "175", "130"), correct = 3, check = "solve(PV-140=20/100*PV,PV)[0]", steps = listOf("Sea PV el precio de venta. Ganancia: PV − 140 = 0,2PV.", "0,8PV = 140, así que PV = 175."), theory = "Un porcentaje r% de una cantidad es r/100 de ella. Un aumento de r% multiplica por 1 + r/100 y un descuento de r% multiplica por 1 − r/100. Los aumentos y descuentos sucesivos se multiplican, no se suman. Precio de venta = costo + ganancia. Una ganancia sobre el costo se calcula con el costo, y sobre el precio de venta, con el precio de venta.", idea = "La ganancia es el 20% del precio de venta, no del costo.", mistake = "Calcular 20% de 140 y obtener 168, que no está.", verify = "175 − 140 = 35 y 35 es el 20% de 175.", letters = "abcde", src = "ficha", group = "Semana 4 · Aritmética", num = 28))
        l.add(BProb(id = "s4arit_29", topic = "porc", level = 3, text = "Un comerciante vende las dos últimas bicicletas que le quedan en S/. 1200 cada una. En una ganó el 25% en la otra perdió el 25% ¿qué afirmación es correcta?", opts = listOf("no gano ni perdió", "ganó S/. 160", "perdió S/. 160", "perdió S/. 200", "N.A."), vals = listOf("0", "160", "-160", "-200", "undef"), correct = 2, check = "1200+1200-(1200/(1+25/100)+1200/(1-25/100))", steps = listOf("La que ganó 25%: 1200 = 1,25 · costo, así que el costo fue 960.", "La que perdió 25%: 1200 = 0,75 · costo, así que el costo fue 1600.", "Costo total: 2560. Ventas: 2400. Perdió 160."), theory = "Un porcentaje r% de una cantidad es r/100 de ella. Un aumento de r% multiplica por 1 + r/100 y un descuento de r% multiplica por 1 − r/100. Los aumentos y descuentos sucesivos se multiplican, no se suman. Precio de venta = costo + ganancia. Una ganancia sobre el costo se calcula con el costo, y sobre el precio de venta, con el precio de venta.", idea = "Cada porcentaje es del costo de esa bicicleta, que es distinto en cada una.", mistake = "Pensar que 25% − 25% = 0 y marcar la alternativa a.", verify = "960 + 1600 = 2560 y 2560 − 2400 = 160.", letters = "abcde", src = "ficha", group = "Semana 4 · Aritmética", num = 29))
        l.add(BProb(id = "s4arit_30", topic = "porc", level = 3, text = "Un artículo se ha vendido en S/. 5400 donde se está ganando el 35% del costo. ¿A cómo se debió vender el mismo artículo para ganar el 20% del precio de venta?", opts = listOf("S/. 4000", "S/. 3500", "S/. 4500", "S/. 4800", "S/. 5000"), vals = listOf("4000", "3500", "4500", "4800", "5000"), correct = 4, check = "(5400/(1+35/100))/(1-20/100)", steps = listOf("Costo: 5400 = 1,35 · costo, así que costo = 4000.", "Con ganancia de 20% del precio de venta: PV − 4000 = 0,2PV, es decir 0,8PV = 4000.", "PV = 5000."), theory = "Un porcentaje r% de una cantidad es r/100 de ella. Un aumento de r% multiplica por 1 + r/100 y un descuento de r% multiplica por 1 − r/100. Los aumentos y descuentos sucesivos se multiplican, no se suman. Precio de venta = costo + ganancia. Una ganancia sobre el costo se calcula con el costo, y sobre el precio de venta, con el precio de venta.", idea = "Primero se halla el costo y luego el nuevo precio.", mistake = "Responder el costo, 4000, alternativa a, que no incluye ninguna ganancia.", verify = "5000 − 4000 = 1000, que es 20% de 5000.", trap = "4000", letters = "abcde", src = "ficha", group = "Semana 4 · Aritmética", num = 30, trapOpt = 0))
        l.add(BProb(id = "s4est_01", topic = "prob", level = 1, text = "¿Cuál es la probabilidad de obtener dos sellos en el lanzamiento de tres monedas?", opts = listOf("S/ 242", "S/ 252", "S/ 258", "S/ 260"), vals = listOf("242", "252", "258", "260"), correct = -1, check = "binomial(3,2)/8", steps = listOf("Resultados posibles: 2·2·2 = 8.", "Con exactamente dos sellos: C(3, 2) = 3 resultados: SSC, SCS y CSS.", "Probabilidad: 3/8."), note = "Si fuera al menos dos sellos, la probabilidad sería 4/8 = 1/2.", theory = "Probabilidad de un suceso: casos favorables entre casos posibles, cuando todos son igual de probables. Si dos sucesos son independientes, la probabilidad de que ocurran ambos es el producto. La probabilidad de al menos uno se calcula como 1 menos la probabilidad de que no ocurra ninguno.", idea = "Hay 8 resultados posibles al lanzar tres monedas.", mistake = "Elegir una alternativa en soles por no saber cuál usar.", verify = "3/8 = 0,375.", warn = "Con el enunciado tal cual, la respuesta es 3/8. Las alternativas están en soles, que no tiene sentido para una probabilidad, y ninguna recoge 3/8. La ficha tiene una errata.", letters = "abcd", src = "ficha", group = "Semana 4 · Estadística", answer = "3/8. Las alternativas están en soles y no corresponden a una probabilidad.", answerVal = "3/8", num = 1, review = true))
        l.add(BProb(id = "s4est_02", topic = "prob", level = 2, text = "Al lanzar dos dados convencionales, ¿cuál es la probabilidad de que la suma de sus puntos sea un número primo?", opts = listOf("5/12", "7/18", "1/3", "15/36"), vals = listOf("5/12", "7/18", "1/3", "15/36"), correct = 0, check = "(1+2+4+6+2)/36", steps = listOf("Suma 2: 1 forma. Suma 3: 2. Suma 5: 4. Suma 7: 6. Suma 11: 2.", "Casos favorables: 1 + 2 + 4 + 6 + 2 = 15 de 36.", "15/36 = 5/12."), note = "En la app se califican como correctas las dos alternativas.", theory = "Probabilidad de un suceso: casos favorables entre casos posibles, cuando todos son igual de probables. Si dos sucesos son independientes, la probabilidad de que ocurran ambos es el producto. La probabilidad de al menos uno se calcula como 1 menos la probabilidad de que no ocurra ninguno. Los números primos hasta 12 son 2, 3, 5, 7 y 11.", idea = "Se cuentan las formas de obtener cada suma prima.", mistake = "Contar las sumas primas sin ponderar por sus formas: 5 sumas de 11 posibles.", verify = "15/36 se simplifica dividiendo entre 3.", warn = "Las alternativas a y d valen lo mismo: 5/12 es igual a 15/36. Las dos son correctas.", letters = "abcd", src = "ficha", group = "Semana 4 · Estadística", num = 2, alsoRight = listOf(3), review = true))
        l.add(BProb(id = "s4est_03", topic = "prob", level = 1, text = "Se lanzan dos dados, ¿cuál es la probabilidad de obtener una suma menor que 6?", opts = listOf("5/18", "7/36", "5/36", "1/4"), vals = listOf("5/18", "7/36", "5/36", "1/4"), correct = 0, check = "(1+2+3+4)/36", steps = listOf("Suma 2: 1 forma. Suma 3: 2. Suma 4: 3. Suma 5: 4.", "Casos favorables: 10 de 36.", "10/36 = 5/18."), theory = "Probabilidad de un suceso: casos favorables entre casos posibles, cuando todos son igual de probables. Si dos sucesos son independientes, la probabilidad de que ocurran ambos es el producto. La probabilidad de al menos uno se calcula como 1 menos la probabilidad de que no ocurra ninguno.", idea = "Las sumas menores que 6 son 2, 3, 4 y 5.", mistake = "Contar solo 4 sumas distintas y obtener 4/36.", verify = "10/36 ≈ 0,278.", letters = "abcd", src = "ficha", group = "Semana 4 · Estadística", num = 3))
        l.add(BProb(id = "s4est_04", topic = "prob", level = 1, text = "De una baraja de 52 cartas se extrae una al azar. ¿Cuál es la probabilidad de que sea una figura (J, Q o K) de color negro?", opts = listOf("3/13", "6/13", "3/26", "1/26"), vals = listOf("3/13", "6/13", "3/26", "1/26"), correct = 2, check = "6/52", steps = listOf("Palos negros: 2. Figuras por palo: 3.", "Casos favorables: 2·3 = 6 de 52.", "6/52 = 3/26."), theory = "Probabilidad de un suceso: casos favorables entre casos posibles, cuando todos son igual de probables. Si dos sucesos son independientes, la probabilidad de que ocurran ambos es el producto. La probabilidad de al menos uno se calcula como 1 menos la probabilidad de que no ocurra ninguno.", idea = "Hay 4 palos: 2 negros y 2 rojos. Cada palo tiene 3 figuras J, Q y K.", mistake = "Contar las 12 figuras y obtener 12/52 = 3/13, alternativa a.", verify = "3/26 ≈ 0,115.", trap = "12/52", letters = "abcd", src = "ficha", group = "Semana 4 · Estadística", num = 4, trapOpt = 0))
    }
    private fun p46(l: MutableList<BProb>) {
        l.add(BProb(id = "s4est_05", topic = "prob", level = 2, text = "Una urna contiene tarjetas numeradas del 12 al 35 inclusive. Si se extrae una tarjeta al azar, ¿cuál es la probabilidad de que su suma de cifras sea un número impar?", opts = listOf("1/2", "11/24", "13/24", "7/12"), vals = listOf("1/2", "11/24", "13/24", "7/12"), correct = 0, check = "size(select(n->irem(iquo(n,10)+irem(n,10),2)==1,seq(n,n,12,35)))/(35-12+1)", steps = listOf("Del 12 al 19: 12, 14, 16 y 18, 4 números.", "Del 20 al 29: 21, 23, 25, 27 y 29, 5 números.", "Del 30 al 35: 30, 32 y 34, 3 números.", "Casos favorables: 4 + 5 + 3 = 12 de 24. Probabilidad 1/2."), theory = "Probabilidad de un suceso: casos favorables entre casos posibles, cuando todos son igual de probables. Si dos sucesos son independientes, la probabilidad de que ocurran ambos es el producto. La probabilidad de al menos uno se calcula como 1 menos la probabilidad de que no ocurra ninguno.", idea = "Hay 35 − 12 + 1 = 24 tarjetas. Se cuentan las de suma de cifras impar.", mistake = "Contar mal una decena y obtener 11/24 o 13/24.", verify = "En cada decena se alternan pares e impares de suma de cifras.", letters = "abcd", src = "ficha", group = "Semana 4 · Estadística", num = 5))
        l.add(BProb(id = "s4est_06", topic = "prob", level = 1, text = "Marina tiene tres frascos con caramelos que solo se distinguen por el color.\nFrasco 1: 6 rojos, 7 verdes y 5 blancos\nFrasco 2: 7 rojos, 1 verde y 1 blanco\nFrasco 3: 1 verde, 1 rojo y 10 blancos\nSi se une el contenido de los tres frascos en un frasco nuevo y se extrae al azar un caramelo de dicho frasco, ¿cuál de las afirmaciones es correcta?", opts = listOf("Es posible obtener un caramelo azul", "Es seguro obtener un caramelo blanco", "Es posible obtener un caramelo verde", "Es imposible obtener un caramelo verde"), vals = listOf("false", "false", "(7+1+1>0)", "(7+1+1==0)"), correct = 2, check = "true", steps = listOf("Verdes: 7 + 1 + 1 = 9. Hay, así que sacar uno verde es posible.", "Blancos: 5 + 1 + 10 = 16, pero también hay rojos y verdes: no es seguro.", "Azules: no hay ninguno, así que sacar uno azul es imposible."), note = "Las alternativas se comprueban como afirmaciones: solo la c es verdadera.", theory = "Un suceso es seguro si tiene probabilidad 1, imposible si tiene probabilidad 0 y posible si está entre 0 y 1.", idea = "Se mira si hay caramelos de cada color en el frasco nuevo.", mistake = "Elegir la b porque los blancos son la mayoría. Mayoría no es lo mismo que seguro.", verify = "Total de caramelos: 18 + 9 + 12 = 39, con rojos 14, verdes 9 y blancos 16.", letters = "abcd", src = "ficha", group = "Semana 4 · Estadística", num = 6))
        l.add(BProb(id = "s4est_07", topic = "prob", level = 1, text = "Una perrita tiene una camada de 4 cachorros. ¿Cuál es la probabilidad de que nazcan exactamente tres machos?", opts = listOf("1/2", "5/16", "1/4", "3/8"), vals = listOf("1/2", "5/16", "1/4", "3/8"), correct = 2, check = "binomial(4,3)/2^4", steps = listOf("Con exactamente tres machos: C(4, 3) = 4 combinaciones.", "Probabilidad: 4/16 = 1/4."), theory = "Probabilidad de un suceso: casos favorables entre casos posibles, cuando todos son igual de probables. Si dos sucesos son independientes, la probabilidad de que ocurran ambos es el producto. La probabilidad de al menos uno se calcula como 1 menos la probabilidad de que no ocurra ninguno.", idea = "Cada cachorro es macho o hembra con igual probabilidad. Hay 2⁴ = 16 combinaciones.", mistake = "Calcular 3/4, la fracción de machos, sin considerar todas las combinaciones.", verify = "Las combinaciones son MMMH, MMHM, MHMM y HMMM.", letters = "abcd", src = "ficha", group = "Semana 4 · Estadística", num = 7))
        l.add(BProb(id = "s4est_08", topic = "prob", level = 2, text = "En un salón de 50 alumnos, 35 postulan a San Marcos y 25 a la UNI. Si 10 postulan a ambas, ¿cuál es la probabilidad de que al elegir un alumno al azar postule solo a una de ellas?", opts = listOf("2/5", "3/5", "1/2", "3/10"), vals = listOf("2/5", "3/5", "1/2", "3/10"), correct = -1, check = "((35-10)+(25-10))/50", steps = listOf("Solo San Marcos: 35 − 10 = 25. Solo la UNI: 25 − 10 = 15.", "Solo una universidad: 25 + 15 = 40 alumnos de 50.", "Probabilidad: 40/50 = 4/5."), theory = "Probabilidad de un suceso: casos favorables entre casos posibles, cuando todos son igual de probables. Si dos sucesos son independientes, la probabilidad de que ocurran ambos es el producto. La probabilidad de al menos uno se calcula como 1 menos la probabilidad de que no ocurra ninguno. Para dos conjuntos: solo uno = total de cada uno menos la parte común.", idea = "Se restan los que postulan a ambas de cada grupo.", mistake = "Marcar 3/5 o 3/10 por parecerse a los datos. Con estos datos todos los alumnos postulan a alguna universidad.", verify = "Los que postulan a alguna: 35 + 25 − 10 = 50, todo el salón.", warn = "Con el enunciado tal cual, la probabilidad es 4/5 y ninguna alternativa lo recoge. La ficha tiene una errata.", letters = "abcd", src = "ficha", group = "Semana 4 · Estadística", answer = "4/5. Ninguna alternativa lo recoge.", answerVal = "4/5", num = 8, review = true))
        l.add(BProb(id = "s4est_09", topic = "prob", level = 3, text = "En un instituto superior, el 60% de los estudiantes son varones. De las mujeres, el 30% estudia becadas, mientras que de los varones el 40% estudia becados. Si se elige un estudiante al azar y resulta ser becado, ¿cuál es la probabilidad de que sea mujer?", opts = listOf("12/35", "18/35", "9/35", "9/27"), vals = listOf("12/35", "18/35", "9/35", "9/27"), correct = 3, check = "(4/10*3/10)/(4/10*3/10+6/10*4/10)", steps = listOf("Mujeres becadas: 40% · 30% = 12% del total.", "Varones becados: 60% · 40% = 24% del total.", "Becados: 12% + 24% = 36%. Entre ellos, mujeres: 12/36 = 1/3.", "9/27 = 1/3."), theory = "Probabilidad de un suceso: casos favorables entre casos posibles, cuando todos son igual de probables. Si dos sucesos son independientes, la probabilidad de que ocurran ambos es el producto. La probabilidad de al menos uno se calcula como 1 menos la probabilidad de que no ocurra ninguno. Probabilidad condicional: entre los becados, la parte que son mujeres.", idea = "Se calcula qué fracción del total son mujeres becadas y varones becados.", mistake = "Calcular 30% de 40% o dividir entre el total de estudiantes, y obtener 12%.", verify = "12/36 y 9/27 son la misma fracción, 1/3.", letters = "abcd", src = "ficha", group = "Semana 4 · Estadística", num = 9))
        l.add(BProb(id = "s4est_10", topic = "prob", level = 3, text = "Mía participa en un juego de la feria de su ciudad, en el cual se ofrece que todos reciban un premio. El juego consiste en sacar una bola de billar (numeradas del 1 al 15) de una canasta y escoger solo un premio de la siguiente tabla, según el número indicado en la bola de billar. Cada vez que Mía juega debe pagar S/ 5 por el ticket.\n[tabla]\nSegún esta información, ¿cuál de las siguientes afirmaciones es falsa?", opts = listOf("Es seguro que Mía reciba al menos S/ 20 si juega 10 veces.", "Es posible que Mía pierda S/ 3 en una jugada.", "Es imposible que Mía gane S/ 1 000 en una jugada.", "Es seguro que Mía reclame S/ 1 de premio como mínimo en una jugada."), vals = listOf("not(10*min(seq(max(when((irem(n,2)==0 and n<8) or (irem(n,2)==1 and n>7),1,0),when(n>6,2,0),when(irem(n,2)==1 and n<9,8,0),when(irem(n,2)==0 and n>14,1000,0)),n,1,15))>=20)", "not(size(select(v->v==2,seq(max(when((irem(n,2)==0 and n<8) or (irem(n,2)==1 and n>7),1,0),when(n>6,2,0),when(irem(n,2)==1 and n<9,8,0),when(irem(n,2)==0 and n>14,1000,0)),n,1,15)))>0)", "not(size(select(v->v==1000,seq(max(when((irem(n,2)==0 and n<8) or (irem(n,2)==1 and n>7),1,0),when(n>6,2,0),when(irem(n,2)==1 and n<9,8,0),when(irem(n,2)==0 and n>14,1000,0)),n,1,15)))==0)", "not(min(seq(max(when((irem(n,2)==0 and n<8) or (irem(n,2)==1 and n>7),1,0),when(n>6,2,0),when(irem(n,2)==1 and n<9,8,0),when(irem(n,2)==0 and n>14,1000,0)),n,1,15))>=1)"), correct = 0, check = "true", steps = listOf("Premio S/ 1: pares menores que 8 e impares mayores que 7. Premio S/ 2: números mayores que 6. Premio S/ 8: impares menores de 9. Premio S/ 1 000: pares mayores que 14, y no hay ninguno entre 1 y 15.", "Con las bolas 2, 4 y 6 el mejor premio es S/ 1. Entonces en 10 jugadas se puede ganar solo S/ 10, no 20. La afirmación a es falsa.", "La b es verdadera: con la bola 8 se gana S/ 2 y se pierde S/ 3. La c es verdadera: no hay bola par mayor que 14. La d es verdadera: toda bola da al menos S/ 1."), note = "Las alternativas se comprueban buscando cuál afirmación es falsa. Se supone que Mía reclama el mayor premio posible con cada bola.", theory = "Probabilidad de un suceso: casos favorables entre casos posibles, cuando todos son igual de probables. Si dos sucesos son independientes, la probabilidad de que ocurran ambos es el producto. La probabilidad de al menos uno se calcula como 1 menos la probabilidad de que no ocurra ninguno.", idea = "Se mira qué premio se puede reclamar con cada bola, del 1 al 15.", mistake = "Sumar S/ 2 por jugada y concluir que se ganan al menos S/ 20 en diez jugadas.", verify = "Los premios posibles por bola son 1, 2 u 8, y ninguno llega a 1000.", letters = "abcd", src = "ficha", group = "Semana 4 · Estadística", table = listOf(listOf("Resultado", "Premio"), listOf("Obtener un número par menor que 8 o impar mayor que 7", "S/ 1,00"), listOf("Obtener un número mayor que 6", "S/ 2,00"), listOf("Obtener un número impar menor de 9", "S/ 8,00"), listOf("Obtener un número par mayor a 14", "S/ 1 000,00")), num = 10))
        l.add(BProb(id = "s4est_11", topic = "prob", level = 2, text = "Se lanzan simultáneamente una moneda y dos dados. ¿Cuál es la probabilidad de obtener cara en la moneda y una suma de 7 en los dados?", opts = listOf("1/12", "1/24", "5/36", "1/6"), vals = listOf("1/12", "1/24", "5/36", "1/6"), correct = 0, check = "1/2*6/36", steps = listOf("Cara: 1/2.", "Suma 7 con dos dados: 6 de 36, es decir 1/6.", "Probabilidad: 1/2 · 1/6 = 1/12."), theory = "Probabilidad de un suceso: casos favorables entre casos posibles, cuando todos son igual de probables. Si dos sucesos son independientes, la probabilidad de que ocurran ambos es el producto. La probabilidad de al menos uno se calcula como 1 menos la probabilidad de que no ocurra ninguno.", idea = "La moneda y los dados son independientes: se multiplican las probabilidades.", mistake = "Sumar 1/2 + 1/6 en lugar de multiplicar.", verify = "1/12 ≈ 0,083.", letters = "abcd", src = "ficha", group = "Semana 4 · Estadística", num = 11))
        l.add(BProb(id = "s4est_12", topic = "prob", level = 2, text = "Si lanzamos 3 dados, ¿cuál es la probabilidad de obtener 4 como suma de puntos?", opts = listOf("1/216", "5/72", "5/216", "1/72"), vals = listOf("1/216", "5/72", "5/216", "1/72"), correct = 3, check = "3/216", steps = listOf("Resultados posibles: 6³ = 216.", "Combinaciones con suma 4: 1 + 1 + 2 en 3 órdenes: 112, 121 y 211.", "Probabilidad: 3/216 = 1/72."), theory = "Probabilidad de un suceso: casos favorables entre casos posibles, cuando todos son igual de probables. Si dos sucesos son independientes, la probabilidad de que ocurran ambos es el producto. La probabilidad de al menos uno se calcula como 1 menos la probabilidad de que no ocurra ninguno.", idea = "Con tres dados, la suma 4 solo se logra con 1, 1 y 2.", mistake = "Contar una sola combinación y obtener 1/216.", verify = "El mínimo de tres dados es 3, y 4 es la suma siguiente.", trap = "1/216", letters = "abcd", src = "ficha", group = "Semana 4 · Estadística", num = 12, trapOpt = 0))
