    private fun p47(l: MutableList<BProb>) {
        l.add(BProb(id = "s4est_13", topic = "prob", level = 1, text = "Una maestra realiza una actividad para recordar las propiedades de los números primos y probabilidades. Ella ha traído una bolsa que contiene tarjetas. Cada una de estas tarjetas tiene escrito solo uno de los siguientes números primos: 2, 3, 5, 7, 11, 13, 17, 19.\nLa maestra le pide a Dora que extraiga, al azar, una tarjeta de la bolsa.\nSegún esta información, ¿cuál es la probabilidad que Dora extraiga una tarjeta que contenga un número primo?", opts = listOf("7/8", "4/8", "1", "0"), vals = listOf("7/8", "4/8", "1", "0"), correct = 2, check = "8/8", steps = listOf("Hay 8 tarjetas y las 8 tienen un número primo.", "Casos favorables: 8 de 8. Probabilidad 1, que es un suceso seguro."), theory = "Probabilidad de un suceso: casos favorables entre casos posibles, cuando todos son igual de probables. Si dos sucesos son independientes, la probabilidad de que ocurran ambos es el producto. La probabilidad de al menos uno se calcula como 1 menos la probabilidad de que no ocurra ninguno.", idea = "Todas las tarjetas tienen números primos.", mistake = "Contar los números impares y obtener 7/8, por excluir el 2.", verify = "Ningún número de la lista es compuesto.", letters = "abcd", src = "ficha", group = "Semana 4 · Estadística", num = 13))
        l.add(BProb(id = "s4est_14", topic = "prob", level = 2, text = "¿Cuál es la probabilidad de que al ordenar en fila a 2 hombres y 2 mujeres, los 2 hombres estén juntos?", opts = listOf("3/4", "1/4", "1/3", "1/2"), vals = listOf("3/4", "1/4", "1/3", "1/2"), correct = 3, check = "(factorial(3)*factorial(2))/factorial(4)", steps = listOf("Total de ordenaciones de 4 personas: 4! = 24.", "Con los hombres juntos: el bloque y las dos mujeres se ordenan de 3! = 6 maneras, y los hombres entre sí de 2! = 2. Total 12.", "Probabilidad: 12/24 = 1/2."), theory = "Probabilidad de un suceso: casos favorables entre casos posibles, cuando todos son igual de probables. Si dos sucesos son independientes, la probabilidad de que ocurran ambos es el producto. La probabilidad de al menos uno se calcula como 1 menos la probabilidad de que no ocurra ninguno.", idea = "Los dos hombres juntos se cuentan como un bloque.", mistake = "Olvidar que los hombres se pueden ordenar entre sí y obtener 6/24 = 1/4.", verify = "Con letras HHMM hay 6 ordenaciones y 3 tienen los hombres juntos: HHMM, MHHM y MMHH.", letters = "abcd", src = "ficha", group = "Semana 4 · Estadística", num = 14))
        l.add(BProb(id = "s4est_15", topic = "prob", level = 2, text = "La probabilidad de que el futbolista más conocido como \"El comandante\" anote un gol al patear un penal es 0,9. ¿Cuál es la probabilidad de que anote por lo menos un gol al patear 2 penales?", opts = listOf("0,84", "0,9", "0,09", "0,99"), vals = listOf("84/100", "9/10", "9/100", "99/100"), correct = 3, check = "1-(1-9/10)^2", steps = listOf("Probabilidad de fallar un penal: 1 − 0,9 = 0,1.", "Fallar los dos: 0,1 · 0,1 = 0,01.", "Por lo menos un gol: 1 − 0,01 = 0,99."), note = "Las alternativas se comprueban como fracciones.", theory = "Probabilidad de un suceso: casos favorables entre casos posibles, cuando todos son igual de probables. Si dos sucesos son independientes, la probabilidad de que ocurran ambos es el producto. La probabilidad de al menos uno se calcula como 1 menos la probabilidad de que no ocurra ninguno.", idea = "Por lo menos un gol es lo contrario de fallar los dos.", mistake = "Responder 0,9, alternativa b, que es la probabilidad de un solo penal.", verify = "0,9 + 0,1·0,9 = 0,99.", trap = "9/10", letters = "abcd", src = "ficha", group = "Semana 4 · Estadística", num = 15, trapOpt = 1))
        l.add(BProb(id = "s4est_16", topic = "prob", level = 2, text = "El reconocido científico Hugo Heredia hizo una investigación sobre las virtudes que poseen cada hombre de Stone Bridge City, a través de una encuesta (virtudes indispensables según un grupo selecto de 1000 mujeres a nivel global), y descubrió lo siguiente:\na. Posee recursos económicos: 1 de cada 2 hombres.\nb. Es ambicioso y estudioso: 1 de cada 4 hombres.\nc. Le demuestra amor y compromiso: 1 de cada 2 hombres\nd. Es emocionalmente estable: 1 de cada 4 hombres\ne. Buena presencia y salud: 1 de cada 2 hombres\nResponder las preguntas 16, 17 y 18.\n¿Cuál es la probabilidad de que ella encuentre a su hombre ideal que cumpla todas las características?", opts = listOf("1 de cada 64 hombres", "1 de cada 128 hombres", "1 de cada 16 hombres", "Solo vive en Tik Tok"), vals = listOf("1/64", "1/128", "1/16", "undef"), correct = 1, check = "(1/2)*(1/4)*(1/2)*(1/4)*(1/2)", steps = listOf("Las cinco probabilidades son 1/2, 1/4, 1/2, 1/4 y 1/2.", "Producto: 1/2 · 1/4 · 1/2 · 1/4 · 1/2 = 1/128."), note = "El enunciado y las preguntas 16 a 18 son compartidos. La alternativa d es una broma de la ficha.", theory = "Probabilidad de un suceso: casos favorables entre casos posibles, cuando todos son igual de probables. Si dos sucesos son independientes, la probabilidad de que ocurran ambos es el producto. La probabilidad de al menos uno se calcula como 1 menos la probabilidad de que no ocurra ninguno.", idea = "Si las características son independientes, se multiplican las probabilidades de las cinco.", mistake = "Contar solo los incisos con 1/4 y obtener 1/16.", verify = "2·4·2·4·2 = 128.", letters = "abcd", src = "ficha", group = "Semana 4 · Estadística", num = 16))
        l.add(BProb(id = "s4est_17", topic = "prob", level = 2, text = "El reconocido científico Hugo Heredia hizo una investigación sobre las virtudes que poseen cada hombre de Stone Bridge City, a través de una encuesta (virtudes indispensables según un grupo selecto de 1000 mujeres a nivel global), y descubrió lo siguiente:\na. Posee recursos económicos: 1 de cada 2 hombres.\nb. Es ambicioso y estudioso: 1 de cada 4 hombres.\nc. Le demuestra amor y compromiso: 1 de cada 2 hombres\nd. Es emocionalmente estable: 1 de cada 4 hombres\ne. Buena presencia y salud: 1 de cada 2 hombres\nResponder las preguntas 16, 17 y 18.\nSi ella decide obviar el inciso c y d para tener mayores opciones, ¿cuál es la probabilidad de encontrar a un hombre compatible?", opts = listOf("1 de cada 64 hombres", "1 de cada 8 hombres", "1 de cada 16 hombres", "Regreso con mi ex"), vals = listOf("1/64", "1/8", "1/16", "undef"), correct = 2, check = "(1/2)*(1/4)*(1/2)", steps = listOf("Incisos a, b y e: 1/2, 1/4 y 1/2.", "Producto: 1/16."), theory = "Probabilidad de un suceso: casos favorables entre casos posibles, cuando todos son igual de probables. Si dos sucesos son independientes, la probabilidad de que ocurran ambos es el producto. La probabilidad de al menos uno se calcula como 1 menos la probabilidad de que no ocurra ninguno.", idea = "Se multiplican solo los incisos que quedan: a, b y e.", mistake = "Multiplicar también los incisos c y d y obtener 1/64, alternativa a.", verify = "2·4·2 = 16.", trap = "1/64", letters = "abcd", src = "ficha", group = "Semana 4 · Estadística", num = 17, trapOpt = 0))
        l.add(BProb(id = "s4est_18", topic = "prob", level = 2, text = "El reconocido científico Hugo Heredia hizo una investigación sobre las virtudes que poseen cada hombre de Stone Bridge City, a través de una encuesta (virtudes indispensables según un grupo selecto de 1000 mujeres a nivel global), y descubrió lo siguiente:\na. Posee recursos económicos: 1 de cada 2 hombres.\nb. Es ambicioso y estudioso: 1 de cada 4 hombres.\nc. Le demuestra amor y compromiso: 1 de cada 2 hombres\nd. Es emocionalmente estable: 1 de cada 4 hombres\ne. Buena presencia y salud: 1 de cada 2 hombres\nResponder las preguntas 16, 17 y 18.\nSi ella elige a un hombre que cumple con los incisos a,b y e, ¿cuál es la probabilidad de que este resulte ser su hombre ideal (cumple con todos los incisos)?", opts = listOf("Me quedo soltera", "1 de cada 8 hombres", "1 de cada 16 hombres", "1 de cada 4 hombres"), vals = listOf("undef", "1/8", "1/16", "1/4"), correct = 1, check = "(1/2)*(1/4)", steps = listOf("Faltan los incisos c y d: 1/2 y 1/4.", "Producto: 1/8."), theory = "Probabilidad de un suceso: casos favorables entre casos posibles, cuando todos son igual de probables. Si dos sucesos son independientes, la probabilidad de que ocurran ambos es el producto. La probabilidad de al menos uno se calcula como 1 menos la probabilidad de que no ocurra ninguno.", idea = "Ya cumple a, b y e. Solo faltan c y d.", mistake = "Multiplicar los cinco incisos otra vez y obtener 1/128.", verify = "2·4 = 8.", letters = "abcd", src = "ficha", group = "Semana 4 · Estadística", num = 18))
        l.add(BProb(id = "s4est_19", topic = "est", level = 2, text = "La edad promedio de 4 hermanos donde hay dos gemelos es 19 años, el menor tiene 12 años y el mayor tiene 24 años. ¿Cuál es la edad de los gemelos, en años?", opts = listOf("16", "19", "20", "21"), vals = listOf("16", "19", "20", "21"), correct = 2, check = "(4*19-12-24)/2", steps = listOf("Suma de las 4 edades: 4 · 19 = 76.", "El menor y el mayor suman 12 + 24 = 36. Los gemelos suman 76 − 36 = 40.", "Cada gemelo tiene 40/2 = 20 años."), theory = "Edad promedio: suma de las edades entre la cantidad de hermanos.", idea = "Se resta del total las edades conocidas.", mistake = "Responder 19, el promedio, alternativa b.", verify = "12 + 20 + 20 + 24 = 76 y 76/4 = 19.", trap = "19", letters = "abcd", src = "ficha", group = "Semana 4 · Estadística", num = 19, trapOpt = 1))
        l.add(BProb(id = "s4est_20", topic = "est", level = 2, text = "Siete compañeros de estudio asisten a una función de cine y adquieren diversas golosinas para consumir durante la película. Tres de ellos compran, cada uno, un combo económico de 13 soles que consiste en canchita y gaseosa. Otros dos consumen, cada uno, el mismo combo pero le agregan a cada combo un chocolate de 2 soles. Finalmente los últimos dos jóvenes comparten un combo gigante de 22 soles. Si cada entrada al cine tiene un costo de 15 soles, ¿cuál sería el gasto promedio total, en soles, por cada joven?", opts = listOf("13", "22", "28", "31"), vals = listOf("13", "22", "28", "31"), correct = 2, check = "(3*13+2*(13+2)+22+7*15)/7", steps = listOf("Tres combos económicos: 3 · 13 = 39.", "Dos combos con chocolate: 2 · (13 + 2) = 30.", "Un combo gigante compartido: 22.", "Entradas: 7 · 15 = 105.", "Gasto total: 39 + 30 + 22 + 105 = 196. Promedio: 196/7 = 28."), theory = "El gasto promedio por joven es el gasto total entre los 7 jóvenes.", idea = "Se suman todos los gastos, incluidas las entradas.", mistake = "Olvidar las entradas y obtener 13.", verify = "28 · 7 = 196.", trap = "(3*13+2*(13+2)+22)/7", letters = "abcd", src = "ficha", group = "Semana 4 · Estadística", num = 20, trapOpt = 0))
