    private fun p48(l: MutableList<BProb>) {
        l.add(BProb(id = "s4est_21", topic = "est", level = 2, text = "El gráfico muestra los niveles de exportación de cerveza, por marca, en el año 2017.\n¿Qué ángulo central correspondería a la marca \"Limeña\" si no se considera el rubro \"Otros\"?", opts = listOf("45°", "50°", "60°", "80°"), vals = listOf("45", "50", "60", "80"), correct = 3, check = "20/(100-10)*360", steps = listOf("Marcas sin Otros: 40% + 20% + 20% + 10% = 90%.", "Limeña es 20 de esos 90.", "Ángulo: 20/90 · 360° = 80°."), fig = "fe4_cerveza", theory = "En un gráfico circular, 360° corresponden al total que se considere.", idea = "Sin Otros, el total es el 90% de las exportaciones.", mistake = "Calcular 20% de 360° = 72°, que no está entre las alternativas, olvidando quitar Otros.", verify = "40 + 20 + 20 + 10 = 90, y 90 de 90 son 360°.", letters = "abcd", src = "ficha", group = "Semana 4 · Estadística", num = 21))
